@layer ui.tokens {
  :root {
    /* Shadcn Zinc Neutral Color Scale */
    --ui-zinc-50: #fafafa;
    --ui-zinc-100: #f4f4f5;
    --ui-zinc-200: #e4e4e7;
    --ui-zinc-300: #d4d4d8;
    --ui-zinc-400: #a1a1aa;
    --ui-zinc-500: #71717a;
    --ui-zinc-600: #52525b;
    --ui-zinc-700: #3f3f46;
    --ui-zinc-800: #27272a;
    --ui-zinc-900: #18181b;
    --ui-zinc-950: #09090b;

    /* Brand Color Scale (Default: Zinc) */
    --ui-color-brand-50: var(--ui-zinc-50);
    --ui-color-brand-100: var(--ui-zinc-100);
    --ui-color-brand-200: var(--ui-zinc-200);
    --ui-color-brand-300: var(--ui-zinc-300);
    --ui-color-brand-400: var(--ui-zinc-400);
    --ui-color-brand-500: var(--ui-zinc-500);
    --ui-color-brand-600: var(--ui-zinc-600);
    --ui-color-brand-700: var(--ui-zinc-700);
    --ui-color-brand-800: var(--ui-zinc-800);
    --ui-color-brand-900: var(--ui-zinc-900);
    --ui-color-brand-950: var(--ui-zinc-950);
    --ui-color-accent-400: #38bdf8;
    --ui-color-accent-500: #0ea5e9;

    --ui-color-success-500: #10b981;
    --ui-color-warning-500: #f97316;
    --ui-color-danger-500: #f43f5e;

    /* Semantic Defaults (Light Theme) */
    --ui-bg-canvas: #ffffff;
    --ui-bg-surface: #ffffff;
    --ui-bg-surface-elevated: #f4f4f5;
    --ui-bg-subtle: #f4f4f5;
    --ui-bg-hover: #e4e4e7;
    --ui-bg-active: #d4d4d8;

    --ui-text-primary: #09090b;
    --ui-text-secondary: #52525b;
    --ui-text-muted: #71717a;
    --ui-text-inverted: #fafafa;

    --ui-border-subtle: #f4f4f5;
    --ui-border-default: #e4e4e7;
    --ui-border-strong: #d4d4d8;
    --ui-border-focus: var(--ui-color-brand-600);
    --ui-focus-ring: color-mix(in srgb, var(--ui-color-brand-500) 25%, transparent);

    /* Canonical Convenience Aliases */
    --ui-bg: var(--ui-bg-canvas);
    --ui-text: var(--ui-text-primary);
    --ui-border: var(--ui-border-default);

    /* Typography */
    --ui-font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    --ui-font-mono: 'JetBrains Mono', 'Fira Code', monospace;
    --ui-font-size-xs: 0.75rem;
    --ui-font-size-sm: 0.875rem;
    --ui-font-size-base: 1rem;
    --ui-font-size-lg: 1.125rem;
    --ui-font-size-xl: 1.25rem;
    --ui-font-size-2xl: 1.5rem;
    --ui-font-size-3xl: 1.875rem;

    /* Spacing */
    --ui-space-1: 0.25rem;
    --ui-space-2: 0.5rem;
    --ui-space-3: 0.75rem;
    --ui-space-4: 1rem;
    --ui-space-5: 1.25rem;
    --ui-space-6: 1.5rem;
    --ui-space-8: 2rem;

    /* Radii */
    --ui-radius-sm: 0.375rem;
    --ui-radius-md: 0.5rem;
    --ui-radius-lg: 0.75rem;
    --ui-radius-xl: 1rem;
    --ui-radius-full: 9999px;

    /* Elevation & Shadows */
    --ui-shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --ui-shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
    --ui-shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.08);
    --ui-shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.12), 0 8px 10px -6px rgba(0, 0, 0, 0.08);
    --ui-shadow-popover: 0 12px 32px -4px rgba(15, 23, 42, 0.18), 0 4px 12px -2px rgba(15, 23, 42, 0.08);

    /* Glassmorphism */
    --ui-glass-bg: rgba(255, 255, 255, 0.82);
    --ui-glass-border: rgba(228, 228, 231, 0.8);
    --ui-glass-blur: blur(12px);

    /* Z-Index Hierarchy Scale */
    --ui-z-base: 0;
    --ui-z-dropdown: 1000;
    --ui-z-sticky: 1100;
    --ui-z-fixed: 1200;
    --ui-z-modal-backdrop: 1300;
    --ui-z-modal: 1350;
    --ui-z-popover: 1400;
    --ui-z-toast: 1500;
    --ui-z-tooltip: 1600;

    /* Motion & Spring Easing Curves */
