  }

  ui-data-table tbody tr,
  nnui-data-table tbody tr {
    content-visibility: auto;
    contain-intrinsic-size: 0 44px;
  }

  ui-data-table tr[hidden],
  nnui-data-table tr[hidden] {
    display: none !important;
  }

  ui-data-table [data-part="pagination"],
  nnui-data-table [data-part="pagination"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ui-space-4);
    padding: 0.5rem 0.25rem;
    flex-wrap: wrap;
  }

  ui-data-table [data-part="pagination-info"],
  nnui-data-table [data-part="pagination-info"] {
    font-size: var(--ui-font-size-xs);
    color: var(--ui-text-muted);
  }

  ui-data-table [data-part="pagination-buttons"],
  nnui-data-table [data-part="pagination-buttons"] {
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
  }

  /* =========================================================================
     Calendar Component (<ui-calendar>, <nnui-calendar>)
     ========================================================================= */
  ui-calendar,
  nnui-calendar,
  [data-ui="calendar"] {
    display: flex;
    flex-direction: column;
    width: 280px;
    max-width: 280px;
    min-width: 280px;
