    cursor: pointer;
    padding: 0;
    transition: all var(--ui-transition-fast);
  }

  ui-calendar [data-part="prev-month"]:hover,
  ui-calendar [data-part="next-month"]:hover,
  nnui-calendar [data-part="prev-month"]:hover,
