  /* =========================================================================
     Virtualized Data Grid (<ui-data-grid>, <nnui-data-grid>)
     ========================================================================= */
  ui-data-grid,
  nnui-data-grid,
  [data-ui="data-grid"] {
    display: flex;
    flex-direction: column;
    width: 100%;
    border: 1px solid var(--ui-border-default);
    border-radius: var(--ui-radius-lg);
    background: var(--ui-bg-surface);
    overflow: hidden;
    box-shadow: var(--ui-shadow-sm);
    position: relative;
  }

  ui-data-grid [data-part="toolbar"],
  [data-ui="data-grid"] [data-part="toolbar"],
  .grid-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1.25rem;
    border-bottom: 1px solid var(--ui-border-subtle);
    background: var(--ui-bg-subtle);
    gap: 0.75rem;
    flex-wrap: wrap;
    flex-shrink: 0;
  }

  .grid-toolbar:empty {
    display: none;
  }

  ui-data-grid [data-part="viewport"],
  [data-ui="data-grid"] [data-part="viewport"],
  .grid-viewport {
    position: relative;
    overflow-y: auto !important;
    overflow-x: auto;
    height: 480px;
    max-height: 70vh;
    will-change: scroll-position;
    width: 100%;
    background: var(--ui-bg-surface);
    flex: 1 1 auto;
    min-height: 240px;
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
  }

  ui-data-grid [data-part="viewport"]::-webkit-scrollbar,
  [data-ui="data-grid"] [data-part="viewport"]::-webkit-scrollbar,
  .grid-viewport::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }

  ui-data-grid [data-part="viewport"]::-webkit-scrollbar-track,
  [data-ui="data-grid"] [data-part="viewport"]::-webkit-scrollbar-track,
  .grid-viewport::-webkit-scrollbar-track {
    background: transparent;
  }

  ui-data-grid [data-part="viewport"]::-webkit-scrollbar-thumb,
  [data-ui="data-grid"] [data-part="viewport"]::-webkit-scrollbar-thumb,
  .grid-viewport::-webkit-scrollbar-thumb {
    background: var(--ui-border-strong);
    border-radius: 4px;
  }

  ui-data-grid [data-part="viewport"]::-webkit-scrollbar-thumb:hover,
  [data-ui="data-grid"] [data-part="viewport"]::-webkit-scrollbar-thumb:hover,
  .grid-viewport::-webkit-scrollbar-thumb:hover {
    background: var(--ui-text-muted);
  }

  ui-data-grid [data-part="runway"],
  [data-ui="data-grid"] [data-part="runway"],
  .grid-runway {
    position: relative;
    width: 100%;
    min-width: 100%;
    box-sizing: border-box;
  }

  ui-data-grid [data-part="grid-table"],
  [data-ui="data-grid"] [data-part="grid-table"],
  .grid-table {
    width: 100%;
    min-width: 100%;
    table-layout: fixed;
    border-collapse: separate;
    border-spacing: 0;
    text-align: left;
    font-size: 0.875rem;
  }

  ui-data-grid thead,
  .grid-table thead {
    position: sticky;
    top: 0;
    z-index: 10;
  }

  ui-data-grid th,
  .grid-table th {
    position: sticky;
    top: 0;
    z-index: 10;
    padding: 0.65rem 1rem;
    font-weight: 600;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--ui-text-muted);
    border-bottom: 1px solid var(--ui-border-default);
    white-space: nowrap;
    user-select: none;
    background: var(--ui-bg-surface-elevated, #18181b);
    backdrop-filter: blur(8px);
    transition: background var(--ui-transition-fast), color var(--ui-transition-fast);
  }

  ui-data-grid th:hover[data-sortable="true"],
  .grid-table th:hover[data-sortable="true"] {
    color: var(--ui-text-primary);
    background: var(--ui-bg-hover);
  }

  ui-data-grid th[aria-sort="ascending"],
  ui-data-grid th[aria-sort="descending"],
  .grid-table th[aria-sort="ascending"],
  .grid-table th[aria-sort="descending"] {
    color: var(--ui-color-primary-500);
  }

  .grid-sort-icon {
    display: inline-block;
    margin-left: 0.4rem;
    font-size: 0.75rem;
    opacity: 0.45;
    transition: opacity var(--ui-transition-fast), color var(--ui-transition-fast);
  }

  th:hover .grid-sort-icon {
    opacity: 0.85;
  }

  th[aria-sort="ascending"] .grid-sort-icon,
  th[aria-sort="descending"] .grid-sort-icon {
    opacity: 1;
    color: var(--ui-color-primary-500);
  }

  ui-data-grid td,
  .grid-table td {
    padding: 0.45rem 1rem;
    border-bottom: 1px solid var(--ui-border-subtle);
    color: var(--ui-text-secondary);
    white-space: nowrap;
    text-overflow: ellipsis;
    overflow: hidden;
    vertical-align: middle;
    font-variant-numeric: tabular-nums;
    transition: background var(--ui-transition-fast), color var(--ui-transition-fast);
  }

  ui-data-grid tr:hover:not(.grid-spacer) td,
  .grid-table tr:hover:not(.grid-spacer) td {
    background: var(--ui-bg-hover);
    color: var(--ui-text-primary);
  }

  ui-data-grid tr[data-selected="true"]:not(.grid-spacer) td,
  .grid-table tr[data-selected="true"]:not(.grid-spacer) td {
    background: color-mix(in srgb, var(--ui-color-brand-500) 12%, var(--ui-bg-surface)) !important;
    color: var(--ui-text-primary);
  }

  ui-data-grid tr[data-selected="true"]:not(.grid-spacer) td:first-child,
  .grid-table tr[data-selected="true"]:not(.grid-spacer) td:first-child {
    border-left: 3px solid var(--ui-color-brand-500);
  }

  ui-data-grid [data-part="virtual-tbody"],
  .grid-tbody {
    width: 100%;
  }

  .grid-table tr.grid-spacer,
  .grid-table tr.grid-spacer td,
  ui-data-grid tr.grid-spacer,
  ui-data-grid tr.grid-spacer td {
    padding: 0 !important;
    margin: 0 !important;
    border: none !important;
    line-height: 0 !important;
    font-size: 0 !important;
    background: transparent !important;
    pointer-events: none !important;
    user-select: none !important;
  }

  ui-data-grid [data-part="footer"],
  [data-ui="data-grid"] [data-part="footer"],
  .grid-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.65rem 1.25rem;
    border-top: 1px solid var(--ui-border-default);
    background: var(--ui-bg-subtle);
    flex-shrink: 0;
    position: relative;
    z-index: 5;
  }

  /* Polished Checkbox for Data Grid */
  ui-data-grid input[type="checkbox"],
  .grid-table input[type="checkbox"],
  .ui-checkbox {
    appearance: none;
    -webkit-appearance: none;
    width: 1.125rem;
    height: 1.125rem;
    border-radius: var(--ui-radius-sm, 4px);
    background-color: var(--ui-bg-surface);
    border: 1px solid var(--ui-border-default);
    cursor: pointer;
    display: inline-grid;
    place-content: center;
    margin: 0 auto;
    vertical-align: middle;
    transition: all var(--ui-transition-fast);
  }

  ui-data-grid input[type="checkbox"]::before,
  .grid-table input[type="checkbox"]::before,
  .ui-checkbox::before {
    content: '✓';
    font-size: 0.75rem;
    font-weight: 700;
    line-height: 1;
    color: var(--ui-text-inverted, #ffffff);
    transform: scale(0);
    transition: transform var(--ui-transition-fast);
  }

  ui-data-grid input[type="checkbox"]:checked,
  .grid-table input[type="checkbox"]:checked,
  .ui-checkbox:checked {
    background-color: var(--ui-color-brand-600);
    border-color: var(--ui-color-brand-600);
  }

  ui-data-grid input[type="checkbox"]:checked::before,
  .grid-table input[type="checkbox"]:checked::before,
  .ui-checkbox:checked::before {
    transform: scale(1);
  }

  ui-data-grid input[type="checkbox"]:indeterminate,
  .grid-table input[type="checkbox"]:indeterminate,
  .ui-checkbox:indeterminate {
    background-color: var(--ui-color-brand-600);
    border-color: var(--ui-color-brand-600);
  }

  ui-data-grid input[type="checkbox"]:indeterminate::before,
  .grid-table input[type="checkbox"]:indeterminate::before,
  .ui-checkbox:indeterminate::before {
    content: '−';
    transform: scale(1);
    font-size: 0.85rem;
  }

  ui-data-grid input[type="checkbox"]:focus-visible,
  .grid-table input[type="checkbox"]:focus-visible,
  .ui-checkbox:focus-visible {
    outline: 2px solid var(--ui-border-focus);
    outline-offset: 2px;
  }

  /* =========================================================================
     Date Range Picker (<ui-date-range-picker>, <nnui-date-range-picker>)
     ========================================================================= */
  ui-date-range-picker,
  nnui-date-range-picker,
  [data-ui="date-range-picker"] {
    display: inline-block;
    position: relative;
    width: 100%;
  }

  .ui-date-range-trigger {
    display: flex;
