  :root[data-theme="dark"] ui-segmented-control,
  :root[data-theme="dark"] nnui-segmented-control,
  [data-theme="dark"] ui-segmented-control,
  [data-theme="dark"] nnui-segmented-control,
  .dark ui-segmented-control,
  .dark nnui-segmented-control {
    background: var(--ui-bg-subtle, #18181b);
