  /* =========================================================================
     22. OTP / PIN INPUT
     ========================================================================= */
  ui-otp-input,
  nnui-otp-input {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
  }

  ui-otp-input [data-part="container"],
  nnui-otp-input [data-part="container"] {
    display: flex;
    align-items: center;
    gap: 0.4rem;
  }

  .ui-otp-slot,
  ui-otp-input [data-part="slot"],
  nnui-otp-input [data-part="slot"] {
    width: 2.75rem;
    height: 3rem;
    font-size: 1.25rem;
    font-weight: 600;
    text-align: center;
    border: 1px solid var(--ui-border-default, #27272a);
    border-radius: var(--ui-radius-md, 6px);
    background: var(--ui-bg-surface, #121214);
    color: var(--ui-text-primary, #ffffff);
    outline: none;
    transition: border-color var(--ui-transition-fast, 150ms), box-shadow var(--ui-transition-fast, 150ms);
