  nnui-otp-input [data-part="slot"]:focus {
    border-color: var(--ui-border-focus);
    box-shadow: 0 0 0 2px var(--ui-focus-ring);
  }

  ui-otp-input [data-part="separator"],
  nnui-otp-input [data-part="separator"] {
    color: var(--ui-text-muted, #71717a);
    font-weight: 700;
  }

  /* =========================================================================
     23. STEPPER / WIZARD (<ui-stepper>, <nnui-stepper>)
     ========================================================================= */
  ui-stepper,
  nnui-stepper,
  [data-ui="stepper"] {
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
    width: 100%;
    box-sizing: border-box;
    container-type: inline-size;
  }

  /* Horizontal Steplist */
  ui-stepper [data-part="steplist"],
  nnui-stepper [data-part="steplist"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    list-style: none;
    margin: 0;
    padding: 0;
    position: relative;
    width: 100%;
    gap: 0.5rem;
  }

  /* Step Item */
  ui-stepper [data-part="step"],
  nnui-stepper [data-part="step"] {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--ui-text-muted, #71717a);
    cursor: pointer;
    position: relative;
    flex: 1;
    user-select: none;
    transition: all var(--ui-transition-fast);
    background: transparent;
    border: none;
    padding: 0.5rem 0.25rem;
    text-align: left;
  }

  ui-stepper [data-part="step"]:last-child,
  nnui-stepper [data-part="step"]:last-child {
    flex: 0 0 auto;
  }

  /* Connecting line between steps */
  ui-stepper [data-part="step"]:not(:last-child)::after,
  nnui-stepper [data-part="step"]:not(:last-child)::after {
    content: '';
    flex: 1;
    height: 2px;
    background: var(--ui-border-default, #27272a);
    margin: 0 0.875rem;
    transition: background var(--ui-transition-normal);
  }

  ui-stepper [data-part="step"][data-state="completed"]:not(:last-child)::after,
  nnui-stepper [data-part="step"][data-state="completed"]:not(:last-child)::after {
    background: var(--ui-color-brand-600);
  }

  /* Step Indicator (Circle with Number or Checkmark) */
  ui-stepper [data-part="indicator"],
  nnui-stepper [data-part="indicator"],
  .ui-stepper-indicator {
    width: 2.25rem;
    height: 2.25rem;
    min-width: 2.25rem;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.875rem;
    font-weight: 600;
    font-family: var(--ui-font-mono, monospace);
    background: var(--ui-bg-surface, #121214);
    border: 2px solid var(--ui-border-default, #27272a);
    color: var(--ui-text-muted, #71717a);
    transition: all var(--ui-transition-fast);
    flex-shrink: 0;
  }

  /* Current Step State */
  ui-stepper [data-part="step"][data-state="current"],
  nnui-stepper [data-part="step"][data-state="current"] {
    color: var(--ui-text-primary, #ffffff);
    font-weight: 600;
  }

  ui-stepper [data-part="step"][data-state="current"] [data-part="indicator"],
  nnui-stepper [data-part="step"][data-state="current"] [data-part="indicator"] {
    background: var(--ui-color-brand-600);
    border-color: var(--ui-color-brand-500);
    color: var(--ui-text-inverted, #ffffff);
    box-shadow: 0 0 0 4px var(--ui-focus-ring), 0 2px 8px color-mix(in srgb, var(--ui-color-brand-500) 30%, transparent);
  }

  /* Completed Step State */
  ui-stepper [data-part="step"][data-state="completed"],
  nnui-stepper [data-part="step"][data-state="completed"] {
    color: var(--ui-text-secondary, #a1a1aa);
  }

  ui-stepper [data-part="step"][data-state="completed"] [data-part="indicator"],
  nnui-stepper [data-part="step"][data-state="completed"] [data-part="indicator"] {
    background: var(--ui-color-brand-600);
    border-color: var(--ui-color-brand-600);
    color: var(--ui-text-inverted, #ffffff);
  }

  /* Hover effect for clickable steps */
  ui-stepper [data-part="step"]:hover:not([aria-disabled="true"]):not([disabled]) [data-part="indicator"],
  nnui-stepper [data-part="step"]:hover:not([aria-disabled="true"]):not([disabled]) [data-part="indicator"] {
    border-color: var(--ui-color-brand-500);
    transform: scale(1.05);
  }

  ui-stepper [data-part="step"]:hover:not([aria-disabled="true"]):not([disabled]) [data-part="title"],
  nnui-stepper [data-part="step"]:hover:not([aria-disabled="true"]):not([disabled]) [data-part="title"] {
    color: var(--ui-text-primary, #ffffff);
  }

  /* Disabled / Gated Upcoming step in linear mode */
  ui-stepper [data-part="step"][aria-disabled="true"],
  ui-stepper [data-part="step"][disabled],
  nnui-stepper [data-part="step"][aria-disabled="true"],
  nnui-stepper [data-part="step"][disabled] {
    cursor: not-allowed;
    opacity: 0.65;
  }

  /* Step Content (Title & Description) */
  ui-stepper [data-part="content"],
  nnui-stepper [data-part="content"] {
    display: flex;
    flex-direction: column;
    text-align: left;
  }

  ui-stepper [data-part="title"],
  nnui-stepper [data-part="title"] {
    font-size: 0.875rem;
    font-weight: 600;
    line-height: 1.25;
    color: inherit;
    transition: color var(--ui-transition-fast);
  }

  ui-stepper [data-part="description"],
  nnui-stepper [data-part="description"] {
    font-size: 0.75rem;
    color: var(--ui-text-muted, #71717a);
    margin-top: 0.2rem;
    line-height: 1.2;
  }

  /* Panels */
  ui-stepper [data-part="panel"],
  nnui-stepper [data-part="panel"] {
    background: var(--ui-bg-surface-elevated, var(--ui-bg-surface));
    border: 1px solid var(--ui-border-default, #27272a);
    border-radius: var(--ui-radius-lg, 12px);
    padding: 1.75rem 2rem;
    box-sizing: border-box;
    box-shadow: var(--ui-shadow-sm);
  }

  ui-stepper [data-part="panel"][data-state="inactive"],
  nnui-stepper [data-part="panel"][data-state="inactive"] {
    display: none !important;
  }

  ui-stepper [data-part="panel"][data-state="active"],
  nnui-stepper [data-part="panel"][data-state="active"] {
    display: block;
    animation: ui-stepper-fade-slide 220ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes ui-stepper-fade-slide {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Vertical Orientation */
  ui-stepper[data-orientation="vertical"],
  ui-stepper[orientation="vertical"],
  nnui-stepper[data-orientation="vertical"],
  nnui-stepper[orientation="vertical"] {
    flex-direction: row;
    align-items: flex-start;
    gap: 2.5rem;
  }

  ui-stepper[data-orientation="vertical"] [data-part="steplist"],
  ui-stepper[orientation="vertical"] [data-part="steplist"],
  nnui-stepper[data-orientation="vertical"] [data-part="steplist"],
