    align-items: stretch;
    width: 240px;
    min-width: 240px;
    gap: 1.25rem;
  }

  ui-stepper[data-orientation="vertical"] [data-part="step"]:not(:last-child)::after,
  ui-stepper[orientation="vertical"] [data-part="step"]:not(:last-child)::after,
  nnui-stepper[data-orientation="vertical"] [data-part="step"]:not(:last-child)::after,
  nnui-stepper[orientation="vertical"] [data-part="step"]:not(:last-child)::after {
