    width: 2px;
    height: auto;
    margin: 0;
    transform: translateX(-50%);
  }

  ui-stepper[data-orientation="vertical"] [data-part="panel"],
  ui-stepper[orientation="vertical"] [data-part="panel"],
  nnui-stepper[data-orientation="vertical"] [data-part="panel"],
  nnui-stepper[orientation="vertical"] [data-part="panel"] {
    flex: 1;
  }

  /* Adaptive Stepper Container Morphing */
  @container (max-width: 600px) {
    ui-stepper:not([orientation="vertical"]) [data-part="title"],
    nnui-stepper:not([orientation="vertical"]) [data-part="title"],
    ui-stepper:not([orientation="vertical"]) [data-part="description"],
    nnui-stepper:not([orientation="vertical"]) [data-part="description"] {
      display: none !important;
    }
    ui-stepper:not([orientation="vertical"]) [data-part="step"]:not(:last-child)::after,
    nnui-stepper:not([orientation="vertical"]) [data-part="step"]:not(:last-child)::after {
      margin: 0 0.35rem !important;
    }
  }

  /* =========================================================================
     24. RESIZABLE SPLIT PANES
     ========================================================================= */
  ui-resizable,
  nnui-resizable {
    display: flex;
    border: 1px solid var(--ui-border-default, #27272a);
    border-radius: var(--ui-radius-lg, 8px);
    overflow: hidden;
    background: var(--ui-bg-surface, #121214);
    min-height: 200px;
  }

  ui-resizable [data-part="panel"],
  nnui-resizable [data-part="panel"] {
    overflow: auto;
    padding: 1rem;
    box-sizing: border-box;
  }

  ui-resizable [data-part="handle"],
  nnui-resizable [data-part="handle"] {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--ui-border-default, #27272a);
    transition: background var(--ui-transition-fast, 150ms);
    user-select: none;
