  }

  ui-resizable[data-orientation="vertical"] [data-part="handle"],
  nnui-resizable[data-orientation="vertical"] [data-part="handle"] {
    height: 6px;
    cursor: row-resize;
  }

  ui-resizable [data-part="handle"]:hover,
  ui-resizable [data-part="handle"][data-dragging="true"],
  nnui-resizable [data-part="handle"]:hover,
  nnui-resizable [data-part="handle"][data-dragging="true"] {
