    color: var(--ui-text-muted, #71717a);
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
  }

  .ui-file-remove:hover {
    color: var(--ui-color-danger-500, #ef4444);
    background: rgba(239, 68, 68, 0.1);
  }

  /* =========================================================================
     26. CONTEXT MENU
     ========================================================================= */
  ui-context-menu [data-part="area"],
  nnui-context-menu [data-part="area"] {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem 1.5rem;
    border: 1px dashed var(--ui-border-default, #27272a);
    border-radius: var(--ui-radius-lg, 8px);
    background: var(--ui-bg-surface, #121214);
    color: var(--ui-text-muted, #a1a1aa);
    user-select: none;
  }

  ui-context-menu [data-part="menu"],
  nnui-context-menu [data-part="menu"] {
    position: fixed;
    margin: 0;
    inset: unset;
    min-width: 180px;
    background: var(--ui-bg-surface-elevated, #18181b);
    border: 1px solid var(--ui-border-default, #27272a);
    border-radius: var(--ui-radius-md, 6px);
    padding: 0.35rem;
    box-shadow: var(--ui-shadow-lg, 0 10px 25px -5px rgba(0,0,0,0.5));
    display: none;
    flex-direction: column;
    gap: 2px;
    z-index: 1000;
  }

  ui-context-menu [data-part="menu"][data-state="open"],
  nnui-context-menu [data-part="menu"][data-state="open"] {
    display: flex !important;
  }

  ui-context-menu [data-part="item"],
  nnui-context-menu [data-part="item"] {
    display: flex;
    align-items: center;
    padding: 0.4rem 0.65rem;
    font-size: 0.85rem;
    color: var(--ui-text-primary, #ffffff);
    border-radius: var(--ui-radius-sm, 4px);
    cursor: pointer;
    background: transparent;
    border: none;
    text-align: left;
    outline: none;
  }

  ui-context-menu [data-part="item"]:hover,
  ui-context-menu [data-part="item"]:focus,
  nnui-context-menu [data-part="item"]:hover,
  nnui-context-menu [data-part="item"]:focus {
    background: var(--ui-color-brand-600);
    color: var(--ui-text-inverted, #ffffff);
  }

  /* =========================================================================
     27. NAVIGATION MENU (MEGA-MENU)
     ========================================================================= */
  /* =========================================================================
     27. NAVIGATION MENU (<ui-navigation-menu>, <nnui-navigation-menu>)
     ========================================================================= */
  ui-navigation-menu,
  nnui-navigation-menu,
  [data-ui="navigation-menu"] {
    display: flex;
    align-items: center;
    position: relative;
    width: 100%;
    box-sizing: border-box;
  }

  ui-navigation-menu [data-part="menubar"],
  nnui-navigation-menu [data-part="menubar"] {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    list-style: none;
    margin: 0;
    padding: 0;
  }

  ui-navigation-menu [data-part="item"],
  nnui-navigation-menu [data-part="item"] {
    position: relative;
    display: inline-flex;
    align-items: center;
  }

  ui-navigation-menu [data-part="trigger"],
  nnui-navigation-menu [data-part="trigger"] {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    background: transparent;
    border: 1px solid transparent;
    padding: 0.45rem 0.85rem;
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--ui-text-muted, #a1a1aa);
    border-radius: var(--ui-radius-md, 6px);
    cursor: pointer;
    transition: all var(--ui-transition-fast, 150ms);
    user-select: none;
  }

  ui-navigation-menu [data-part="trigger"]:hover,
  ui-navigation-menu [data-part="trigger"][aria-expanded="true"],
  nnui-navigation-menu [data-part="trigger"]:hover,
  nnui-navigation-menu [data-part="trigger"][aria-expanded="true"] {
    background: var(--ui-bg-subtle, #18181b);
    color: var(--ui-text-primary, #ffffff);
    border-color: var(--ui-border-default, #27272a);
  }

  ui-navigation-menu [data-part="content"],
  nnui-navigation-menu [data-part="content"] {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    margin: 0;
    min-width: 280px;
    background: var(--ui-bg-surface-elevated, #18181b);
    border: 1px solid var(--ui-border-default, #27272a);
    border-radius: var(--ui-radius-xl, 12px);
    padding: 1.25rem;
    box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.08);
    z-index: 1000;
    display: none;
    opacity: 0;
    transform: translateY(-6px);
    transition: opacity 150ms ease, transform 150ms ease;
    pointer-events: none;
  }

  ui-navigation-menu [data-part="content"][data-state="open"],
  nnui-navigation-menu [data-part="content"][data-state="open"] {
    display: block !important;
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
    animation: uiSlideDown 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  /* =========================================================================
     28. TREE VIEW
     ========================================================================= */
  ui-tree-view,
  nnui-tree-view {
    display: block;
    font-family: inherit;
    font-size: 0.875rem;
    color: var(--ui-text-primary, #ffffff);
  }

  ui-tree-view ul,
  nnui-tree-view ul {
    list-style: none;
    margin: 0;
    padding-left: 1.25rem;
  }

  ui-tree-view > ul,
  nnui-tree-view > ul {
    padding-left: 0;
  }

  ui-tree-view [data-part="item"],
  nnui-tree-view [data-part="item"] {
    padding: 0.25rem 0.5rem;
    border-radius: var(--ui-radius-sm, 4px);
    cursor: pointer;
    outline: none;
    user-select: none;
  }

  ui-tree-view [data-part="item"]:focus,
  ui-tree-view [data-part="item"][data-selected="true"],
  nnui-tree-view [data-part="item"]:focus,
  nnui-tree-view [data-part="item"][data-selected="true"] {
    background: var(--ui-bg-hover, #27272a);
    color: var(--ui-color-brand-500);
  }

  ui-tree-view [data-part="group"],
  nnui-tree-view [data-part="group"] {
    display: none;
  }

  ui-tree-view [data-part="item"][aria-expanded="true"] > [data-part="group"],
  nnui-tree-view [data-part="item"][aria-expanded="true"] > [data-part="group"] {
    display: block;
  }

  /* =========================================================================
     29. AI PROMPT BOX
     ========================================================================= */
  ui-ai-prompt-box,
  nnui-ai-prompt-box {
    display: flex;
    flex-direction: column;
    background: var(--ui-bg-surface, #121214);
    border: 1px solid var(--ui-border-default, #27272a);
    border-radius: var(--ui-radius-lg, 8px);
    padding: 0.75rem;
    box-shadow: var(--ui-shadow-sm, 0 1px 3px rgba(0,0,0,0.3));
    transition: border-color var(--ui-transition-fast, 150ms), background-color var(--ui-transition-fast, 150ms);
    container-type: inline-size;
  }

  ui-ai-prompt-box[data-dragover],
  nnui-ai-prompt-box[data-dragover] {
    border-color: var(--ui-color-brand-500, #6366f1) !important;
    background: color-mix(in srgb, var(--ui-color-brand-500, #6366f1) 8%, var(--ui-bg-surface, #121214)) !important;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--ui-color-brand-500, #6366f1) 30%, transparent) !important;
  }

  @container (max-width: 380px) {
    ui-ai-prompt-box [data-part="toolbar"],
    nnui-ai-prompt-box [data-part="toolbar"] {
      flex-wrap: wrap !important;
      gap: 0.5rem !important;
    }
  }

  ui-ai-prompt-box:focus-within,
  nnui-ai-prompt-box:focus-within {
    border-color: var(--ui-border-focus);
    box-shadow: 0 0 0 2px var(--ui-focus-ring);
  }

  ui-ai-prompt-box textarea,
  nnui-ai-prompt-box textarea {
    width: 100%;
    border: none;
    outline: none;
    background: transparent;
    color: var(--ui-text-primary, #ffffff);
    font-family: inherit;
    font-size: 0.95rem;
    line-height: 1.5;
    box-sizing: border-box;
    padding: 0;
  }

  ui-ai-prompt-box [data-part="toolbar"],
  nnui-ai-prompt-box [data-part="toolbar"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 0.75rem;
    padding-top: 0.5rem;
    border-top: 1px solid var(--ui-border-subtle, #1e1e24);
  }

  ui-ai-prompt-box [data-part="submit-btn"],
  nnui-ai-prompt-box [data-part="submit-btn"] {
    background: var(--ui-color-brand-600);
    color: var(--ui-text-inverted, #ffffff);
    border: none;
    border-radius: var(--ui-radius-md, 6px);
    padding: 0.4rem 0.85rem;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: filter 150ms ease, transform 150ms ease;
  }
  ui-ai-prompt-box [data-part="submit-btn"]:hover,
  nnui-ai-prompt-box [data-part="submit-btn"]:hover {
    filter: brightness(1.1);
  }

  ui-ai-prompt-box [data-part="stop-btn"],
  nnui-ai-prompt-box [data-part="stop-btn"] {
    background: var(--ui-color-danger-500, #ef4444);
    color: #ffffff;
    border: none;
    border-radius: var(--ui-radius-md, 6px);
    padding: 0.4rem 0.85rem;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
  }

  /* =========================================================================
     30. COLOR PICKER (<ui-color-picker>, <nnui-color-picker>)
     ========================================================================= */
  ui-color-picker,
  nnui-color-picker,
  [data-ui="color-picker"] {
    display: inline-flex;
    align-items: center;
    gap: 0.75rem;
    position: relative;
  }

  ui-color-picker [data-part="swatch"],
  nnui-color-picker [data-part="swatch"] {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: var(--ui-radius-lg, 8px);
    border: 2px solid var(--ui-border-default, #27272a);
    cursor: pointer;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
    transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
    background-image: linear-gradient(45deg, #18181b 25%, transparent 25%), linear-gradient(-45deg, #18181b 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #18181b 75%), linear-gradient(-45deg, transparent 75%, #18181b 75%);
    background-size: 10px 10px;
    background-position: 0 0, 0 5px, 5px -5px, -5px 0px;
  }

  ui-color-picker [data-part="swatch"]:hover {
    transform: scale(1.05);
    border-color: var(--ui-border-focus);
    box-shadow: 0 0 0 3px var(--ui-focus-ring);
  }

  ui-color-picker [data-part="popover"],
  nnui-color-picker [data-part="popover"] {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    margin: 0;
    min-width: 250px;
    background: var(--ui-bg-surface-elevated, #18181b);
    border: 1px solid var(--ui-border-default, #27272a);
    border-radius: var(--ui-radius-xl, 12px);
    padding: 1.25rem;
    box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.08);
    display: none;
    flex-direction: column;
    gap: 0.85rem;
    z-index: 1000;
    animation: uiSlideDown 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  ui-color-picker [data-part="popover"][data-state="open"],
  nnui-color-picker [data-part="popover"][data-state="open"] {
    display: flex !important;
  }

  /* =========================================================================
     Sparkline Component (<ui-sparkline>, <nnui-sparkline>)
     ========================================================================= */
  ui-sparkline,
  nnui-sparkline,
  [data-ui="sparkline"] {
    position: relative;
    display: inline-block;
    width: 100%;
    max-width: 220px;
    height: 48px;
    vertical-align: middle;
    overflow: visible;
  }

  /* =========================================================================
     Dock Component (<ui-dock>, <nnui-dock>)
     ========================================================================= */
  ui-dock,
  nnui-dock,
  [data-ui="dock"] {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.55rem;
    background: rgba(18, 22, 30, 0.88);
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: var(--ui-radius-full, 9999px);
    box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.15), 0 20px 40px -10px rgba(0, 0, 0, 0.7), 0 0 0 1px rgba(0, 0, 0, 0.5);
    user-select: none;
    z-index: 100;
  }

  :root:not([data-theme="dark"]) ui-dock,
  :root:not([data-theme="dark"]) nnui-dock {
    background: rgba(255, 255, 255, 0.88);
    border-color: rgba(0, 0, 0, 0.08);
    box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.9), 0 16px 36px -6px rgba(0, 0, 0, 0.12), 0 0 0 1px rgba(0, 0, 0, 0.04);
  }

  ui-dock[position="floating-bottom"],
  nnui-dock[position="floating-bottom"] {
    position: fixed;
    bottom: 1.5rem;
    left: 50%;
    transform: translateX(-50%);
  }

  ui-dock [data-part="item"],
  nnui-dock [data-part="item"] {
    position: relative;
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    min-width: 56px;
    height: 50px;
    padding: 6px 14px;
    border-radius: var(--ui-radius-full, 9999px);
    background: transparent;
    color: #94a3b8;
    border: 1px solid transparent;
    cursor: pointer;
    outline: none;
    text-decoration: none;
    transform-origin: bottom center;
    transform: scale(var(--dock-scale, 1)) translateY(var(--dock-translate-y, 0px));
    transition: transform var(--ui-transition-spring-snappy, 350ms cubic-bezier(0.16, 1, 0.3, 1)), background-color 150ms ease, color 150ms ease, box-shadow 150ms ease;
  }

  :root:not([data-theme="dark"]) ui-dock [data-part="item"] {
    color: #64748b;
  }

  /* Active Pill Capsule (Apple / Revolut Navigation Style) */
  ui-dock [data-part="item"][data-active="true"],
  ui-dock [data-part="item"][aria-selected="true"],
  ui-dock [data-part="item"].is-active,
  nnui-dock [data-part="item"][data-active="true"],
  nnui-dock [data-part="item"][aria-selected="true"],
  nnui-dock [data-part="item"].is-active {
    background: rgba(255, 255, 255, 0.14);
    color: #ffffff;
    box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.25), 0 2px 10px rgba(0, 0, 0, 0.35);
  }

  :root:not([data-theme="dark"]) ui-dock [data-part="item"][data-active="true"],
  :root:not([data-theme="dark"]) ui-dock [data-part="item"][aria-selected="true"],
  :root:not([data-theme="dark"]) ui-dock [data-part="item"].is-active {
    background: rgba(0, 0, 0, 0.08);
    color: #09090b;
    box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.06);
  }

  /* Hover state when not active */
  ui-dock [data-part="item"]:hover:not([data-active="true"]),
  nnui-dock [data-part="item"]:hover:not([data-active="true"]) {
    background: rgba(255, 255, 255, 0.06);
    color: #f8fafc;
  }

  :root:not([data-theme="dark"]) ui-dock [data-part="item"]:hover:not([data-active="true"]) {
    background: rgba(0, 0, 0, 0.04);
    color: #0f172a;
  }

  ui-dock [data-part="item"]:focus-visible,
  nnui-dock [data-part="item"]:focus-visible {
    border-color: var(--ui-border-focus);
    box-shadow: 0 0 0 2px var(--ui-focus-ring);
  }

  /* Dock Item Icons */
  ui-dock [data-part="item"] > svg,
  ui-dock [data-part="icon"],
  nnui-dock [data-part="item"] > svg,
  nnui-dock [data-part="icon"] {
    width: 20px;
    height: 20px;
    flex-shrink: 0;
    stroke: currentColor;
    fill: none;
    stroke-width: 2.2;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: transform var(--ui-transition-fast);
  }

  /* Dock Item Label */
  ui-dock [data-part="label"],
  nnui-dock [data-part="label"] {
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: -0.01em;
    line-height: 1;
    white-space: nowrap;
  }

  /* Tooltip for icon-only variant */
  ui-dock [data-part="tooltip"],
  nnui-dock [data-part="tooltip"] {
    position: absolute;
    bottom: calc(100% + 8px);
    left: 50%;
    transform: translateX(-50%) translateY(4px);
    opacity: 0;
    pointer-events: none;
    font-size: 0.75rem;
    font-weight: 600;
    white-space: nowrap;
    padding: 0.25rem 0.5rem;
    border-radius: var(--ui-radius-sm);
    background: var(--ui-bg-surface-elevated, #151b27);
    color: var(--ui-text-primary, #ffffff);
    border: 1px solid var(--ui-border-default);
    box-shadow: var(--ui-shadow-md);
    transition: opacity var(--ui-transition-fast), transform var(--ui-transition-fast);
    z-index: 10;
  }

  ui-dock [data-part="item"]:hover [data-part="tooltip"],
  ui-dock [data-part="item"]:focus-visible [data-part="tooltip"] {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }

  /* =========================================================================
     Timeline Component (<ui-timeline>, <nnui-timeline>)
     ========================================================================= */
  ui-timeline,
  nnui-timeline,
  [data-ui="timeline"] {
    display: flex;
    flex-direction: column;
    position: relative;
    padding: 0.5rem 0;
    margin: 0;
    list-style: none;
    gap: 0;
    width: 100%;
  }

  ui-timeline[orientation="horizontal"],
  nnui-timeline[orientation="horizontal"] {
    flex-direction: row;
    overflow-x: auto;
  }

  ui-timeline [data-part="item"],
  nnui-timeline [data-part="item"] {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
    padding-bottom: 2rem;
    min-height: 84px;
  }

  ui-timeline [data-part="item"]:last-child {
    padding-bottom: 0;
  }

  /* Connecting vertical line */
  ui-timeline [data-part="connector"],
  nnui-timeline [data-part="connector"] {
    position: absolute;
    top: 34px;
    left: 14px;
    bottom: -6px;
    width: 2px;
    background: rgba(255, 255, 255, 0.12);
    z-index: 1;
  }

  :root:not([data-theme="dark"]) ui-timeline [data-part="connector"] {
    background: #e2e8f0;
  }

  ui-timeline [data-part="item"]:last-child [data-part="connector"] {
    display: none;
  }

  /* Connecting line gradients between steps */
  ui-timeline [data-part="item"][data-status="completed"] [data-part="connector"] {
    background: linear-gradient(to bottom, #10b981 0%, #f97316 100%);
  }

  ui-timeline [data-part="item"][data-status="active"] [data-part="connector"] {
    background: linear-gradient(to bottom, #f97316 0%, rgba(255, 255, 255, 0.12) 100%);
  }

  /* Timeline Marker (Beacon / Badge) */
  ui-timeline [data-part="marker"],
  nnui-timeline [data-part="marker"] {
    position: relative;
    z-index: 2;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: #11151f;
    border: 2px solid rgba(255, 255, 255, 0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    box-sizing: border-box;
    transition: all var(--ui-transition-spring-snappy, 350ms cubic-bezier(0.16, 1, 0.3, 1));
  }

  :root:not([data-theme="dark"]) ui-timeline [data-part="marker"] {
    background: #f8fafc;
    border-color: #cbd5e1;
  }

  /* Completed Status: Emerald Aura with Checkmark */
  ui-timeline [data-part="item"][data-status="completed"] [data-part="marker"] {
    background: #10b981;
    border: none;
    color: #ffffff;
    box-shadow: 0 0 16px rgba(16, 185, 129, 0.55), 0 0 4px rgba(16, 185, 129, 0.8);
  }
  ui-timeline [data-part="item"][data-status="completed"] [data-part="marker"]::after {
    content: "✓";
    font-size: 14px;
    font-weight: 800;
    line-height: 1;
    color: #ffffff;
  }

  /* Active Status: Glowing Luminous Orange Beacon with Pulse */
  ui-timeline [data-part="item"][data-status="active"] [data-part="marker"] {
    background: #f97316;
    border: 3px solid #ffffff;
    box-shadow: 0 0 18px rgba(249, 115, 22, 0.75), 0 0 6px rgba(249, 115, 22, 0.9);
    animation: ui-timeline-beacon-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  }

  @keyframes ui-timeline-beacon-pulse {
    0% {
      box-shadow: 0 0 0 0 rgba(249, 115, 22, 0.6), 0 0 16px rgba(249, 115, 22, 0.75);
    }
    60% {
      box-shadow: 0 0 0 10px transparent, 0 0 22px rgba(249, 115, 22, 0.4);
    }
    100% {
      box-shadow: 0 0 0 0 transparent, 0 0 16px rgba(249, 115, 22, 0.75);
    }
  }

  /* Timeline Card Content */
  ui-timeline [data-part="content"],
  nnui-timeline [data-part="content"] {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    padding: 1.15rem 1.35rem;
    border-radius: 14px;
    background: rgba(18, 22, 31, 0.75);
    border: 1px solid rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    box-shadow: 0 8px 24px -4px rgba(0, 0, 0, 0.45);
    transition: transform var(--ui-transition-spring-snappy, 350ms cubic-bezier(0.16, 1, 0.3, 1)), border-color 200ms ease;
  }

  :root:not([data-theme="dark"]) ui-timeline [data-part="content"] {
    background: #ffffff;
    border-color: #e2e8f0;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  }

  ui-timeline [data-part="item"]:hover [data-part="content"] {
    border-color: rgba(255, 255, 255, 0.18);
    transform: translateX(3px);
  }

