    overflow: hidden;
    margin: 1rem 0;
    width: 100%;
    transition: all 250ms var(--ui-spring-snappy, cubic-bezier(0.16, 1, 0.3, 1));
  }

  ui-ai-approval[data-severity="critical"] {
    border-color: rgba(244, 63, 94, 0.45);
    box-shadow: 0 0 24px -4px rgba(244, 63, 94, 0.25), 0 8px 32px -4px rgba(0, 0, 0, 0.5);
  }

  ui-ai-approval[data-severity="warning"] {
    border-color: rgba(249, 115, 22, 0.45);
    box-shadow: 0 0 20px -4px rgba(249, 115, 22, 0.2), 0 8px 32px -4px rgba(0, 0, 0, 0.5);
  }

  ui-ai-approval [data-part="header"],
  nnui-ai-approval [data-part="header"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.85rem 1.25rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  ui-ai-approval [data-part="title-group"],
  nnui-ai-approval [data-part="title-group"] {
    display: flex;
    align-items: center;
    gap: 0.6rem;
  }

  ui-ai-approval[data-severity="critical"] [data-part="icon"] {
    color: #f43f5e;
  }
  ui-ai-approval[data-severity="warning"] [data-part="icon"] {
    color: #f97316;
  }

  ui-ai-approval [data-part="title"],
  nnui-ai-approval [data-part="title"] {
    margin: 0;
    font-size: 0.95rem;
    font-weight: 600;
    color: #ffffff;
    letter-spacing: -0.01em;
  }

  ui-ai-approval [data-part="severity-badge"],
  nnui-ai-approval [data-part="severity-badge"] {
    font-size: 0.7rem;
    font-weight: 600;
    padding: 0.2rem 0.6rem;
    border-radius: 9999px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  ui-ai-approval [data-part="severity-badge"][data-severity="critical"] {
    background: rgba(244, 63, 94, 0.15);
    color: #f43f5e;
    border: 1px solid rgba(244, 63, 94, 0.35);
  }

  ui-ai-approval [data-part="severity-badge"][data-severity="warning"] {
    background: rgba(249, 115, 22, 0.15);
    color: #f97316;
    border: 1px solid rgba(249, 115, 22, 0.35);
  }

  /* Payload / Diff container */
  ui-ai-approval [data-part="payload"],
  ui-ai-approval [data-part="content"],
  ui-ai-approval [data-part="diff"],
  nnui-ai-approval [data-part="payload"],
  nnui-ai-approval [data-part="content"],
  nnui-ai-approval [data-part="diff"] {
    padding: 1rem 1.25rem;
    font-family: var(--ui-font-mono, monospace);
    font-size: 0.825rem;
    line-height: 1.5;
    background: #090a0f;
    color: #f8fafc;
    overflow-x: auto;
  }

  /* Actions Bar */
  ui-ai-approval [data-part="actions"],
  nnui-ai-approval [data-part="actions"] {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    background: rgba(255, 255, 255, 0.02);
    border-top: 1px solid rgba(255, 255, 255, 0.08);
  }

  ui-ai-approval [data-part="reject"],
  nnui-ai-approval [data-part="reject"] {
    padding: 0.45rem 1rem;
    border-radius: 8px;
    background: transparent;
    border: 1px solid rgba(244, 63, 94, 0.4);
    color: #f43f5e;
    font-size: 0.8125rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 150ms ease;
  }

  ui-ai-approval [data-part="reject"]:hover {
    background: rgba(244, 63, 94, 0.12);
  }

  ui-ai-approval [data-part="approve"],
  nnui-ai-approval [data-part="approve"] {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 1.1rem;
    border-radius: 8px;
    background: #10b981;
    border: 1px solid transparent;
    color: #ffffff;
    font-size: 0.8125rem;
    font-weight: 600;
    cursor: pointer;
    box-shadow: 0 2px 10px rgba(16, 185, 129, 0.4);
    transition: all 150ms ease;
  }

  ui-ai-approval [data-part="approve"]:hover {
    background: #059669;
    box-shadow: 0 4px 14px rgba(16, 185, 129, 0.55);
  }

  ui-ai-approval [data-part="approve"] kbd {
    background: rgba(0, 0, 0, 0.25);
    padding: 0.1rem 0.35rem;
    border-radius: 4px;
    font-size: 0.6875rem;
  }

  /* Settled Audit Badges */
  ui-ai-approval [data-part="audit-badge"],
  nnui-ai-approval [data-part="audit-badge"] {
    display: none;
    align-items: center;
    justify-content: center;
    padding: 0.75rem 1.25rem;
    font-size: 0.85rem;
    font-weight: 600;
  }

  ui-ai-approval [data-part="audit-badge"][data-status="approved"] {
    color: #10b981;
    background: rgba(16, 185, 129, 0.1);
  }

  ui-ai-approval [data-part="audit-badge"][data-status="rejected"] {
    color: #f43f5e;
    background: rgba(244, 63, 94, 0.1);
  }
}

