import { BaseLightElement } from '../../utils/base-element.js';
import { Keys, getNextIndex, generateUniqueId } from '../../utils/a11y.js';
import { applyPositionFallback } from '../../utils/anchor-fallback.js';

/**
 * <ui-dropdown> Micro-Enhancer
 * WAI-ARIA APG Compliant Dropdown Menu Pattern in Light-DOM.
 * Invariant: Mutates attributes, never nodes.
 */
export class UiDropdown extends BaseLightElement {
  static get observedAttributes() {
    return ['open'];
  }

  get isOpen() {
    return this.hasAttribute('open') || this._menu?.getAttribute('data-state') === 'open';
  }

  set isOpen(val) {
    if (val) this.open();
    else this.close();
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'dropdown');
    this._trigger = this.querySelector('[data-part="trigger"], button');
    this._menu = this.querySelector('[data-part="menu"], [role="menu"], ul, ol, div');
    this._activeIndex = -1;

    if (!this._trigger || !this._menu) return;

    this._setupARIA();
    this._bindEvents();
  }

  _getItems() {
    if (!this._menu) return [];
    return Array.from(
      this._menu.querySelectorAll('[data-part="item"], [role="menuitem"], li, button')
    ).filter((item) => !item.hasAttribute('disabled') && item.getAttribute('aria-disabled') !== 'true');
  }

  _setupARIA() {
    const baseId = this.id || generateUniqueId('dropdown');
    const menuId = this._menu.id || `${baseId}-menu`;

    this.setAttributeSafe(this._trigger, 'aria-haspopup', 'menu');
    this.setAttributeSafe(this._trigger, 'aria-expanded', 'false');
    this.setAttributeSafe(this._trigger, 'aria-controls', menuId);

    this.setAttributeSafe(this._menu, 'id', menuId);
    this.setAttributeSafe(this._menu, 'role', 'menu');
    this.setAttributeSafe(this._menu, 'data-state', 'closed');
    this.setAttributeSafe(this._menu, 'tabindex', '-1');

    this._getItems().forEach((item, idx) => {
      const itemId = item.id || `${baseId}-item-${idx}`;
      this.setAttributeSafe(item, 'id', itemId);
      this.setAttributeSafe(item, 'role', 'menuitem');
      this.setAttributeSafe(item, 'tabindex', '-1');
    });
  }

  _bindEvents() {
    // 1. Trigger click toggle
    this.listen(this._trigger, 'click', (e) => {
      e.preventDefault();
      this.toggle();
    });

    // 2. Keyboard navigation on trigger
    this.listen(this._trigger, 'keydown', (e) => {
      if (e.key === Keys.ARROW_DOWN || e.key === Keys.ENTER || e.key === Keys.SPACE) {
        e.preventDefault();
        this.open(0);
      } else if (e.key === Keys.ARROW_UP) {
        e.preventDefault();
        const items = this._getItems();
        this.open(items.length - 1);
      }
    });

    // 3. Keyboard navigation inside menu
    this.listen(this._menu, 'keydown', (e) => {
      const items = this._getItems();
      if (!items.length) return;

      switch (e.key) {
        case Keys.ARROW_DOWN:
          e.preventDefault();
          this._focusItem(getNextIndex(this._activeIndex, items.length, 1));
          break;
        case Keys.ARROW_UP:
          e.preventDefault();
          this._focusItem(getNextIndex(this._activeIndex, items.length, -1));
          break;
        case Keys.HOME:
          e.preventDefault();
          this._focusItem(0);
          break;
        case Keys.END:
          e.preventDefault();
          this._focusItem(items.length - 1);
          break;
        case Keys.ENTER:
        case Keys.SPACE: {
          e.preventDefault();
          if (this._activeIndex >= 0 && items[this._activeIndex]) {
            this.selectItem(items[this._activeIndex]);
          }
          break;
        }
        case Keys.ESCAPE:
          e.preventDefault();
          this.close();
          this._trigger?.focus();
          break;
        case Keys.TAB:
          this.close();
          break;
      }
    });

    // 4. Click delegation on menu items
    this.listen(this._menu, 'click', (e) => {
      const item = e.target.closest('[data-part="item"], [role="menuitem"], li, button');
      if (item && this._menu.contains(item)) {
        if (item.hasAttribute('disabled') || item.getAttribute('aria-disabled') === 'true') {
          return;
        }
        this.selectItem(item);
      }
    });

    // 5. Dismiss on pointerdown outside
    this.listen(document, 'pointerdown', (e) => {
      if (!this.contains(e.target) && this.isOpen) {
        this.close();
      }
    });

    // 6. Reposition on scroll / resize
    const onScrollOrResize = () => {
      if (this.isOpen) {
        this._reposition();
      }
    };
    this.listen(window, 'resize', onScrollOrResize, { passive: true });
    this.listen(window, 'scroll', onScrollOrResize, { passive: true });
  }

  _reposition() {
    if (!this._trigger || !this._menu) return;
    applyPositionFallback(this._trigger, this._menu, 'bottom', 6);
  }

  _focusItem(index) {
    const items = this._getItems();
    if (!items.length) return;

    items.forEach((item, idx) => {
      const isFocused = idx === index;
      this.setAttributeSafe(item, 'data-focused', isFocused ? 'true' : 'false');
      this.setAttributeSafe(item, 'tabindex', isFocused ? '0' : '-1');
    });

    this._activeIndex = index;
    if (items[index]) {
      items[index].focus();
    }
  }

  open(focusIndex = -1) {
    if (!this._menu) return;
    this.setAttributeSafe(this, 'open', '');
    this.setAttributeSafe(this._trigger, 'aria-expanded', 'true');
    this.setAttributeSafe(this._menu, 'data-state', 'open');

    this._reposition();
    requestAnimationFrame(() => {
      this._reposition();
      if (focusIndex >= 0) {
        this._focusItem(focusIndex);
      } else {
        this._menu.focus();
      }
    });

    this.dispatch('open');
  }

  close() {
    if (!this._menu) return;
    this.removeAttribute('open');
    this.setAttributeSafe(this._trigger, 'aria-expanded', 'false');
    this.setAttributeSafe(this._menu, 'data-state', 'closed');
    this._activeIndex = -1;

    const items = this._getItems();
    items.forEach((item) => {
      this.setAttributeSafe(item, 'data-focused', 'false');
      this.setAttributeSafe(item, 'tabindex', '-1');
    });

    this.dispatch('close');
  }

  toggle() {
    if (this.isOpen) {
      this.close();
    } else {
      this.open();
    }
  }

  selectItem(item) {
    const value = item.dataset.value || item.getAttribute('value') || item.textContent.trim();
    const label = item.textContent.trim();

    this.dispatch('select', { value, label, item });
    this.close();
    this._trigger?.focus();
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (name === 'open') {
      if (newVal !== null && !this.isOpen) {
        this.open();
      } else if (newVal === null && this.isOpen) {
        this.close();
      }
    }
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

let activeToaster = null;
let toastCounter = 0;

/**
 * <ui-toaster> Micro-Enhancer
 * Lightweight, stacked toast notification viewport in Light-DOM.
 */
export class UiToaster extends BaseLightElement {
  static get observedAttributes() {
    return ['position', 'expand', 'max', 'limit'];
  }

  get position() {
    return this.getAttribute('position') || 'bottom-right';
  }

  set position(val) {
    if (val) this.setAttribute('position', val);
    else this.removeAttribute('position');
  }

  get expand() {
    return this.hasAttribute('expand');
  }

  set expand(val) {
    if (val) this.setAttribute('expand', '');
    else this.removeAttribute('expand');
  }

  get max() {
    const val = this.getAttribute('max') || this.getAttribute('limit');
    return val ? parseInt(val, 10) : 3;
  }

  set max(val) {
    if (val) this.setAttribute('max', String(val));
    else this.removeAttribute('max');
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'toaster');
    this.setAttributeSafe(this, 'role', 'region');
    this.setAttributeSafe(this, 'aria-label', 'Notifications');
    this.setAttributeSafe(this, 'position', this.position);

    activeToaster = this;
  }

  destroy() {
    if (activeToaster === this) {
      activeToaster = null;
    }
  }

  createToast({
    title = '',
    description = '',
    type = 'default',
    duration = 4000,
    action = null,
    onDismiss = null,
  } = {}) {
    // 1. Deduplication: If identical toast is already active, shake & restart timer instead of piling up
    const activeToasts = Array.from(this.querySelectorAll('[data-ui="toast"]:not([data-state="closed"])'));
    const duplicate = activeToasts.find(
      (t) => t.dataset.toastTitle === title && t.dataset.type === type && t.dataset.toastDesc === (description || '')
    );
    if (duplicate) {
      duplicate.setAttribute('data-shake', 'true');
      setTimeout(() => duplicate.removeAttribute('data-shake'), 350);
      if (typeof duplicate._restartTimer === 'function') {
        duplicate._restartTimer();
      }
      return { id: duplicate.id, dismiss: duplicate._dismiss, element: duplicate };
    }

    // 2. Strict visible limit: Prevent flooding the screen (default 3 max)
    const maxAllowed = Math.max(1, this.max || 3);
    if (activeToasts.length >= maxAllowed) {
      const excess = activeToasts.length - maxAllowed + 1;
      for (let i = 0; i < excess; i++) {
        const oldest = activeToasts[i];
        if (typeof oldest._dismiss === 'function') {
          oldest._dismiss();
        } else {
          oldest.remove();
        }
      }
    }

    const id = `toast-${++toastCounter}`;
    const toastEl = document.createElement('div');
    toastEl.id = id;
    toastEl.setAttribute('data-ui', 'toast');
    toastEl.setAttribute('data-type', type);
    toastEl.setAttribute('data-state', 'open');
    toastEl.setAttribute('role', type === 'error' ? 'alert' : 'status');
    toastEl.setAttribute('aria-live', type === 'error' ? 'assertive' : 'polite');
    toastEl.dataset.toastTitle = title;
    toastEl.dataset.toastDesc = description || '';

    const icons = {
      default: '',
      success: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="ui-toast-svg ui-toast-svg--success"><circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/></svg>`,
      error: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="ui-toast-svg ui-toast-svg--error"><circle cx="12" cy="12" r="10"/><path d="m15 9-6 6"/><path d="m9 9 6 6"/></svg>`,
      warning: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="ui-toast-svg ui-toast-svg--warning"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>`,
      info: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="ui-toast-svg ui-toast-svg--info"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>`,
      loading: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="ui-toast-svg ui-toast-svg--loading ui-spin"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>`,
    };

    const iconHtml = icons[type]
      ? `<span data-part="toast-icon" data-type="${type}">${icons[type]}</span>`
      : '';

    const actionHtml = action
      ? `<button type="button" data-part="toast-action" class="ui-toast-action-btn">${action.label}</button>`
      : '';

    const hasProgressBar = duration > 0 && duration !== Infinity && type !== 'loading';
    const progressHtml = hasProgressBar
      ? `<div data-part="toast-progress" style="animation: uiToastProgress ${duration}ms linear forwards;"></div>`
      : '';

    toastEl.innerHTML = `
      <div data-part="toast-content">
        ${iconHtml}
        <div data-part="toast-text">
          <div data-part="toast-title">${title}</div>
          ${description ? `<div data-part="toast-description">${description}</div>` : ''}
        </div>
      </div>
      <div data-part="toast-actions">
        ${actionHtml}
        <button type="button" data-part="toast-close" aria-label="Dismiss"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></button>
      </div>
      ${progressHtml}
    `;

    // Action button listener
    if (action?.onClick) {
      const actionBtn = toastEl.querySelector('[data-part="toast-action"]');
      if (actionBtn) {
        actionBtn.addEventListener('click', (e) => {
          action.onClick(e);
          dismiss();
        });
      }
    }

    // Close button listener
    const closeBtn = toastEl.querySelector('[data-part="toast-close"]');
    if (closeBtn) {
      closeBtn.addEventListener('click', () => dismiss());
    }

    // Auto-dismiss timer with hover pause
    let remaining = duration;
    let timerId = null;
    let startTime = Date.now();

    const startTimer = () => {
      if (duration <= 0 || duration === Infinity) return;
      startTime = Date.now();
      timerId = setTimeout(() => dismiss(), remaining);
    };

    const pauseTimer = () => {
      if (timerId) {
        clearTimeout(timerId);
        remaining -= Date.now() - startTime;
      }
    };

    toastEl.addEventListener('pointerenter', pauseTimer);
    toastEl.addEventListener('pointerleave', startTimer);

    const dismiss = () => {
      pauseTimer();
      toastEl.setAttribute('data-state', 'closed');
      toastEl.addEventListener('animationend', () => {
        toastEl.remove();
        if (typeof onDismiss === 'function') onDismiss(id);
      }, { once: true });

      // Fallback removal if animation disabled
      setTimeout(() => {
        if (toastEl.parentNode) {
          toastEl.remove();
          if (typeof onDismiss === 'function') onDismiss(id);
        }
      }, 250);
    };

    const update = ({ title: newTitle, description: newDesc, type: newType, duration: newDuration = 4000 } = {}) => {
      if (newTitle !== undefined) {
        const titleEl = toastEl.querySelector('[data-part="toast-title"]');
        if (titleEl) titleEl.textContent = newTitle;
        toastEl.dataset.toastTitle = newTitle;
      }
      if (newDesc !== undefined) {
        let descEl = toastEl.querySelector('[data-part="toast-description"]');
        if (!descEl && newDesc) {
          descEl = document.createElement('div');
          descEl.setAttribute('data-part', 'toast-description');
          toastEl.querySelector('[data-part="toast-text"]')?.appendChild(descEl);
        }
        if (descEl) descEl.textContent = newDesc;
        toastEl.dataset.toastDesc = newDesc;
      }
      if (newType) {
        toastEl.setAttribute('data-type', newType);
        const iconContainer = toastEl.querySelector('[data-part="toast-icon"]');
        if (iconContainer && icons[newType]) {
          iconContainer.setAttribute('data-type', newType);
          iconContainer.innerHTML = icons[newType];
        }
      }
      if (newDuration > 0 && newDuration !== Infinity) {
        pauseTimer();
        remaining = newDuration;
        startTimer();
        let progress = toastEl.querySelector('[data-part="toast-progress"]');
        if (!progress) {
          progress = document.createElement('div');
          progress.setAttribute('data-part', 'toast-progress');
          toastEl.appendChild(progress);
        }
        progress.style.animation = 'none';
        void progress.offsetHeight; // trigger reflow
        progress.style.animation = `uiToastProgress ${newDuration}ms linear forwards`;
      }
    };

    toastEl._restartTimer = () => {
      pauseTimer();
      remaining = duration;
      startTimer();
    };
    toastEl._dismiss = dismiss;
    toastEl._update = update;

    // Prepend or append depending on top/bottom
    if (this.position.startsWith('top')) {
      this.prepend(toastEl);
    } else {
      this.appendChild(toastEl);
    }

    startTimer();
    return { id, dismiss, update, element: toastEl };
  }
}

/**
 * Global toast dispatch helper
 */
function ensureToaster() {
  if (!activeToaster || !activeToaster.isConnected) {
    let existing = document.querySelector('ui-toaster, nnui-toaster');
    if (existing) {
      activeToaster = existing;
    } else {
      activeToaster = document.createElement('ui-toaster');
      document.body.appendChild(activeToaster);
    }
  }
  return activeToaster;
}

export function toast(input, maybeOptions = {}) {
  const toaster = ensureToaster();
  const options = (typeof input === 'object' && input !== null)
    ? { ...input, ...maybeOptions }
    : { title: input, ...maybeOptions };

  return toaster.createToast({
    title: options.title || '',
    description: options.description || '',
    type: options.type || 'default',
    duration: options.duration !== undefined ? options.duration : 4000,
    action: options.action || null,
    onDismiss: options.onDismiss || null,
  });
}

toast.success = (input, options = {}) => toast(input, { ...options, type: 'success' });
toast.error = (input, options = {}) => toast(input, { ...options, type: 'error' });
toast.warning = (input, options = {}) => toast(input, { ...options, type: 'warning' });
toast.info = (input, options = {}) => toast(input, { ...options, type: 'info' });
toast.loading = (input, options = {}) => toast(input, { ...options, type: 'loading', duration: Infinity });

toast.promise = async function (promise, { loading = 'Loading...', success = 'Success', error = 'Error' } = {}) {
  const loadingTitle = typeof loading === 'string' ? loading : (loading?.title || 'Loading...');
  const loadingOpts = typeof loading === 'object' ? loading : {};
  const toastRef = toast.loading(loadingTitle, loadingOpts);

  try {
    const result = await (typeof promise === 'function' ? promise() : promise);
    const successOpts = typeof success === 'function' ? success(result) : success;
    const title = typeof successOpts === 'string' ? successOpts : (successOpts?.title || 'Action completed');
    const opts = typeof successOpts === 'object' ? successOpts : {};
    toastRef.update({ title, ...opts, type: 'success', duration: 4000 });
    return result;
  } catch (err) {
    const errorOpts = typeof error === 'function' ? error(err) : error;
    const title = typeof errorOpts === 'string' ? errorOpts : (errorOpts?.title || (err?.message || 'Action failed'));
    const opts = typeof errorOpts === 'object' ? errorOpts : {};
    toastRef.update({ title, ...opts, type: 'error', duration: 5000 });
    throw err;
  }
};

toast.dismiss = (id) => {
  if (!id) {
    document.querySelectorAll('[data-ui="toast"]').forEach((t) => t.remove());
    return;
  }
  const el = document.getElementById(id);
  if (el) el.remove();
};

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys, getNextIndex, applyRovingTabindex, generateUniqueId } from '../../utils/a11y.js';

/**
 * <ui-tabs> Micro-Enhancer
 * WAI-ARIA APG Compliant Tabs Pattern
 * Invariant: Mutates attributes, never nodes. Light-DOM native.
 */
export class UiTabs extends BaseLightElement {
  static get observedAttributes() {
    return ['value', 'orientation'];
  }

  get value() {
    return this.getAttribute('value') || '';
  }

  set value(val) {
    this.setAttributeSafe(this, 'value', val);
  }

  get orientation() {
    return this.getAttribute('orientation') || 'horizontal';
  }

  set orientation(val) {
    if (val) this.setAttributeSafe(this, 'orientation', val);
    else this.removeAttributeSafe(this, 'orientation');
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'tabs');

    // Dev-mode diagnostics: only warn if template content was provided without tab triggers
    if (this.childElementCount > 0 && this._getTabs().length === 0) {
      console.warn(`[NNUI-KIT] <${this.tagName.toLowerCase()}> has no tab triggers. Add buttons with data-part="tab" or role="tab".`);
    }

    this._setupStructure();
    this._syncState();
    this._bindEvents();
  }

  _getTabs() {
    const tablist = this.querySelector('[data-part="tablist"], [role="tablist"]');
    if (tablist && tablist.closest('ui-tabs, nnui-tabs') === this) {
      return Array.from(tablist.querySelectorAll('[data-part="tab"], [role="tab"], button')).filter(
        (el) => el.closest('ui-tabs, nnui-tabs') === this
      );
    }
    return Array.from(this.querySelectorAll('[data-part="tab"], [role="tab"]')).filter(
      (el) => el.closest('ui-tabs, nnui-tabs') === this
    );
  }

  _getPanels() {
    return Array.from(this.querySelectorAll('[data-part="tabpanel"], [role="tabpanel"], div[data-part="tabpanel"]')).filter(
      (el) => el.closest('ui-tabs, nnui-tabs') === this
    );
  }

  _setupStructure() {
    const tabs = this._getTabs();
    const panels = this._getPanels();
    const baseId = this.id || generateUniqueId('tabs');

    tabs.forEach((tab, index) => {
      const tabVal = tab.dataset.value || `tab-${index}`;
      tab.dataset.value = tabVal;

      const triggerId = tab.id || `${baseId}-trigger-${index}`;
      const panelId = panels[index]?.id || `${baseId}-panel-${index}`;

      this.setAttributeSafe(tab, 'id', triggerId);
      this.setAttributeSafe(tab, 'role', 'tab');
      this.setAttributeSafe(tab, 'aria-controls', panelId);

      if (panels[index]) {
        this.setAttributeSafe(panels[index], 'id', panelId);
        this.setAttributeSafe(panels[index], 'role', 'tabpanel');
        this.setAttributeSafe(panels[index], 'aria-labelledby', triggerId);
        panels[index].dataset.value = panels[index].dataset.value || tabVal;
      }
    });

    // Default to first tab if no value is set
    if (!this.value && tabs.length > 0) {
      this.value = tabs[0].dataset.value;
    }
  }

  _syncState() {
    const tabs = this._getTabs();
    const panels = this._getPanels();
    const currentVal = this.value;

    let activeIndex = 0;

    tabs.forEach((tab, index) => {
      const isSelected = tab.dataset.value === currentVal;
      if (isSelected) activeIndex = index;

      this.setAttributeSafe(tab, 'aria-selected', isSelected ? 'true' : 'false');
      this.setAttributeSafe(tab, 'data-state', isSelected ? 'active' : 'inactive');
      this.setAttributeSafe(tab, 'tabindex', isSelected ? '0' : '-1');
    });

    panels.forEach((panel, idx) => {
      const panelVal = panel.dataset.value || tabs[idx]?.dataset?.value;
      const isSelected = panelVal === currentVal || (!panelVal && idx === activeIndex);
      this.setAttributeSafe(panel, 'data-state', isSelected ? 'active' : 'inactive');
      if (isSelected) {
        panel.removeAttribute('hidden');
        panel.style.display = '';
      } else {
        this.setAttributeSafe(panel, 'hidden', '');
        panel.style.display = 'none';
      }
    });
  }

  _bindEvents() {
    // Click delegation (scoped to this specific <ui-tabs> instance)
    this.listen(this, 'click', (e) => {
      const tab = e.target.closest('[data-part="tab"], [role="tab"]');
      if (tab && this.contains(tab) && tab.closest('ui-tabs, nnui-tabs') === this) {
        this.selectTab(tab.dataset.value);
      }
    });

    // Keyboard navigation (APG roving tabindex)
    this.listen(this, 'keydown', (e) => {
      const tab = e.target.closest('[data-part="tab"], [role="tab"]');
      if (!tab || tab.closest('ui-tabs, nnui-tabs') !== this) return;

      const tabs = this._getTabs();
      const currentIndex = tabs.indexOf(tab);
      const isVertical = this.orientation === 'vertical';
      let nextIndex = -1;

      switch (e.key) {
        case Keys.ARROW_RIGHT:
          if (!isVertical) {
            e.preventDefault();
            nextIndex = getNextIndex(currentIndex, tabs.length, 1);
          }
          break;
        case Keys.ARROW_LEFT:
          if (!isVertical) {
            e.preventDefault();
            nextIndex = getNextIndex(currentIndex, tabs.length, -1);
          }
          break;
        case Keys.ARROW_DOWN:
          if (isVertical) {
            e.preventDefault();
            nextIndex = getNextIndex(currentIndex, tabs.length, 1);
          }
          break;
        case Keys.ARROW_UP:
          if (isVertical) {
            e.preventDefault();
            nextIndex = getNextIndex(currentIndex, tabs.length, -1);
          }
          break;
        case Keys.HOME:
          e.preventDefault();
          nextIndex = 0;
          break;
        case Keys.END:
          e.preventDefault();
          nextIndex = tabs.length - 1;
          break;
        case Keys.ENTER:
        case Keys.SPACE:
        case Keys.SPACEBAR:
          e.preventDefault();
          this.selectTab(tab.dataset.value);
          return;
      }

      if (nextIndex >= 0 && nextIndex !== currentIndex) {
        const nextTab = tabs[nextIndex];
        applyRovingTabindex(tabs, nextIndex, true);
        this.selectTab(nextTab.dataset.value);
      }
    });
  }

  selectTab(val) {
    if (this.value === val) return;
    const prev = this.value;
    this.value = val;
    this._syncState();

    this.dispatch('change', {
      value: val,
      previousValue: prev,
    });
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (oldVal !== newVal && this._initialized) {
      if (name === 'value') {
        this._syncState();
      }
    }
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * <ui-dialog> Micro-Enhancer
 * Wraps native HTML <dialog> in Light-DOM with focus restoration & backdrop dismiss.
 */
export class UiDialog extends BaseLightElement {
  static get observedAttributes() {
    return ['open'];
  }

  get isOpen() {
    return this._dialog ? this._dialog.hasAttribute('open') : false;
  }

  set isOpen(val) {
    if (val) this.showModal();
    else this.close();
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'dialog-container');
    this._dialog = this.querySelector('dialog');
    this._trigger = null;

    if (!this._dialog) {
      // Light-DOM invariant: Never reparent children or create synthetic wrapper nodes.
      // If no native <dialog> exists, bind custom events to this element container.
      this._bindCustomEvents();
      return;
    }

    this._setupDialog();
    this._bindEvents();
  }

  _bindCustomEvents() {
    // 1. Trigger click inside <ui-dialog>
    this.listen(this, 'click', (e) => {
      const trigger = e.target.closest('[data-part="trigger"], [data-trigger]');
      if (trigger) {
        e.preventDefault();
        this.showModal(trigger);
        return;
      }

      // 2. Close button click
      const closeBtn = e.target.closest('[data-part="dialog-close"], [data-part="close"], [data-close]');
      if (closeBtn) {
        e.preventDefault();
        this.close('button');
        return;
      }

      // 3. Backdrop click
      const backdrop = e.target.closest('[data-part="backdrop"]');
      if (backdrop && e.target === backdrop) {
        this.close('backdrop');
      }
    });

    // 4. Global trigger support for external buttons with data-dialog-target="id"
    this.listen(document, 'click', (e) => {
      if (!this.id) return;
      const trigger = e.target.closest(`[data-dialog-target="${this.id}"], [data-target="${this.id}"]`);
      if (trigger && !this.contains(trigger)) {
        e.preventDefault();
        this.showModal(trigger);
      }
    });

    // 5. Native cancel (Esc key)
    this.listen(window, 'keydown', (e) => {
      if (e.key === 'Escape' && this.isOpen) {
        this.close('escape');
      }
    });
  }

  _setupDialog() {
    this.setAttributeSafe(this._dialog, 'data-ui', 'dialog');
    if (this.hasAttribute('open') && !this._dialog.open) {
      this.showModal();
    }
  }

  _bindEvents() {
    // 1. Trigger click inside <ui-dialog> (e.g. <button data-part="trigger">)
    this.listen(this, 'click', (e) => {
      const trigger = e.target.closest('[data-part="trigger"], [data-trigger]');
      if (trigger && (!this._dialog || !this._dialog.contains(trigger))) {
        e.preventDefault();
        this.showModal(trigger);
      }
    });

    // 2. Global trigger support for external buttons with data-dialog-target="id"
    this.listen(document, 'click', (e) => {
      if (!this.id) return;
      const trigger = e.target.closest(`[data-dialog-target="${this.id}"], [data-target="${this.id}"]`);
      if (trigger && !this.contains(trigger)) {
        e.preventDefault();
        this.showModal(trigger);
      }
    });

    // 3. Backdrop click dismiss (native <dialog> backdrop click has e.target === dialog)
    this.listen(this._dialog, 'click', (e) => {
      if (e.target !== this._dialog) return;

      const rect = this._dialog.getBoundingClientRect();
      const isInDialog = (
        rect.top <= e.clientY &&
        e.clientY <= rect.top + rect.height &&
        rect.left <= e.clientX &&
        e.clientX <= rect.left + rect.width
      );

      if (!isInDialog) {
        this.close('backdrop');
      }
    });

    // 4. Close button click delegation ([data-part="dialog-close"], [data-part="close"], [data-close])
    this.listen(this._dialog, 'click', (e) => {
      const closeBtn = e.target.closest('[data-part="dialog-close"], [data-part="close"], [data-close]');
      if (closeBtn && this._dialog.contains(closeBtn)) {
        e.preventDefault();
        this.close('button');
      }
    });

    // 5. Native cancel event (Esc key)
    this.listen(this._dialog, 'cancel', (e) => {
      this.removeAttribute('open');
      this.dispatch('close', { reason: 'escape' });
      this._restoreFocus();
    });

    // 6. Native close event
    this.listen(this._dialog, 'close', () => {
      this.removeAttribute('open');
      this.dispatch('close', { reason: 'api' });
      this._restoreFocus();
    });
  }

  get isOpen() {
    return this._dialog ? this._dialog.hasAttribute('open') : this.hasAttribute('open');
  }

  set isOpen(val) {
    if (val) this.showModal();
    else this.close();
  }

  showModal(triggerElement = null) {
    if (this._dialog) {
      if (this.isOpen) return;
      this._trigger = triggerElement || document.activeElement;
      this._dialog.showModal();
    } else {
      this._trigger = triggerElement || document.activeElement;
    }
    this.setAttributeSafe(this, 'open', '');
    this.dispatch('open');
  }

  close(reason = 'programmatic') {
    if (this._dialog && this._dialog.open) {
      this._dialog.close();
    }
    this.removeAttribute('open');
    this.dispatch('close', { reason });
    this._restoreFocus();
  }

  _restoreFocus() {
    if (this._trigger && typeof this._trigger.focus === 'function') {
      this._trigger.focus();
      this._trigger = null;
    }
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (name === 'open') {
      const hasOpen = newVal !== null;
      if (this._dialog) {
        if (hasOpen && !this._dialog.open) {
          this._dialog.showModal();
        } else if (!hasOpen && this._dialog.open) {
          this._dialog.close();
        }
      }
    }
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys, getNextIndex, generateUniqueId } from '../../utils/a11y.js';

/**
 * <ui-select> Micro-Enhancer
 * Custom dropdown with native form integration via ElementInternals.
 * Invariant: Mutates attributes, never nodes. Light-DOM native.
 */
export class UiSelect extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['value', 'name', 'required', 'disabled', 'open'];
  }

  constructor() {
    super();
    // ElementInternals provides seamless integration into native <form> submission & validation
    if (typeof this.attachInternals === 'function') {
      this._internals = this.attachInternals();
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    this.setAttributeSafe(this, 'name', val);
  }

  get value() {
    return this.getAttribute('value') || '';
  }

  set value(val) {
    this.setAttributeSafe(this, 'value', val);
    this._updateFormValue(val);
    this._syncState();
  }

  get isOpen() {
    return this.hasAttribute('open');
  }

  set isOpen(val) {
    if (val) this.open();
    else this.close();
  }

  get required() {
    return this.hasAttribute('required');
  }

  set required(val) {
    if (val) this.setAttributeSafe(this, 'required', '');
    else this.removeAttributeSafe(this, 'required');
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) this.setAttributeSafe(this, 'disabled', '');
    else this.removeAttributeSafe(this, 'disabled');
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'select');
    this._trigger = this.querySelector('[data-part="trigger"], button');
    this._valueDisplay = this.querySelector('[data-part="value"], span');
    this._listbox = this.querySelector('[data-part="listbox"], [role="listbox"], ul, ol');
    this._activeIndex = -1;

    // Dev-mode diagnostics for AI generation issues
    this.warnIfMissing('[data-part="trigger"], button', 'Trigger button');
    this.warnIfMissing('[data-part="listbox"], [role="listbox"], ul, ol', 'Dropdown listbox container');

    this._setupStructure();
    this._syncState();
    this._bindEvents();
  }

  _getOptions() {
    return Array.from(this.querySelectorAll('[data-part="option"], [role="option"], li'));
  }

  _setupStructure() {
    const baseId = this.id || generateUniqueId('select');
    const listboxId = this._listbox?.id || `${baseId}-listbox`;

    if (this._trigger) {
      this.setAttributeSafe(this._trigger, 'role', 'combobox');
      this.setAttributeSafe(this._trigger, 'aria-haspopup', 'listbox');
      this.setAttributeSafe(this._trigger, 'aria-expanded', 'false');
      this.setAttributeSafe(this._trigger, 'aria-controls', listboxId);
      this.setAttributeSafe(this._trigger, 'tabindex', this.disabled ? '-1' : '0');
    }

    if (this._listbox) {
      this.setAttributeSafe(this._listbox, 'id', listboxId);
      this.setAttributeSafe(this._listbox, 'role', 'listbox');
      this.setAttributeSafe(this._listbox, 'data-state', 'closed');
      this.setAttributeSafe(this._listbox, 'tabindex', '-1');
    }

    this._getOptions().forEach((option, idx) => {
      const optId = option.id || `${baseId}-opt-${idx}`;
      this.setAttributeSafe(option, 'id', optId);
      this.setAttributeSafe(option, 'role', 'option');
      this.setAttributeSafe(option, 'aria-selected', 'false');
    });

    // Default value check
    if (!this.value && this._getOptions().length > 0) {
      const selectedOpt = this._getOptions().find((opt) => opt.hasAttribute('selected') || opt.getAttribute('aria-selected') === 'true');
      if (selectedOpt) {
        this.value = selectedOpt.dataset.value || selectedOpt.textContent.trim();
      }
    }
  }

  _updateFormValue(val) {
    if (this._internals) {
      this._internals.setFormValue(val);
      // Native constraint validation
      if (this.required && !val) {
        this._internals.setValidity({ valueMissing: true }, 'Please select an option.', this._trigger);
      } else {
        this._internals.setValidity({});
      }
    }
  }

  _syncState() {
    const options = this._getOptions();
    const currentVal = this.value;

    let matchedOption = null;

    options.forEach((opt, index) => {
      const optVal = opt.dataset.value || opt.textContent.trim();
      const isSelected = optVal === currentVal;
      if (isSelected) {
        matchedOption = opt;
        this._activeIndex = index;
      }
      this.setAttributeSafe(opt, 'aria-selected', isSelected ? 'true' : 'false');
    });

    if (this._valueDisplay && matchedOption) {
      this._valueDisplay.textContent = matchedOption.textContent.trim();
    }
  }

  _bindEvents() {
    if (!this._trigger) return;

    // Trigger click
    this.listen(this._trigger, 'click', (e) => {
      if (this.disabled) return;
      e.preventDefault();
      this.toggle();
    });

    // Keyboard navigation
    this.listen(this, 'keydown', (e) => this._handleKeydown(e));

    // Option selection click delegation
    this.listen(this, 'click', (e) => {
      const option = e.target.closest('[data-part="option"], [role="option"]');
      if (option && this.contains(option)) {
        this.selectOption(option);
      }
    });

    // Outside click dismiss
    this.listen(document, 'pointerdown', (e) => {
      if (!this.contains(e.target) && this.isOpen) {
        this.close();
      }
    });
  }

  _handleKeydown(e) {
    if (this.disabled) return;
    const options = this._getOptions();

    switch (e.key) {
      case Keys.ENTER:
      case Keys.SPACE:
      case Keys.SPACEBAR:
        e.preventDefault();
        if (!this.isOpen) {
          this.open();
        } else if (this._activeIndex >= 0 && options[this._activeIndex]) {
          this.selectOption(options[this._activeIndex]);
        }
        break;

      case Keys.ARROW_DOWN:
        e.preventDefault();
        if (!this.isOpen) {
          this.open();
        } else {
          this._activeIndex = getNextIndex(this._activeIndex, options.length, 1);
          this._highlightOption(options[this._activeIndex]);
        }
        break;

      case Keys.ARROW_UP:
        e.preventDefault();
        if (!this.isOpen) {
          this.open();
        } else {
          this._activeIndex = getNextIndex(this._activeIndex, options.length, -1);
          this._highlightOption(options[this._activeIndex]);
        }
        break;

      case Keys.ESCAPE:
        if (this.isOpen) {
          e.preventDefault();
          this.close();
          this._trigger?.focus();
        }
        break;

      case Keys.TAB:
        this.close();
        break;
    }
  }

  _highlightOption(optionNode) {
    this._getOptions().forEach((opt) => {
      if (opt === optionNode) {
        this.setAttributeSafe(opt, 'data-focused', 'true');
        opt.scrollIntoView({ block: 'nearest' });
      } else {
        this.setAttributeSafe(opt, 'data-focused', 'false');
      }
    });
  }

  selectOption(optionNode) {
    if (!optionNode) return;
    const value = optionNode.dataset.value || optionNode.textContent.trim();
    const prev = this.value;

    this.value = value;
    this.close();
    this._trigger?.focus();

    this.dispatch('change', { value, previousValue: prev });
    this.dispatch('input', { value });
  }

  open() {
    if (this.isOpen || this.disabled) return;
    this.setAttributeSafe(this, 'open', '');
    if (this._trigger) this.setAttributeSafe(this._trigger, 'aria-expanded', 'true');
    if (this._listbox) this.setAttributeSafe(this._listbox, 'data-state', 'open');

    const options = this._getOptions();
    if (this._activeIndex >= 0 && options[this._activeIndex]) {
      this._highlightOption(options[this._activeIndex]);
    }
  }

  close() {
    if (!this.isOpen) return;
    this.removeAttribute('open');
    if (this._trigger) this.setAttributeSafe(this._trigger, 'aria-expanded', 'false');
    if (this._listbox) this.setAttributeSafe(this._listbox, 'data-state', 'closed');
  }

  toggle() {
    if (this.isOpen) this.close();
    else this.open();
  }

  // Native formResetCallback support
  formResetCallback() {
    const defaultOpt = this._getOptions().find((opt) => opt.hasAttribute('default-selected') || opt.hasAttribute('selected'));
    this.value = defaultOpt ? (defaultOpt.dataset.value || defaultOpt.textContent.trim()) : '';
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (oldVal !== newVal && this._initialized) {
      if (name === 'value') {
        this._updateFormValue(newVal);
        this._syncState();
      }
    }
  }
}

