import { Keys, getNextIndex, generateUniqueId } from '../../utils/a11y.js';

/**
 * <ui-combobox> Micro-Enhancer
 * WAI-ARIA 1.2 Combobox Pattern (Active-Descendant / Roving)
 * Invariant: Mutates attributes, never nodes. Light-DOM native.
 */
export class UiCombobox extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['value', 'open', 'name', 'disabled'];
  }

  constructor() {
    super();
    if (typeof this.attachInternals === 'function') {
      this._internals = this.attachInternals();
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    if (val) this.setAttributeSafe(this, 'name', val);
    else this.removeAttributeSafe(this, 'name');
  }

  get value() {
    return this.getAttribute('value') || '';
  }

  set value(val) {
    this.setAttributeSafe(this, 'value', val);
    this._updateFormValue(val);
  }

  get isOpen() {
    return this.hasAttribute('open');
  }

  set isOpen(val) {
    if (val) this.open();
    else this.close();
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'combobox');
    this._input = this.querySelector('[data-part="input"], input');
    this._listbox = this.querySelector('[data-part="listbox"], [role="listbox"], ul, ol');
    this._activeIndex = -1;

    // Dev-mode diagnostics for AI generation issues
    this.warnIfMissing('[data-part="input"], input', 'Input search element');
    this.warnIfMissing('[data-part="listbox"], [role="listbox"], ul, ol', 'Dropdown listbox container');

    this._setupARIA();
    this._bindEvents();
  }

  _getOptions() {
    return Array.from(this.querySelectorAll('[data-part="option"], [role="option"], li'));
  }

  _getVisibleOptions() {
    return this._getOptions().filter((opt) => !opt.hasAttribute('hidden'));
  }

  _setupARIA() {
    const baseId = this.id || generateUniqueId('combobox');
    const listboxId = this._listbox?.id || `${baseId}-listbox`;

    if (this._input) {
      this.setAttributeSafe(this._input, 'role', 'combobox');
      this.setAttributeSafe(this._input, 'aria-autocomplete', 'list');
      this.setAttributeSafe(this._input, 'aria-expanded', 'false');
      this.setAttributeSafe(this._input, 'aria-controls', listboxId);
      this.setAttributeSafe(this._input, 'autocomplete', 'off');
    }

    if (this._listbox) {
      this.setAttributeSafe(this._listbox, 'id', listboxId);
      this.setAttributeSafe(this._listbox, 'role', 'listbox');
      this.setAttributeSafe(this._listbox, 'data-state', 'closed');
    }

    this._getOptions().forEach((option, index) => {
      const optionId = option.id || `${baseId}-opt-${index}`;
      this.setAttributeSafe(option, 'id', optionId);
      this.setAttributeSafe(option, 'role', 'option');
      this.setAttributeSafe(option, 'aria-selected', 'false');
    });
  }

  _bindEvents() {
    if (!this._input) return;

    // Focus & Input events
    this.listen(this._input, 'focus', () => this.open());
    this.listen(this._input, 'input', (e) => this._handleInput(e.target.value));

    // Keyboard navigation
    this.listen(this._input, 'keydown', (e) => this._handleKeydown(e));

    // Option selection
    this.listen(this, 'click', (e) => {
      const option = e.target.closest('[data-part="option"], [role="option"]');
      if (option && this.contains(option)) {
        this.selectOption(option);
      }
    });

    // Close on outside click
    this.listen(document, 'pointerdown', (e) => {
      if (!this.contains(e.target) && this.isOpen) {
        this.close();
      }
    });
  }

  _handleInput(query) {
    if (!this.isOpen) this.open();
    const cleanQuery = query.toLowerCase().trim();
    const options = this._getOptions();

    // Mutate attributes (hidden), never remove nodes
    options.forEach((opt) => {
      const text = (opt.textContent || '').toLowerCase();
      const value = (opt.dataset.value || '').toLowerCase();
      const matches = text.includes(cleanQuery) || value.includes(cleanQuery);
      if (matches) {
        opt.removeAttribute('hidden');
      } else {
        this.setAttributeSafe(opt, 'hidden', '');
      }
    });

    this._activeIndex = -1;
    this._highlightOption(null);
  }

  _handleKeydown(e) {
    const visible = this._getVisibleOptions();

    switch (e.key) {
      case Keys.ARROW_DOWN:
        e.preventDefault();
        if (!this.isOpen) {
          this.open();
        } else {
          this._activeIndex = getNextIndex(this._activeIndex, visible.length, 1);
          this._highlightOption(visible[this._activeIndex]);
        }
        break;

      case Keys.ARROW_UP:
        e.preventDefault();
        if (!this.isOpen) {
          this.open();
        } else {
          this._activeIndex = getNextIndex(this._activeIndex, visible.length, -1);
          this._highlightOption(visible[this._activeIndex]);
        }
        break;

      case Keys.ENTER:
        if (this.isOpen && this._activeIndex >= 0 && visible[this._activeIndex]) {
          e.preventDefault();
          this.selectOption(visible[this._activeIndex]);
        }
        break;

      case Keys.ESCAPE:
        if (this.isOpen) {
          e.preventDefault();
          this.close();
        }
        break;

      case Keys.TAB:
        this.close();
        break;
    }
  }

  _highlightOption(optionNode) {
    const options = this._getOptions();
    options.forEach((opt) => {
      if (opt === optionNode) {
        this.setAttributeSafe(opt, 'data-focused', 'true');
        if (this._input) {
          this.setAttributeSafe(this._input, 'aria-activedescendant', opt.id);
        }
        opt.scrollIntoView({ block: 'nearest' });
      } else {
        this.setAttributeSafe(opt, 'data-focused', 'false');
      }
    });

    if (!optionNode && this._input) {
      this._input.removeAttribute('aria-activedescendant');
    }
  }

  selectOption(optionNode) {
    if (!optionNode) return;
    const value = optionNode.dataset.value || optionNode.textContent.trim();
    const label = optionNode.textContent.trim();

    this._getOptions().forEach((node) => {
      this.setAttributeSafe(node, 'aria-selected', node === optionNode ? 'true' : 'false');
    });

    if (this._input) {
      this._input.value = label;
    }
    this.value = value;
    this.close();

    // Dispatch standard lowercase native event
    this.dispatch('change', { value, label });
  }

  open() {
    if (this.isOpen) return;
    this.setAttributeSafe(this, 'open', '');
    if (this._input) this.setAttributeSafe(this._input, 'aria-expanded', 'true');
    if (this._listbox) this.setAttributeSafe(this._listbox, 'data-state', 'open');
  }

  close() {
    if (!this.isOpen) return;
    this.removeAttribute('open');
    if (this._input) this.setAttributeSafe(this._input, 'aria-expanded', 'false');
    if (this._listbox) this.setAttributeSafe(this._listbox, 'data-state', 'closed');
    this._activeIndex = -1;
    this._highlightOption(null);
  }

  _updateFormValue(val = this.value) {
    if (this._internals) {
      this._internals.setFormValue(val);
    }
  }

  formResetCallback() {
    const defaultOpt = this._getOptions().find((opt) => opt.hasAttribute('selected') || opt.hasAttribute('default-selected'));
    const initialVal = defaultOpt ? (defaultOpt.dataset.value || defaultOpt.textContent.trim()) : (this.getAttribute('value') || '');
    this.value = initialVal;
    if (this._input) {
      this._input.value = defaultOpt ? defaultOpt.textContent.trim() : initialVal;
    }
    this._updateFormValue(initialVal);
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys, getNextIndex, generateUniqueId } from '../../utils/a11y.js';

/**
 * <ui-accordion> Micro-Enhancer
 * WAI-ARIA APG Compliant Accordion Pattern
 * Invariant: Mutates attributes, never nodes. Light-DOM native.
 */
export class UiAccordion extends BaseLightElement {
  static get observedAttributes() {
    return ['type', 'collapsible'];
  }

  get type() {
    return this.getAttribute('type') || 'single'; // 'single' | 'multiple'
  }

  set type(val) {
    if (val) this.setAttribute('type', val);
    else this.removeAttribute('type');
  }

  get collapsible() {
    return this.getAttribute('collapsible') !== 'false';
  }

  set collapsible(val) {
    if (val === false || val === 'false') {
      this.setAttribute('collapsible', 'false');
    } else {
      this.removeAttribute('collapsible');
    }
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'accordion');
    this._setupStructure();
    this._bindEvents();
  }

  _getItems() {
    return Array.from(this.querySelectorAll('[data-part="item"]'));
  }

  _getTriggers() {
    return Array.from(this.querySelectorAll('[data-part="trigger"]'));
  }

  _setupStructure() {
    const baseId = this.id || generateUniqueId('accordion');
    const items = this._getItems();

    items.forEach((item, index) => {
      const trigger = item.querySelector('[data-part="trigger"]');
      const content = item.querySelector('[data-part="content"]');

      if (trigger && content) {
        const triggerId = trigger.id || `${baseId}-trigger-${index}`;
        const contentId = content.id || `${baseId}-content-${index}`;

        this.setAttributeSafe(trigger, 'id', triggerId);
        this.setAttributeSafe(trigger, 'aria-controls', contentId);
        this.setAttributeSafe(content, 'id', contentId);
        this.setAttributeSafe(content, 'role', 'region');
        this.setAttributeSafe(content, 'aria-labelledby', triggerId);

        const isOpen = item.getAttribute('data-state') === 'open' || trigger.getAttribute('aria-expanded') === 'true';
        this.setAttributeSafe(trigger, 'aria-expanded', isOpen ? 'true' : 'false');
        this.setAttributeSafe(item, 'data-state', isOpen ? 'open' : 'closed');
        this.setAttributeSafe(content, 'data-state', isOpen ? 'open' : 'closed');

        // Ensure inner content wrapper for smooth CSS grid height animation
        if (!content.querySelector('[data-part="content-inner"]')) {
          const inner = document.createElement('div');
          inner.setAttribute('data-part', 'content-inner');
          while (content.firstChild) {
            inner.appendChild(content.firstChild);
          }
          content.appendChild(inner);
        }

        if (!isOpen) {
          content.setAttribute('hidden', '');
        } else {
          content.removeAttribute('hidden');
        }
      }
    });
  }

  _bindEvents() {
    // Click delegation
    this.listen(this, 'click', (e) => {
      const trigger = e.target.closest('[data-part="trigger"]');
      if (trigger && this.contains(trigger)) {
        e.preventDefault();
        const item = trigger.closest('[data-part="item"]');
        if (item) {
          this.toggleItem(item);
        }
      }
    });

    // Keyboard navigation (Up/Down/Home/End)
    this.listen(this, 'keydown', (e) => {
      const trigger = e.target.closest('[data-part="trigger"]');
      if (!trigger) return;

      const triggers = this._getTriggers();
      const currentIndex = triggers.indexOf(trigger);
      let nextIndex = -1;

      switch (e.key) {
        case Keys.ARROW_DOWN:
          e.preventDefault();
          nextIndex = getNextIndex(currentIndex, triggers.length, 1);
          break;
        case Keys.ARROW_UP:
          e.preventDefault();
          nextIndex = getNextIndex(currentIndex, triggers.length, -1);
          break;
        case Keys.HOME:
          e.preventDefault();
          nextIndex = 0;
          break;
        case Keys.END:
          e.preventDefault();
          nextIndex = triggers.length - 1;
          break;
      }

      if (nextIndex >= 0 && nextIndex !== currentIndex) {
        triggers[nextIndex]?.focus();
      }
    });
  }

  toggleItem(targetItem) {
    const isSingle = this.type === 'single';
    const isCurrentlyOpen = targetItem.getAttribute('data-state') === 'open';

    if (isCurrentlyOpen && !this.collapsible && isSingle) {
      return; // Cannot collapse if non-collapsible single mode
    }

    if (isSingle) {
      this._getItems().forEach((item) => {
        const shouldOpen = item === targetItem && !isCurrentlyOpen;
        this._setItemState(item, shouldOpen);
      });
    } else {
      this._setItemState(targetItem, !isCurrentlyOpen);
    }

    const value = targetItem.dataset.value || '';
    this.dispatch('change', {
      value,
      open: !isCurrentlyOpen,
    });
  }

  _setItemState(item, open) {
    const trigger = item.querySelector('[data-part="trigger"]');
    const content = item.querySelector('[data-part="content"]');

    if (open) {
      this.setAttributeSafe(item, 'data-state', 'open');
      if (trigger) {
        this.setAttributeSafe(trigger, 'aria-expanded', 'true');
      }
      if (content) {
        content.removeAttribute('hidden');
        // Double rAF ensures browser paints the unhidden 0fr grid box before transitioning to 1fr
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            if (item.getAttribute('data-state') === 'open') {
              this.setAttributeSafe(content, 'data-state', 'open');
            }
          });
        });
      }
    } else {
      this.setAttributeSafe(item, 'data-state', 'closed');
      if (trigger) {
        this.setAttributeSafe(trigger, 'aria-expanded', 'false');
      }
      if (content) {
        this.setAttributeSafe(content, 'data-state', 'closed');
        // Smoothly wait for CSS transition to collapse before setting hidden
        let closed = false;
        const finalizeClose = () => {
          if (closed) return;
          closed = true;
          if (item.getAttribute('data-state') === 'closed') {
            content.setAttribute('hidden', '');
          }
          content.removeEventListener('transitionend', finalizeClose);
        };
        content.addEventListener('transitionend', finalizeClose, { once: true });
        setTimeout(finalizeClose, 280);
      }
    }
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { applyPositionFallback } from '../../utils/anchor-fallback.js';
import { generateUniqueId } from '../../utils/a11y.js';

/**
 * <ui-popover> Micro-Enhancer
 * Couples Native Popover API with universal viewport positioning fallback.
 */
export class UiPopover extends BaseLightElement {
  init() {
    this.setAttributeSafe(this, 'data-ui', 'popover');
    this._trigger = this.querySelector('[data-part="trigger"]');
    this._panel = this.querySelector('[data-part="popover-panel"], [data-part="content"], [popover]');

    if (!this._trigger || !this._panel) return;

    this._setupPopover();
    this._bindEvents();
  }

  _setupPopover() {
    const baseId = this.id || generateUniqueId('popover');
    const panelId = this._panel.id || `${baseId}-panel`;

    this.setAttributeSafe(this._panel, 'id', panelId);
    this.setAttributeSafe(this._panel, 'popover', this._panel.getAttribute('popover') || 'auto');
    this.setAttributeSafe(this._panel, 'data-ui', 'popover-content');
    this.setAttributeSafe(this._panel, 'data-part', 'popover-panel');

    // Link trigger via native popovertarget
    this.setAttributeSafe(this._trigger, 'popovertarget', panelId);
    this.setAttributeSafe(this._trigger, 'aria-haspopup', 'dialog');
    this.setAttributeSafe(this._trigger, 'aria-expanded', 'false');
  }

  _bindEvents() {
    // Native Popover toggle event (fired whenever popover opens or closes)
    this.listen(this._panel, 'toggle', (e) => {
      const isOpen = e.newState === 'open';
      this.setAttributeSafe(this._trigger, 'aria-expanded', isOpen ? 'true' : 'false');
      this.setAttributeSafe(this._panel, 'data-state', isOpen ? 'open' : 'closed');

      if (isOpen) {
        // Wait one frame so browser calculates dimensions of top-layer element
        requestAnimationFrame(() => {
          this._reposition();
        });
      }

      this.dispatch('toggle', { open: isOpen });
    });

    // Fallback trigger click if browser lacks popovertarget handling
    this.listen(this._trigger, 'click', (e) => {
      if (typeof this._panel.showPopover === 'function') {
        // Handled natively by popovertarget, but guarantee position update
        requestAnimationFrame(() => {
          if (this._panel.matches(':popover-open')) {
            this._reposition();
          }
        });
      } else {
        // Fallback for non-popover supporting browsers
        e.preventDefault();
        const isOpen = this._panel.getAttribute('data-state') === 'open';
        if (isOpen) {
          this.hide();
        } else {
          this.show();
        }
      }
    });

    // Auto-update position on window resize or page scroll
    const onScrollOrResize = () => {
      if (this.isOpen) {
        this._reposition();
      }
    };

    this.listen(window, 'resize', onScrollOrResize, { passive: true });
    this.listen(window, 'scroll', onScrollOrResize, { passive: true });
  }

  get isOpen() {
    if (!this._panel) return false;
    return (
      (typeof this._panel.matches === 'function' && this._panel.matches(':popover-open')) ||
      this._panel.getAttribute('data-state') === 'open'
    );
  }

  set isOpen(val) {
    if (val) this.show();
    else this.hide();
  }

  _reposition() {
    if (!this._trigger || !this._panel) return;
    applyPositionFallback(this._trigger, this._panel, 'bottom', 8);
  }

  show() {
    if (!this._panel) return;
    this.setAttributeSafe(this._panel, 'data-state', 'open');
    if (this._trigger) {
      this.setAttributeSafe(this._trigger, 'aria-expanded', 'true');
    }
    if (typeof this._panel.showPopover === 'function') {
      try {
        if (!this._panel.matches(':popover-open')) {
          this._panel.showPopover();
        }
      } catch (e) {}
    }
    this._reposition();
  }

  hide() {
    if (!this._panel) return;
    this.setAttributeSafe(this._panel, 'data-state', 'closed');
    if (this._trigger) {
      this.setAttributeSafe(this._trigger, 'aria-expanded', 'false');
    }
    if (typeof this._panel.hidePopover === 'function') {
      try {
        if (this._panel.matches(':popover-open')) {
          this._panel.hidePopover();
        }
      } catch (e) {}
    }
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys, generateUniqueId } from '../../utils/a11y.js';

/**
 * <ui-tooltip> Micro-Enhancer
 * Accessible tooltip with hover/focus triggers, escape dismiss, and automatic ARIA bindings.
 */
export class UiTooltip extends BaseLightElement {
  static get observedAttributes() {
    return ['delay'];
  }

  get delay() {
    return parseInt(this.getAttribute('delay') || '150', 10);
  }

  set delay(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe(this, 'delay', String(val));
    else this.removeAttributeSafe(this, 'delay');
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'tooltip');
    this._trigger = this.querySelector('[data-part="trigger"]');
    this._content = this.querySelector('[data-part="content"], [data-ui="tooltip-content"]');
    this._timer = null;

    if (!this._trigger || !this._content) return;

    // Ensure content does not have stray popover attribute causing browser UA display:none
    if (this._content.hasAttribute('popover')) {
      this._content.removeAttribute('popover');
    }

    this._setupARIA();
    this._bindEvents();
  }

  _setupARIA() {
    const baseId = this.id || generateUniqueId('tooltip');
    const contentId = this._content.id || `${baseId}-content`;

    this.setAttributeSafe(this._content, 'id', contentId);
    this.setAttributeSafe(this._content, 'role', 'tooltip');
    this.setAttributeSafe(this._trigger, 'aria-describedby', contentId);
  }

  _bindEvents() {
    // Pointer hover
    this.listen(this, 'pointerenter', () => this.scheduleShow());
    this.listen(this, 'pointerleave', () => this.hide());

    // Focus triggers for keyboard accessibility
    this.listen(this._trigger, 'focusin', () => this.show());
    this.listen(this._trigger, 'focusout', () => this.hide());

    // Dismiss on Escape
    this.listen(window, 'keydown', (e) => {
      if (e.key === Keys.ESCAPE && this.getAttribute('data-state') === 'visible') {
        this.hide();
      }
    });
  }

  scheduleShow() {
    this.clearTimer();
    this._timer = setTimeout(() => {
      this.show();
    }, this.delay);
  }

  show() {
    this.clearTimer();
    this.setAttributeSafe(this, 'data-state', 'visible');
    if (this._content) {
      this.setAttributeSafe(this._content, 'data-state', 'visible');
    }
  }

  hide() {
    this.clearTimer();
    this.setAttributeSafe(this, 'data-state', 'hidden');
    if (this._content) {
      this.setAttributeSafe(this._content, 'data-state', 'hidden');
    }
  }

  clearTimer() {
    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }
  }

  destroy() {
    this.clearTimer();
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { generateUniqueId } from '../../utils/a11y.js';

/**
 * UiCommand
 * Platform-Native, Light-DOM Command Palette & Spotlight Search.
 * 
 * Invariants:
 * 1. Zero Shadow DOM: All child elements remain in Light-DOM.
 * 2. Mutate Attributes, Never Nodes: Filters using [hidden] rather than removing DOM nodes.
 * 3. WAI-ARIA APG active-descendant navigation.
 */
export class UiCommand extends BaseLightElement {
  static get observedAttributes() {
    return ['open', 'shortcut'];
  }

  constructor() {
    super();
    this._activeIndex = -1;
    this._isOpen = false;
  }

  init() {
    this.warnIfMissing('[data-part="input"]', 'Command input field');
    this.warnIfMissing('[data-part="item"]', 'Command item');

    this._dialog = this.querySelector('dialog[data-part="dialog"]');
    this._input = this.querySelector('[data-part="input"]');
    this._list = this.querySelector('[data-part="list"]') || this;
    this._empty = this.querySelector('[data-part="empty"]');

    this._setupDialog();
    this._setupInput();
    this._setupList();
    this._setupGlobalShortcut();

    // Initial filter run to index items
    this.filter('');
  }

  _setupDialog() {
    if (!this._dialog) return;

    // Handle backdrop click to close
    this.listen(this._dialog, 'click', (e) => {
      if (e.target !== this._dialog) return;
      const rect = this._dialog.getBoundingClientRect();
      const isInDialog = (
        rect.top <= e.clientY &&
        e.clientY <= rect.top + rect.height &&
        rect.left <= e.clientX &&
        e.clientX <= rect.left + rect.width
      );
      if (!isInDialog) {
        this.close();
      }
    });

    this.listen(this._dialog, 'close', () => {
      this._isOpen = false;
      this.removeAttribute('open');
      this.dispatch('close');
    });

    this.listen(this._dialog, 'keydown', (e) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        this.close();
      }
    });
  }

  _setupInput() {
    if (!this._input) return;

    this.setAttributeSafe(this._input, 'role', 'combobox');
    this.setAttributeSafe(this._input, 'aria-autocomplete', 'list');
    this.setAttributeSafe(this._input, 'aria-expanded', 'true');

    // Input search typing
    this.listen(this._input, 'input', (e) => {
      this.filter(e.target.value);
    });

    // Keyboard navigation
    this.listen(this._input, 'keydown', (e) => {
      const items = this._getVisibleItems();
      if (!items.length) return;

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          this._moveActive(1);
          break;
        case 'ArrowUp':
          e.preventDefault();
          this._moveActive(-1);
          break;
        case 'Enter':
          e.preventDefault();
          if (this._activeIndex >= 0 && this._activeIndex < items.length) {
            this.selectItem(items[this._activeIndex]);
          }
          break;
        case 'Home':
          e.preventDefault();
          this._setActive(0);
          break;
        case 'End':
          e.preventDefault();
          this._setActive(items.length - 1);
          break;
      }
    });
  }

  _setupList() {
    // Click on items
    this.listen(this._list, 'click', (e) => {
      const item = e.target.closest('[data-part="item"]');
      if (item && !item.hasAttribute('disabled')) {
        this.selectItem(item);
      }
    });

    // Mouse hover updates active item
    this.listen(this._list, 'mousemove', (e) => {
      const item = e.target.closest('[data-part="item"]');
      if (item && !item.hasAttribute('disabled')) {
        const items = this._getVisibleItems();
        const idx = items.indexOf(item);
        if (idx !== -1 && idx !== this._activeIndex) {
          this._setActive(idx);
        }
      }
    });
  }

  _setupGlobalShortcut() {
    // Only bind global shortcut if shortcut attribute is explicitly defined and not 'none'
    const shortcut = this.getAttribute('shortcut');
    if (!shortcut || shortcut === 'none') return;

    this.listen(window, 'keydown', (e) => {
      if (e.defaultPrevented) return;
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === shortcut.toLowerCase()) {
        e.preventDefault();
        this.toggle();
      }
    });
  }

  _getVisibleItems() {
    return Array.from(this.querySelectorAll('[data-part="item"]')).filter(
      (item) => !item.hasAttribute('hidden') && item.style.display !== 'none'
    );
  }

  _moveActive(step) {
    const items = this._getVisibleItems();
    if (!items.length) return;

    let next = this._activeIndex + step;
    if (next < 0) next = items.length - 1;
    if (next >= items.length) next = 0;

    this._setActive(next);
  }

  _setActive(index) {
    const items = this._getVisibleItems();
    items.forEach((item, idx) => {
      const isActive = idx === index;
      this.setAttributeSafe(item, 'data-active', isActive ? 'true' : false);
      this.setAttributeSafe(item, 'aria-selected', isActive ? 'true' : false);
      if (isActive) {
        if (!item.id) item.id = generateUniqueId('cmd-item');
        if (this._input) {
          this.setAttributeSafe(this._input, 'aria-activedescendant', item.id);
        }
        item.scrollIntoView({ block: 'nearest' });
      }
    });
    this._activeIndex = index;
  }

  filter(query) {
    const q = (query || '').trim().toLowerCase();
    const items = Array.from(this.querySelectorAll('[data-part="item"]'));
    let visibleCount = 0;

    items.forEach((item) => {
      const value = (item.getAttribute('data-value') || '').toLowerCase();
      const text = item.textContent.toLowerCase();
      const keywords = (item.getAttribute('data-keywords') || '').toLowerCase();

      const matches = !q || value.includes(q) || text.includes(q) || keywords.includes(q);

      if (matches) {
        item.removeAttribute('hidden');
        visibleCount++;
      } else {
        item.setAttribute('hidden', '');
        item.removeAttribute('data-active');
        item.removeAttribute('aria-selected');
      }
    });

    // Check parent groups and hide empty ones
    const groups = Array.from(this.querySelectorAll('[data-part="group"]'));
    groups.forEach((group) => {
      const groupVisibleItems = group.querySelectorAll('[data-part="item"]:not([hidden])');
      if (groupVisibleItems.length === 0) {
        group.setAttribute('hidden', '');
      } else {
        group.removeAttribute('hidden');
      }
    });

    // Toggle empty state message
    if (this._empty) {
      if (visibleCount === 0) {
        this._empty.removeAttribute('hidden');
      } else {
        this._empty.setAttribute('hidden', '');
      }
    }

    // Reset active index to first item
    this._setActive(visibleCount > 0 ? 0 : -1);
  }

  selectItem(item) {
    const value = item.getAttribute('data-value') || item.textContent.trim();
    const label = item.textContent.trim();

    this.dispatch('change', { value, label, item });
    this.dispatch('select', { value, label, item });

    if (this._dialog && this._isOpen) {
      this.close();
    }
  }

  showModal(triggerElement = null) {
    if (this._dialog && !this._dialog.open) {
      this._dialog.showModal();
      this._isOpen = true;
      this.setAttribute('open', '');
      this.filter('');
      if (this._input) {
        this._input.value = '';
        setTimeout(() => this._input.focus(), 50);
      }
      this.dispatch('open');
    }
  }

  open() {
    this.showModal();
  }

  close() {
    if (this._dialog && this._dialog.open) {
      this._dialog.close();
      this._isOpen = false;
      this.removeAttribute('open');
    }
  }

  toggle() {
    if (this._isOpen || (this._dialog && this._dialog.open)) {
      this.close();
    } else {
      this.showModal();
    }
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (name === 'open') {
      if (newVal !== null && !this._isOpen) {
        this.showModal();
      } else if (newVal === null && this._isOpen) {
        this.close();
      }
    }
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * UiSheet
 * Platform-Native, Light-DOM Slide-Out Sheet / Drawer.
 * 
 * Invariants:
 * 1. Zero Shadow DOM: Pure Light-DOM rendering.
 * 2. Uses native browser <dialog> top-layer for guaranteed focus-trap & accessibility.
 * 3. Sides: right (default), left, top, bottom.
 */
export class UiSheet extends BaseLightElement {
  static get observedAttributes() {
    return ['open', 'side'];
  }

  constructor() {
    super();
    this._isOpen = false;
    this._isClosing = false;
  }

  init() {
    this.warnIfMissing('dialog[data-part="dialog"]', 'Native dialog sheet element');

    this._dialog = this.querySelector('dialog[data-part="dialog"]');
    this._trigger = this.querySelector('[data-part="trigger"]');

    if (!this.hasAttribute('side')) {
      this.setAttribute('side', 'right');
    }

    this._setupTrigger();
    this._setupDialog();
    this._setupCloseButtons();
  }

  _setupTrigger() {
    if (this._trigger) {
      this.listen(this._trigger, 'click', (e) => {
        e.preventDefault();
        this.showModal(this._trigger);
      });
    }
  }

  _setupDialog() {
    if (!this._dialog) return;

    // Click on backdrop dismisses the sheet
    this.listen(this._dialog, 'click', (e) => {
      const rect = this._dialog.getBoundingClientRect();
      const isInDialog = (
        rect.top <= e.clientY &&
        e.clientY <= rect.top + rect.height &&
        rect.left <= e.clientX &&
        e.clientX <= rect.left + rect.width
      );
      if (!isInDialog && !this._isClosing) {
        this.close('backdrop');
      }
    });

    this.listen(this._dialog, 'keydown', (e) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        if (!this._isClosing) {
          this.close('escape');
        }
      }
    });

    this.listen(this._dialog, 'close', () => {
      this._isOpen = false;
      this._isClosing = false;
      this.removeAttribute('open');
      this.removeAttribute('data-closing');
      this.dispatch('close');
    });
  }

  _setupCloseButtons() {
    const closeBtns = this.querySelectorAll('[data-part="close"]');
    closeBtns.forEach((btn) => {
      this.listen(btn, 'click', () => {
        this.close('close-button');
      });
    });
  }

  showModal(triggerElement = null) {
    if (!this._dialog) return;
    this._triggerElement = triggerElement || this._trigger;

    this._dialog.showModal();
    this._isOpen = true;
    this._isClosing = false;
    this.setAttribute('open', '');
    this.removeAttribute('data-closing');
    this.dispatch('open');
  }

  open() {
    this.showModal();
  }

  close(reason = 'programmatic') {
    if (!this._dialog || !this._dialog.open || this._isClosing) return;

    this._isClosing = true;
    this.removeAttribute('open');
    this.setAttribute('data-closing', 'true');

    // Wait for slide-out CSS transition before calling native dialog.close()
    const handleTransitionEnd = () => {
      this._dialog.removeEventListener('animationend', handleTransitionEnd);
      this._dialog.removeEventListener('transitionend', handleTransitionEnd);
      if (this._dialog.open) {
        this._dialog.close(reason);
      }
      this._isClosing = false;
      this.removeAttribute('data-closing');
      if (this._triggerElement) {
        try {
          this._triggerElement.focus();
        } catch (_) {}
      }
    };

    this._dialog.addEventListener('animationend', handleTransitionEnd, { once: true });
    this._dialog.addEventListener('transitionend', handleTransitionEnd, { once: true });

    // Fallback timer in case transitions are disabled in user styles
    setTimeout(handleTransitionEnd, 300);
  }

  toggle() {
    if (this._isOpen) {
      this.close();
    } else {
      this.showModal();
    }
  }

  get side() {
    return this.getAttribute('side') || 'right';
  }

  set side(val) {
    this.setAttribute('side', val);
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (name === 'open') {
      if (newVal !== null && !this._isOpen) {
        this.showModal();
      } else if (newVal === null && this._isOpen && !this._isClosing) {
        this.close();
      }
    }
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * UiSlider
 * Platform-Native, Light-DOM Accessible Range Slider.
 * 
 * Invariants:
 * 1. Zero Shadow DOM: All child elements remain in Light-DOM.
 * 2. Form Associated: Uses ElementInternals (attachInternals) for native form submission.
 * 3. WAI-ARIA role="slider" with full keyboard and pointer dragging.
 */
export class UiSlider extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['value', 'min', 'max', 'step', 'disabled', 'name'];
  }

  constructor() {
    super();
    if (typeof this.attachInternals === 'function') {
      this._internals = this.attachInternals();
    }
    this._value = 0;
    this._isDragging = false;
  }

  init() {
    // If no children were authored in template, auto-scaffold track, range & thumb
    if (this.childElementCount === 0) {
      const track = document.createElement('div');
      track.setAttribute('data-part', 'track');
      track.className = 'ui-slider-track';

      const range = document.createElement('div');
      range.setAttribute('data-part', 'range');
      range.className = 'ui-slider-range';
      track.appendChild(range);

      const thumb = document.createElement('div');
      thumb.setAttribute('data-part', 'thumb');
      thumb.className = 'ui-slider-thumb';

      this.appendChild(track);
      this.appendChild(thumb);
    } else {
      this.warnIfMissing('[data-part="track"]', 'Slider track');
      this.warnIfMissing('[data-part="thumb"]', 'Slider thumb');
    }

    this._track = this.querySelector('[data-part="track"]') || this;
    this._range = this.querySelector('[data-part="range"]');
    this._thumb = this.querySelector('[data-part="thumb"]');
    this._valueDisplay = this.querySelector('[data-part="value"]');

    // Parse initial value from attributes
    const initialVal = parseFloat(this.getAttribute('value')) || this.min;
    this._value = this._clamp(initialVal);

    this._setupAria();
    this._setupEvents();
    this._updateVisuals();
    this._updateFormValue();
  }

  _setupAria() {
    if (!this._thumb) return;

    this.setAttributeSafe(this._thumb, 'role', 'slider');
    this.setAttributeSafe(this._thumb, 'tabindex', this.disabled ? '-1' : '0');
    this.setAttributeSafe(this._thumb, 'aria-valuemin', this.min);
    this.setAttributeSafe(this._thumb, 'aria-valuemax', this.max);
    this.setAttributeSafe(this._thumb, 'aria-valuenow', this._value);
    this.setAttributeSafe(this._thumb, 'aria-orientation', 'horizontal');
  }

  _setupEvents() {
    if (this.disabled) return;

    // Keyboard controls on thumb
    if (this._thumb) {
      this.listen(this._thumb, 'keydown', (e) => {
        if (this.disabled) return;
        const step = this.step;
        let newValue = this._value;

        switch (e.key) {
          case 'ArrowRight':
          case 'ArrowUp':
            e.preventDefault();
            newValue += step;
            break;
          case 'ArrowLeft':
          case 'ArrowDown':
            e.preventDefault();
            newValue -= step;
            break;
          case 'PageUp':
            e.preventDefault();
            newValue += step * 10;
            break;
          case 'PageDown':
            e.preventDefault();
            newValue -= step * 10;
            break;
          case 'Home':
            e.preventDefault();
            newValue = this.min;
            break;
          case 'End':
            e.preventDefault();
            newValue = this.max;
            break;
          default:
            return;
        }

        this.value = newValue;
        this.dispatch('input', { value: this._value });
        this.dispatch('change', { value: this._value });
      });
    }

    // Pointer Dragging on Track or Thumb
    const onPointerDown = (e) => {
      if (this.disabled || e.button !== 0) return;
      this._isDragging = true;
      this.setPointerCapture?.(e.pointerId);
      this.setAttribute('data-dragging', 'true');
      if (this._thumb) this._thumb.focus();

      this._updateFromPointer(e);
      this.dispatch('input', { value: this._value });
    };

    const onPointerMove = (e) => {
      if (!this._isDragging || this.disabled) return;
      this._updateFromPointer(e);
      this.dispatch('input', { value: this._value });
    };

    const onPointerUp = (e) => {
      if (!this._isDragging) return;
      this._isDragging = false;
      this.removeAttribute('data-dragging');
      try {
        this.releasePointerCapture?.(e.pointerId);
      } catch (_) {}

      this._updateFromPointer(e);
      this.dispatch('change', { value: this._value });
    };

    this.listen(this, 'pointerdown', onPointerDown);
    this.listen(this, 'pointermove', onPointerMove);
    this.listen(this, 'pointerup', onPointerUp);
    this.listen(this, 'pointercancel', onPointerUp);
  }

  _updateFromPointer(e) {
    const trackRect = (this._track || this).getBoundingClientRect();
    if (trackRect.width === 0) return;

    const offsetX = Math.max(0, Math.min(e.clientX - trackRect.left, trackRect.width));
    const percent = offsetX / trackRect.width;

    const rawValue = this.min + percent * (this.max - this.min);
    this.value = rawValue;
  }

  _clamp(val) {
    const min = this.min;
    const max = this.max;
    const step = this.step;

    // Step snapping
    const stepped = Math.round((val - min) / step) * step + min;
    const clamped = Math.max(min, Math.min(max, stepped));
    return parseFloat(clamped.toFixed(4));
  }

  _updateVisuals() {
    const percent = ((this._value - this.min) / (this.max - this.min)) * 100;

    if (this._range) {
      this._range.style.width = `${percent}%`;
    }
    if (this._thumb) {
      this._thumb.style.left = `${percent}%`;
      this.setAttributeSafe(this._thumb, 'aria-valuenow', this._value);
    }
    if (this._valueDisplay) {
      this._valueDisplay.textContent = String(this._value);
    }
  }

  _updateFormValue() {
    if (this._internals) {
      this._internals.setFormValue(String(this._value));
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    if (val) this.setAttributeSafe('name', val);
    else this.removeAttributeSafe('name');
  }

  get value() {
    return this._value;
  }

  set value(val) {
    const clamped = this._clamp(Number(val));
    if (this._value !== clamped) {
      this._value = clamped;
      this.setAttributeSafe(this, 'value', clamped);
      this._updateVisuals();
      this._updateFormValue();
    }
  }

  get min() {
    return parseFloat(this.getAttribute('min')) || 0;
  }

  set min(val) {
    if (val !== null && val !== undefined) this.setAttribute('min', String(val));
    else this.removeAttribute('min');
  }

  get max() {
    return parseFloat(this.getAttribute('max')) || 100;
  }

  set max(val) {
    if (val !== null && val !== undefined) this.setAttribute('max', String(val));
    else this.removeAttribute('max');
  }

  get step() {
    return parseFloat(this.getAttribute('step')) || 1;
  }

  set step(val) {
    if (val !== null && val !== undefined) this.setAttribute('step', String(val));
    else this.removeAttribute('step');
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) this.setAttribute('disabled', '');
    else this.removeAttribute('disabled');
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (name === 'value' && newVal !== null) {
      const num = parseFloat(newVal);
      if (!isNaN(num) && num !== this._value) {
        this._value = this._clamp(num);
        this._updateVisuals();
        this._updateFormValue();
      }
    } else if (['min', 'max', 'step'].includes(name)) {
      this._value = this._clamp(this._value);
      this._setupAria();
      this._updateVisuals();
    } else if (name === 'disabled') {
      if (this._thumb) {
        this.setAttributeSafe(this._thumb, 'tabindex', this.disabled ? '-1' : '0');
      }
    }
  }

  formResetCallback() {
    const initialVal = parseFloat(this.getAttribute('value')) || this.min;
    this.value = initialVal;
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * <ui-data-table> Micro-Enhancer
 * High-performance, accessible Light-DOM Data Table.
 * Features:
 * - Column sorting (numeric, date, string) with aria-sort & indicators
 * - Client-side search filtering with pre-cached text search
 * - Slice pagination (Previous, Next, page count)
 * - Row selection with indeterminate "Select All" checkbox
 * - Invariant: Mutates attributes, moves existing nodes without destroying DOM references.
 */
export class UiDataTable extends BaseLightElement {
  static get observedAttributes() {
    return ['page-size', 'page', 'sort-key', 'sort-dir', 'search'];
  }

  get pageSize() {
    const sz = parseInt(this.getAttribute('page-size'), 10);
    return isNaN(sz) || sz <= 0 ? 10 : sz;
  }

  set pageSize(val) {
    this.setAttribute('page-size', String(val));
  }

  get currentPage() {
    const p = parseInt(this.getAttribute('page'), 10);
    return isNaN(p) || p <= 0 ? 1 : p;
  }

  set currentPage(val) {
    this.setAttribute('page', String(val));
  }

  get totalPages() {
    return Math.max(1, Math.ceil(this._filteredRows.length / this.pageSize));
  }

  set totalPages(_) {}

  init() {
    this.setAttributeSafe(this, 'data-ui', 'data-table');

    this._tbody = this.querySelector('tbody[data-part="tbody"], tbody');
    this._thead = this.querySelector('thead');
    this._searchInput = this.querySelector('input[data-part="search"]');
    this._selectAllCheckbox = this.querySelector('input[data-part="select-all"]');
    this._prevBtn = this.querySelector('[data-part="prev-btn"]');
    this._nextBtn = this.querySelector('[data-part="next-btn"]');
    this._pageInfo = this.querySelector('[data-part="pagination-info"], [data-part="page-info"]');
    this._selectionCount = this.querySelector('[data-part="selection-count"]');
    this._bulkActions = this.querySelector('[data-part="bulk-actions"], [data-part="selection-bar"]');
    this._bulkCount = this.querySelector('[data-part="bulk-count"]');
    this._exportBtn = this.querySelector('[data-part="export-csv"], [data-action="export-csv"]');

    if (this._exportBtn) {
      this._exportBtn.addEventListener('click', () => this.exportCsv());
    }

    if (!this._tbody) return;

    // Cache rows and their search text
    this._allRows = Array.from(this._tbody.querySelectorAll('tr'));
    this._allRows.forEach((tr, i) => {
      if (!tr.hasAttribute('data-row-id')) {
        tr.setAttribute('data-row-id', String(i + 1));
      }
      tr._searchCache = tr.textContent.toLowerCase();
    });

    this._filteredRows = [...this._allRows];
    this._selectedIds = new Set();

    this._setupHeaders();
    this._setupSearch();
    this._setupPagination();
    this._setupSelection();

    this._applyFilterAndSort();
    this._renderPage();
  }

  _setupHeaders() {
    if (!this._thead) return;

    this._sortHeaders = Array.from(
      this._thead.querySelectorAll('th[data-sortable="true"], th[data-sort-key]')
    );

    this._sortHeaders.forEach((th) => {
      this.setAttributeSafe(th, 'role', 'columnheader');
      this.setAttributeSafe(th, 'tabindex', '0');
      this.setAttributeSafe(th, 'aria-sort', 'none');

      const colIndex = th.parentNode ? Array.from(th.parentNode.children).indexOf(th) : 0;
      const clickHandler = () => this._handleHeaderClick(th, colIndex);
      th.addEventListener('click', clickHandler);
      th.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          clickHandler();
        }
      });
    });
  }

  _handleHeaderClick(th, colIndex) {
    const key = th.getAttribute('data-sort-key') || String(colIndex);
    const currentSort = th.getAttribute('aria-sort');
    let nextSort = 'ascending';

    if (currentSort === 'ascending') {
      nextSort = 'descending';
    } else if (currentSort === 'descending') {
      nextSort = 'none';
    }

    // Reset all headers
    this._sortHeaders.forEach((h) => {
      h.setAttribute('aria-sort', 'none');
      const icon = h.querySelector('[data-part="sort-icon"], [data-part="sort-indicator"]');
      if (icon) icon.textContent = '⇅';
    });

    if (nextSort !== 'none') {
      th.setAttribute('aria-sort', nextSort);
      const icon = th.querySelector('[data-part="sort-icon"], [data-part="sort-indicator"]');
      if (icon) icon.textContent = nextSort === 'ascending' ? '▲' : '▼';
      this.setAttribute('sort-key', key);
      this.setAttribute('sort-dir', nextSort === 'ascending' ? 'asc' : 'desc');
      this._sortColumn(colIndex, nextSort === 'ascending' ? 'asc' : 'desc');
    } else {
      this.removeAttribute('sort-key');
      this.removeAttribute('sort-dir');
      // Reset to original DOM order
      this._filteredRows.sort((a, b) => {
        return parseInt(a.getAttribute('data-row-id'), 10) - parseInt(b.getAttribute('data-row-id'), 10);
      });
    }

    this._renderPage();
    this.dispatchEvent(new CustomEvent('sort', {
      bubbles: true,
      detail: { key, direction: nextSort }
    }));
  }

  _sortColumn(colIndex, direction) {
    const mult = direction === 'asc' ? 1 : -1;

    this._filteredRows.sort((trA, trB) => {
      const cellA = trA.children[colIndex]?.textContent?.trim() || '';
      const cellB = trB.children[colIndex]?.textContent?.trim() || '';

      // Try numeric parse (strip currency symbols and commas)
      const numA = parseFloat(cellA.replace(/[^0-9.-]+/g, ''));
      const numB = parseFloat(cellB.replace(/[^0-9.-]+/g, ''));

      if (!isNaN(numA) && !isNaN(numB) && cellA.match(/[0-9]/) && cellB.match(/[0-9]/)) {
        return (numA - numB) * mult;
      }

      // Try Date parse
      const dateA = Date.parse(cellA);
      const dateB = Date.parse(cellB);
      if (!isNaN(dateA) && !isNaN(dateB) && cellA.length > 5 && cellB.length > 5) {
        return (dateA - dateB) * mult;
      }

      // String locale compare
      return cellA.localeCompare(cellB, undefined, { numeric: true, sensitivity: 'base' }) * mult;
    });

    // Reorder DOM nodes in tbody efficiently
    const fragment = document.createDocumentFragment();
    this._filteredRows.forEach((row) => fragment.appendChild(row));
    this._tbody.appendChild(fragment);
  }

  _setupSearch() {
    if (!this._searchInput) return;

    this._searchInput.addEventListener('input', () => {
      const query = this._searchInput.value.trim().toLowerCase();
      this.setAttribute('search', query);
      this.currentPage = 1;
      this._applyFilterAndSort();
      this._renderPage();

      this.dispatchEvent(new CustomEvent('filter', {
        bubbles: true,
        detail: { query, matchCount: this._filteredRows.length }
      }));
    });
  }

  _applyFilterAndSort() {
    const query = (this.getAttribute('search') || '').toLowerCase();

    if (!query) {
      this._filteredRows = [...this._allRows];
    } else {
      this._filteredRows = this._allRows.filter((tr) => tr._searchCache.includes(query));
    }
  }

  _setupPagination() {
    if (this._prevBtn) {
      this._prevBtn.addEventListener('click', () => {
        if (this.currentPage > 1) {
          this.currentPage = this.currentPage - 1;
          this._renderPage();
        }
      });
    }

    if (this._nextBtn) {
      this._nextBtn.addEventListener('click', () => {
        if (this.currentPage < this.totalPages) {
          this.currentPage = this.currentPage + 1;
          this._renderPage();
        }
      });
    }
  }

  _renderPage() {
    const page = this.currentPage;
    const size = this.pageSize;
    const total = this._filteredRows.length;
    const totalP = this.totalPages;

    const startIdx = (page - 1) * size;
    const endIdx = startIdx + size;

    // Hide all rows not matching filter
    this._allRows.forEach((tr) => {
      tr.setAttribute('hidden', '');
    });

    // Show active slice of filtered rows
    const visibleSlice = this._filteredRows.slice(startIdx, endIdx);
    visibleSlice.forEach((tr) => {
      tr.removeAttribute('hidden');
    });

    // Update pagination controls
    if (this._prevBtn) {
      this._prevBtn.disabled = page <= 1;
    }
    if (this._nextBtn) {
      this._nextBtn.disabled = page >= totalP;
    }

    if (this._pageInfo) {
      const startDisplay = total === 0 ? 0 : startIdx + 1;
      const endDisplay = Math.min(endIdx, total);
      this._pageInfo.textContent = `Showing ${startDisplay} to ${endDisplay} of ${total} row(s)`;
    }

    this._updateSelectAllState();

    this.dispatchEvent(new CustomEvent('page-change', {
      bubbles: true,
      detail: { page, totalPages: totalP, totalRows: total }
    }));
  }

  _setupSelection() {
    // Select all checkbox
    if (this._selectAllCheckbox) {
      this._selectAllCheckbox.addEventListener('change', () => {
        const isChecked = this._selectAllCheckbox.checked;
        const startIdx = (this.currentPage - 1) * this.pageSize;
        const visibleSlice = this._filteredRows.slice(startIdx, startIdx + this.pageSize);

        visibleSlice.forEach((row) => {
          const rowId = row.getAttribute('data-row-id');
          const cb = row.querySelector('input[data-part="row-select"], input[type="checkbox"]');
          if (cb) cb.checked = isChecked;

          if (isChecked) {
            row.setAttribute('data-selected', 'true');
            this._selectedIds.add(rowId);
          } else {
            row.removeAttribute('data-selected');
            this._selectedIds.delete(rowId);
          }
        });

        this._updateSelectionDisplay();
      });
    }

    // Individual row checkboxes delegation
    this._tbody.addEventListener('change', (e) => {
      const cb = e.target.closest('input[data-part="row-select"], input[type="checkbox"]');
      if (!cb) return;

      const row = cb.closest('tr');
      if (!row) return;

      const rowId = row.getAttribute('data-row-id');
      if (cb.checked) {
        row.setAttribute('data-selected', 'true');
        this._selectedIds.add(rowId);
      } else {
        row.removeAttribute('data-selected');
        this._selectedIds.delete(rowId);
      }

      this._updateSelectAllState();
      this._updateSelectionDisplay();
    });
  }

  _updateSelectAllState() {
    if (!this._selectAllCheckbox) return;

    const startIdx = (this.currentPage - 1) * this.pageSize;
    const visibleSlice = this._filteredRows.slice(startIdx, startIdx + this.pageSize);

    if (visibleSlice.length === 0) {
      this._selectAllCheckbox.checked = false;
      this._selectAllCheckbox.indeterminate = false;
      return;
    }

    const selectedVisibleCount = visibleSlice.filter((r) =>
      this._selectedIds.has(r.getAttribute('data-row-id'))
    ).length;

    if (selectedVisibleCount === visibleSlice.length) {
      this._selectAllCheckbox.checked = true;
      this._selectAllCheckbox.indeterminate = false;
    } else if (selectedVisibleCount > 0) {
      this._selectAllCheckbox.checked = false;
      this._selectAllCheckbox.indeterminate = true;
    } else {
      this._selectAllCheckbox.checked = false;
      this._selectAllCheckbox.indeterminate = false;
    }
  }

  _updateSelectionDisplay() {
    const count = this._selectedIds.size;
    const total = this._allRows.length;

    if (this._selectionCount) {
      this._selectionCount.textContent = `${count} of ${total} row(s) selected`;
    }

    if (this._bulkActions) {
      if (count > 0) {
        this._bulkActions.removeAttribute('hidden');
        this._bulkActions.setAttribute('data-visible', 'true');
      } else {
        this._bulkActions.setAttribute('hidden', '');
        this._bulkActions.removeAttribute('data-visible');
      }
    }

    if (this._bulkCount) {
      this._bulkCount.textContent = String(count);
    }

    this.dispatchEvent(new CustomEvent('selection-change', {
      bubbles: true,
      detail: {
        selectedIds: Array.from(this._selectedIds),
        selectedCount: count
      }
    }));
  }

  /**
   * Export table contents (selected rows or all matching filtered rows) to CSV
   * @param {string} filename 
   */
  exportCsv(filename = 'export-table.csv') {
    if (!this._allRows || this._allRows.length === 0) return;

    // Determine data rows: either selected rows, or all filtered rows
    const rowsToExport = this._selectedIds.size > 0
      ? this._allRows.filter((r) => this._selectedIds.has(r.getAttribute('data-row-id')))
      : this._filteredRows;

    if (rowsToExport.length === 0) return;

    // Extract headers (exclude checkbox column if any)
    const ths = this._thead ? Array.from(this._thead.querySelectorAll('th')) : [];
    const colIndices = [];
    const headerLabels = [];

    ths.forEach((th, idx) => {
      // Skip checkbox column
      if (th.querySelector('input[type="checkbox"]')) return;
      colIndices.push(idx);
      headerLabels.push(`"${(th.textContent || '').trim().replace(/"/g, '""')}"`);
    });

    const rowsCsv = rowsToExport.map((tr) => {
      return colIndices.map((idx) => {
        const cell = tr.children[idx];
        const text = cell ? cell.textContent.trim() : '';
        return `"${text.replace(/"/g, '""')}"`;
      }).join(',');
    });

    const csvContent = [headerLabels.join(','), ...rowsCsv].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  // Public Methods
  nextPage() {
    if (this.currentPage < this.totalPages) {
      this.currentPage = this.currentPage + 1;
      this._renderPage();
    }
  }

  prevPage() {
    if (this.currentPage > 1) {
      this.currentPage = this.currentPage - 1;
      this._renderPage();
    }
  }

  setPage(n) {
    if (n >= 1 && n <= this.totalPages) {
      this.currentPage = n;
      this._renderPage();
    }
  }

  setSearch(q) {
    if (this._searchInput) this._searchInput.value = q;
    this.setAttribute('search', q);
    this.currentPage = 1;
    this._applyFilterAndSort();
    this._renderPage();
  }

  getSelectedRowIds() {
    return Array.from(this._selectedIds);
  }

  selectAll() {
    this._allRows.forEach((r) => {
      const id = r.getAttribute('data-row-id');
      const cb = r.querySelector('input[type="checkbox"]');
      if (cb) cb.checked = true;
      r.setAttribute('data-selected', 'true');
      this._selectedIds.add(id);
    });
    this._updateSelectAllState();
    this._updateSelectionDisplay();
  }

  deselectAll() {
    this._allRows.forEach((r) => {
      const cb = r.querySelector('input[type="checkbox"]');
      if (cb) cb.checked = false;
      r.removeAttribute('data-selected');
    });
    this._selectedIds.clear();
    this._updateSelectAllState();
    this._updateSelectionDisplay();
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

const DAY_NAMES = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];

function formatDate(year, month, day) {
  const m = String(month).padStart(2, '0');
  const d = String(day).padStart(2, '0');
  return `${year}-${m}-${d}`;
}

function parseDate(str) {
  if (!str) return null;
  const parts = str.split('-');
  if (parts.length !== 3) return null;
  const y = parseInt(parts[0], 10);
  const m = parseInt(parts[1], 10);
  const d = parseInt(parts[2], 10);
  if (isNaN(y) || isNaN(m) || isNaN(d)) return null;
  return { year: y, month: m, day: d };
}

/**
 * <ui-calendar> Micro-Enhancer
 * WAI-ARIA APG Calendar Date Picker Grid Pattern.
 * Invariant: Mutates attributes, never nodes. Form-associated via ElementInternals.
 */
export class UiCalendar extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['value', 'name', 'month', 'year', 'min', 'max', 'disabled'];
  }

  constructor() {
    super();
    if (typeof this.attachInternals === 'function') {
      try {
        this._internals = this.attachInternals();
      } catch (e) {
        // Fallback for older environments
      }
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    if (val) this.setAttributeSafe(this, 'name', val);
    else this.removeAttributeSafe(this, 'name');
  }

  get value() {
    return this.getAttribute('value') || '';
  }

  set value(val) {
    this.setAttribute('value', val);
  }

  get month() {
    const m = parseInt(this.getAttribute('month'), 10);
    return isNaN(m) || m < 1 || m > 12 ? (this._currentViewDate.getMonth() + 1) : m;
  }

  set month(val) {
    this.setAttribute('month', String(val));
  }

  get year() {
    const y = parseInt(this.getAttribute('year'), 10);
    return isNaN(y) ? this._currentViewDate.getFullYear() : y;
  }

  set year(val) {
    this.setAttribute('year', String(val));
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'calendar');

    const parsedVal = parseDate(this.value);
    const today = new Date();
    this._currentViewDate = parsedVal
      ? new Date(parsedVal.year, parsedVal.month - 1, parsedVal.day)
      : today;

    this._focusedDate = parsedVal
      ? new Date(parsedVal.year, parsedVal.month - 1, parsedVal.day)
      : new Date(today.getFullYear(), today.getMonth(), today.getDate());

    if (!this.querySelector('[data-part="calendar-header"]')) {
      this._buildSkeleton();
    }

    this._cacheElements();
    this._attachEvents();
    this._render();
    this._updateFormValue();
  }

  _buildSkeleton() {
    this.innerHTML = `
      <div data-part="calendar-header">
        <button type="button" data-part="prev-month" aria-label="Previous Month" class="ui-button ui-button--ghost ui-button--icon">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <div data-part="month-heading" aria-live="polite"></div>
        <button type="button" data-part="next-month" aria-label="Next Month" class="ui-button ui-button--ghost ui-button--icon">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>
        </button>
      </div>
      <table data-part="calendar-grid" role="grid" aria-label="Calendar">
        <thead>
          <tr role="row">
            ${DAY_NAMES.map((d) => `<th role="columnheader" aria-label="${d}">${d}</th>`).join('')}
          </tr>
        </thead>
        <tbody data-part="calendar-body"></tbody>
      </table>
      <div data-part="calendar-footer" class="ui-calendar-footer">
        <button type="button" data-part="today-btn" class="ui-calendar-action-btn">Today</button>
        <button type="button" data-part="clear-btn" class="ui-calendar-action-btn">Clear</button>
      </div>
    `;
  }

  _cacheElements() {
    this._prevBtn = this.querySelector('[data-part="prev-month"]');
    this._nextBtn = this.querySelector('[data-part="next-month"]');
    this._heading = this.querySelector('[data-part="month-heading"]');
    this._grid = this.querySelector('[data-part="calendar-grid"]');
    this._tbody = this.querySelector('[data-part="calendar-body"]');
    this._todayBtn = this.querySelector('[data-part="today-btn"]');
    this._clearBtn = this.querySelector('[data-part="clear-btn"]');
  }

  _attachEvents() {
    if (this._prevBtn) {
      this._prevBtn.addEventListener('click', (e) => {
        e.preventDefault();
        this.prevMonth();
      });
    }

    if (this._nextBtn) {
      this._nextBtn.addEventListener('click', (e) => {
        e.preventDefault();
        this.nextMonth();
      });
    }

    if (this._todayBtn) {
      this._todayBtn.addEventListener('click', (e) => {
        e.preventDefault();
        const now = new Date();
        const todayStr = formatDate(now.getFullYear(), now.getMonth() + 1, now.getDate());
        this.selectDate(todayStr);
      });
    }

    if (this._clearBtn) {
      this._clearBtn.addEventListener('click', (e) => {
        e.preventDefault();
        this.clear();
      });
    }

    if (this._tbody) {
      this._tbody.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-part="day-btn"]');
        if (!btn || btn.hasAttribute('disabled')) return;
        const dateStr = btn.getAttribute('data-date');
        if (dateStr) {
          this.selectDate(dateStr);
        }
      });
    }

    this.addEventListener('keydown', (e) => this._handleKeydown(e));
  }

  _handleKeydown(e) {
    if (this.hasAttribute('disabled')) return;

    let handled = false;
    const cur = new Date(this._focusedDate);

    switch (e.key) {
      case 'ArrowLeft':
        cur.setDate(cur.getDate() - 1);
        handled = true;
        break;
      case 'ArrowRight':
        cur.setDate(cur.getDate() + 1);
        handled = true;
        break;
      case 'ArrowUp':
        cur.setDate(cur.getDate() - 7);
        handled = true;
        break;
      case 'ArrowDown':
        cur.setDate(cur.getDate() + 7);
        handled = true;
        break;
      case 'PageUp':
        if (e.shiftKey) {
          cur.setFullYear(cur.getFullYear() - 1);
        } else {
          cur.setMonth(cur.getMonth() - 1);
        }
        handled = true;
        break;
      case 'PageDown':
        if (e.shiftKey) {
          cur.setFullYear(cur.getFullYear() + 1);
        } else {
          cur.setMonth(cur.getMonth() + 1);
        }
        handled = true;
        break;
      case 'Home':
        cur.setDate(cur.getDate() - cur.getDay());
        handled = true;
        break;
      case 'End':
        cur.setDate(cur.getDate() + (6 - cur.getDay()));
        handled = true;
        break;
      case 'Enter':
      case ' ': {
        const targetBtn = this.querySelector(`[data-date="${formatDate(cur.getFullYear(), cur.getMonth() + 1, cur.getDate())}"]`);
        if (targetBtn && !targetBtn.hasAttribute('disabled')) {
          e.preventDefault();
          this.selectDate(targetBtn.getAttribute('data-date'));
        }
        return;
      }
    }

    if (handled) {
      e.preventDefault();
      this._focusedDate = cur;

      // Update month view if focus moved outside current month
      const focusMonth = cur.getMonth() + 1;
      const focusYear = cur.getFullYear();
      if (focusMonth !== this.month || focusYear !== this.year) {
        this.month = focusMonth;
        this.year = focusYear;
        this._render();
      }

      const newFocusBtn = this.querySelector(`[data-date="${formatDate(cur.getFullYear(), cur.getMonth() + 1, cur.getDate())}"]`);
      if (newFocusBtn) {
        newFocusBtn.focus();
      }
    }
  }

  _render() {
    const y = this.year;
    const m = this.month; // 1-indexed

    if (this._heading) {
      this._heading.textContent = `${MONTH_NAMES[m - 1]} ${y}`;
    }

    if (!this._tbody) return;

    const firstDayIndex = new Date(y, m - 1, 1).getDay();
    const daysInMonth = new Date(y, m, 0).getDate();
    const daysInPrevMonth = new Date(y, m - 1, 0).getDate();

    const todayStr = formatDate(new Date().getFullYear(), new Date().getMonth() + 1, new Date().getDate());
    const valStr = this.value;
    const minStr = this.getAttribute('min') || '';
    const maxStr = this.getAttribute('max') || '';

    let html = '';
    let dayCounter = 1;
    let nextMonthDayCounter = 1;

    for (let row = 0; row < 6; row++) {
      html += '<tr role="row">';
      for (let col = 0; col < 7; col++) {
        let dayNum;
        let cellDateStr;
        let isOutside = false;

        if (row === 0 && col < firstDayIndex) {
          // Prev month overflow
          dayNum = daysInPrevMonth - firstDayIndex + col + 1;
          const prevM = m === 1 ? 12 : m - 1;
          const prevY = m === 1 ? y - 1 : y;
          cellDateStr = formatDate(prevY, prevM, dayNum);
          isOutside = true;
        } else if (dayCounter > daysInMonth) {
          // Next month overflow
          dayNum = nextMonthDayCounter++;
          const nextM = m === 12 ? 1 : m + 1;
          const nextY = m === 12 ? y + 1 : y;
          cellDateStr = formatDate(nextY, nextM, dayNum);
          isOutside = true;
        } else {
          dayNum = dayCounter++;
          cellDateStr = formatDate(y, m, dayNum);
        }

        const isToday = cellDateStr === todayStr;
        const isSelected = cellDateStr === valStr;
        const isFocused = this._focusedDate && cellDateStr === formatDate(this._focusedDate.getFullYear(), this._focusedDate.getMonth() + 1, this._focusedDate.getDate());

        let isDisabled = this.hasAttribute('disabled');
        if (minStr && cellDateStr < minStr) isDisabled = true;
        if (maxStr && cellDateStr > maxStr) isDisabled = true;

        html += `
          <td role="gridcell" 
              aria-selected="${isSelected ? 'true' : 'false'}"
              ${isDisabled ? 'aria-disabled="true"' : ''}>
            <button type="button"
                    data-part="day-btn"
                    data-date="${cellDateStr}"
                    tabindex="${isFocused ? '0' : '-1'}"
                    ${isOutside ? 'data-outside="true"' : ''}
                    ${isToday ? 'data-today="true"' : ''}
                    ${isSelected ? 'data-selected="true"' : ''}
                    ${isDisabled ? 'disabled' : ''}>
              ${dayNum}
            </button>
          </td>
        `;
      }
      html += '</tr>';

      // If we've finished the month and row is done, break early if all 6 rows not required
      if (dayCounter > daysInMonth && row >= 4) {
        break;
      }
    }

    this._tbody.innerHTML = html;
  }

  selectDate(dateStr) {
    this.value = dateStr;
    const parsed = parseDate(dateStr);
    if (parsed) {
      this._focusedDate = new Date(parsed.year, parsed.month - 1, parsed.day);
      if (parsed.month !== this.month || parsed.year !== this.year) {
        this.month = parsed.month;
        this.year = parsed.year;
      }
    }
    this._render();
    this._updateFormValue();

    this.dispatchEvent(new CustomEvent('change', {
      bubbles: true,
      detail: {
        value: dateStr,
        date: parsed ? new Date(parsed.year, parsed.month - 1, parsed.day) : null
      }
    }));
  }

  clear() {
    this.value = '';
    this._render();
    this._updateFormValue();
    this.dispatchEvent(new CustomEvent('change', {
      bubbles: true,
      detail: {
        value: '',
        date: null
      }
    }));
  }

  prevMonth() {
    let m = this.month - 1;
    let y = this.year;
    if (m < 1) {
      m = 12;
      y -= 1;
    }
    this.month = m;
    this.year = y;
    this._render();
    this.dispatchEvent(new CustomEvent('month-change', {
      bubbles: true,
      detail: { year: y, month: m }
    }));
  }

  nextMonth() {
    let m = this.month + 1;
    let y = this.year;
    if (m > 12) {
      m = 1;
      y += 1;
    }
    this.month = m;
    this.year = y;
    this._render();
    this.dispatchEvent(new CustomEvent('month-change', {
      bubbles: true,
      detail: { year: y, month: m }
    }));
  }

  _updateFormValue() {
    if (this._internals && this._internals.setFormValue) {
      this._internals.setFormValue(this.value || null);
    }
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (oldVal === newVal) return;
    if (name === 'value') {
      const parsed = parseDate(newVal);
      if (parsed) {
        this._currentViewDate = new Date(parsed.year, parsed.month - 1, parsed.day);
        this._focusedDate = new Date(parsed.year, parsed.month - 1, parsed.day);
        if (parsed.month !== this.month || parsed.year !== this.year) {
          this.month = parsed.month;
          this.year = parsed.year;
        }
      }
      this._render();
      this._updateFormValue();
    } else if (name === 'month' || name === 'year' || name === 'disabled' || name === 'min' || name === 'max') {
      this._render();
    }
  }

  formResetCallback() {
    this.value = this.getAttribute('value') || '';
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { applyPositionFallback } from '../../utils/anchor-fallback.js';
import '../calendar/ui-calendar.js';

/**
 * <ui-date-picker> Micro-Enhancer
 * Composed Light-DOM date picker primitive combining popover and <ui-calendar>.
 * Form-associated via ElementInternals.
 */
export class UiDatePicker extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['value', 'placeholder', 'disabled', 'open', 'min', 'max'];
  }

  constructor() {
    super();
    if (typeof this.attachInternals === 'function') {
      try {
        this._internals = this.attachInternals();
      } catch (e) {
        // Fallback for older environments
      }
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    if (val) this.setAttributeSafe(this, 'name', val);
    else this.removeAttributeSafe(this, 'name');
  }

  get value() {
    return this.getAttribute('value') || '';
  }

  set value(val) {
    this.setAttribute('value', val);
  }

  get isOpen() {
    return this.hasAttribute('open') || this._popover?.matches(':popover-open') || this._popover?.hasAttribute('open');
  }

  set isOpen(val) {
    if (val) this.open();
    else this.close();
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'date-picker');

    if (!this.querySelector('[data-part="trigger"]')) {
      this._buildSkeleton();
    }

    this._trigger = this.querySelector('[data-part="trigger"]');
    this._displayValue = this.querySelector('[data-part="display-value"]');
    this._clearBtn = this.querySelector('[data-part="clear-btn"]');
    this._popover = this.querySelector('[data-part="popover"]');
    this._calendar = this.querySelector('ui-calendar, [data-ui="calendar"]');

    if (this._popover) {
      this.setAttributeSafe(this._popover, 'popover', 'auto');
    }

    this._updateDisplay();
    this._syncConstraints();
    this._attachEvents();
    this._updateFormValue();
  }

  _buildSkeleton() {
    const placeholder = this.getAttribute('placeholder') || 'Pick a date...';
    this.innerHTML = `
      <button type="button" data-part="trigger" data-ui="button" data-variant="outline" class="ui-button ui-button--outline ui-date-picker-trigger" aria-haspopup="dialog" aria-expanded="false">
        <svg data-part="icon" class="ui-date-picker-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <rect width="18" height="18" x="3" y="4" rx="2" ry="2"/>
          <line x1="16" x2="16" y1="2" y2="6"/>
          <line x1="8" x2="8" y1="2" y2="6"/>
          <line x1="3" x2="21" y1="10" y2="10"/>
        </svg>
        <span data-part="display-value">${placeholder}</span>
        <span data-part="clear-btn" class="ui-date-picker-clear-action" role="button" tabindex="-1" aria-label="Clear date" style="display: none;">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12"/></svg>
        </span>
        <svg data-part="chevron" class="ui-date-picker-chevron" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="m6 9 6 6 6-6"/>
        </svg>
      </button>
      <div data-part="popover" popover="auto" class="ui-date-picker-popover">
        <ui-calendar></ui-calendar>
      </div>
    `;
  }

  _syncConstraints() {
    if (!this._calendar) return;
    if (this.hasAttribute('min')) {
      this._calendar.setAttribute('min', this.getAttribute('min'));
    } else {
      this._calendar.removeAttribute('min');
    }
    if (this.hasAttribute('max')) {
      this._calendar.setAttribute('max', this.getAttribute('max'));
    } else {
      this._calendar.removeAttribute('max');
    }
  }

  _reposition = () => {
    if (!this.isOpen || !this._popover) return;
    const trigger = (this._trigger && this._trigger.isConnected) ? this._trigger : this.querySelector('[data-part="trigger"]');
    if (!trigger) return;
    applyPositionFallback(trigger, this._popover, { placement: 'bottom-start', offset: 6 });
  };

  _attachEvents() {
    if (this._trigger) {
      this._trigger.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.toggle();
      });
    }

    if (this._clearBtn) {
      this._clearBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.clear();
      });
    }

    if (this._calendar) {
      if (this.value) {
        this._calendar.setAttribute('value', this.value);
      }

      this._calendar.addEventListener('change', (e) => {
        const selected = e.detail.value;
        this.value = selected;
        this._updateDisplay();
        this._updateFormValue();
        this.close();

        this.dispatchEvent(new CustomEvent('change', {
          bubbles: true,
          detail: { value: selected, date: e.detail.date }
        }));
      });
    }

    // Dismiss on click outside
    document.addEventListener('click', (e) => {
      if (this.isOpen && !this.contains(e.target)) {
        this.close();
      }
    });

    this.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.isOpen) {
        e.preventDefault();
        this.close();
        this._trigger?.focus();
      }
    });
  }

  _updateDisplay() {
    if (!this._displayValue) return;
    const placeholder = this.getAttribute('placeholder') || 'Pick a date...';

    if (this.value) {
      const parts = this.value.split('-');
      if (parts.length === 3) {
        const d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
        if (!isNaN(d.getTime())) {
          this._displayValue.textContent = d.toLocaleDateString(undefined, {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
          });
          if (this._clearBtn) this._clearBtn.style.display = 'inline-flex';
          this.setAttributeSafe(this, 'data-has-value', 'true');
          return;
        }
      }
      this._displayValue.textContent = this.value;
      if (this._clearBtn) this._clearBtn.style.display = 'inline-flex';
      this.setAttributeSafe(this, 'data-has-value', 'true');
    } else {
      this._displayValue.textContent = placeholder;
      if (this._clearBtn) this._clearBtn.style.display = 'none';
      this.removeAttribute('data-has-value');
    }
  }

  clear() {
    this.value = '';
    if (this._calendar) {
      this._calendar.clear?.();
    }
    this._updateDisplay();
    this._updateFormValue();
    this.dispatchEvent(new CustomEvent('change', {
      bubbles: true,
      detail: { value: '', date: null }
    }));
  }

  open() {
    if (this.hasAttribute('disabled') || this._isToggling) return;
    this._isToggling = true;
    try {
      if (!this.hasAttribute('open')) {
        this.setAttributeSafe(this, 'open', '');
      }
      this._trigger?.setAttribute('aria-expanded', 'true');

      this._syncConstraints();

      if (this._calendar) {
        if (this.value) {
          this._calendar.setAttribute('value', this.value);
          const parts = this.value.split('-');
          if (parts.length === 3) {
            this._calendar.month = parseInt(parts[1], 10);
            this._calendar.year = parseInt(parts[0], 10);
          }
        }
        this._calendar._render?.();
      }

      if (this._popover) {
        if (typeof this._popover.showPopover === 'function') {
          try {
            if (!this._popover.matches(':popover-open')) {
              this._popover.showPopover();
            }
          } catch (e) {
            this._popover.setAttribute('open', '');
          }
        } else {
          this._popover.setAttribute('open', '');
        }

        this._reposition();
        if (typeof requestAnimationFrame === 'function') {
          requestAnimationFrame(this._reposition);
        }
        setTimeout(this._reposition, 10);
      }

      if (typeof window !== 'undefined') {
        window.addEventListener('scroll', this._reposition, { passive: true, capture: true });
        window.addEventListener('resize', this._reposition, { passive: true });
      }

      this.dispatchEvent(new CustomEvent('open', { bubbles: true }));
    } finally {
      this._isToggling = false;
    }
  }

  close() {
    if (this._isToggling) return;
    this._isToggling = true;
    try {
      if (this.hasAttribute('open')) {
        this.removeAttribute('open');
      }
      this._trigger?.setAttribute('aria-expanded', 'false');

      if (typeof window !== 'undefined') {
        window.removeEventListener('scroll', this._reposition, { capture: true });
        window.removeEventListener('resize', this._reposition);
      }

      if (this._popover) {
        if (typeof this._popover.hidePopover === 'function') {
          try {
            if (this._popover.matches(':popover-open')) {
              this._popover.hidePopover();
            }
          } catch (e) {
            this._popover.removeAttribute('open');
          }
        } else {
          this._popover.removeAttribute('open');
        }
      }

      this.dispatchEvent(new CustomEvent('close', { bubbles: true }));
    } finally {
      this._isToggling = false;
    }
  }

  toggle() {
    if (this.isOpen) {
      this.close();
    } else {
      this.open();
    }
  }

  disconnectedCallback() {
    if (typeof window !== 'undefined') {
      window.removeEventListener('scroll', this._reposition, { capture: true });
      window.removeEventListener('resize', this._reposition);
    }
  }

  _updateFormValue() {
    if (this._internals && this._internals.setFormValue) {
      this._internals.setFormValue(this.value || null);
    }
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (oldVal === newVal) return;
    if (name === 'value') {
      this._updateDisplay();
      if (this._calendar) {
        this._calendar.setAttribute('value', newVal || '');
      }
      this._updateFormValue();
    } else if (name === 'open') {
      if (this.hasAttribute('open')) {
        this.open();
      } else {
        this.close();
      }
    } else if (name === 'min' || name === 'max') {
      this._syncConstraints();
      this._calendar?._render?.();
    } else if (name === 'disabled') {
      if (this._trigger) {
        if (this.hasAttribute('disabled')) {
          this._trigger.setAttribute('disabled', '');
        } else {
          this._trigger.removeAttribute('disabled');
        }
      }
    }
  }

  formResetCallback() {
    this.value = this.getAttribute('value') || '';
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { attachPersistence } from '../../utils/persistence.js';

/**
 * <ui-data-grid> Micro-Enhancer
 * High-performance Virtualized Data Grid capable of streaming >10,000 to 100,000 rows at 60 FPS.
 * 
 * Invariants:
 * 1. 100% Light-DOM: Full accessibility and form tree integration.
 * 2. Window Virtualization: Only renders ~25-35 DOM rows at any moment regardless of total dataset size.
 * 3. Passive RAF Scrolling: Zero main-thread lag during fast scrolling.
 * 4. Streaming Ready: appendRows() and live stream support for real-time telemetry/financial data.
 * 5. Declarative Persistence: persist="url|session|local" [sync="cross-tab"]
 */
export class UiDataGrid extends BaseLightElement {
  static get observedAttributes() {
    return ['row-height', 'overscan', 'sort-key', 'sort-dir', 'search', 'streaming', 'persist', 'sync'];
  }

  constructor() {
    super();
    this._rows = [];
    this._filteredRows = [];
    this._columns = [];
    this._selectedIds = new Set();
    this._lastSelectedIndex = -1;
    this._sortKey = null;
    this._sortDir = null; // 'asc' | 'desc'
    this._searchQuery = '';
    this._streamTimer = null;
    this._rafId = null;
    this._isInternalSync = false;
  }

  get rowHeight() {
    const val = parseInt(this.getAttribute('row-height'), 10);
    return isNaN(val) || val <= 0 ? 40 : val;
  }

  set rowHeight(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('row-height', String(val));
    else this.removeAttributeSafe('row-height');
  }

  get overscan() {
    const val = parseInt(this.getAttribute('overscan'), 10);
    return isNaN(val) || val < 0 ? 6 : val;
  }

  set overscan(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('overscan', String(val));
    else this.removeAttributeSafe('overscan');
  }

  get totalRows() {
    return this._rows.length;
  }

  set totalRows(_) {}

  get filteredCount() {
    return this._filteredRows.length;
  }

  set filteredCount(_) {}

  get selectedCount() {
    return this._selectedIds.size;
  }

  set selectedCount(_) {}

  getAiState() {
    return {
      totalRows: this.totalRows,
      filteredCount: this.filteredCount,
      selectedCount: this.selectedCount,
      sortKey: this._sortKey,
      sortDir: this._sortDir,
      searchQuery: this._searchQuery,
      rowHeight: this.rowHeight,
      overscan: this.overscan
    };
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (oldVal === newVal || !this._initialized || this._isInternalSync) return;
    if (name === 'sort-key' || name === 'sort-dir') {
      const key = this.getAttribute('sort-key');
      const dir = this.getAttribute('sort-dir') || 'asc';
      if (key !== this._sortKey || dir !== this._sortDir) {
        this.sortBy(key, dir);
      }
    } else if (name === 'search') {
      if (newVal !== this._searchQuery) {
        this.setSearch(newVal || '');
      }
    }
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'data-grid');
    this.setAttributeSafe(this, 'role', 'region');
    this.setAttributeSafe(this, 'aria-label', this.getAttribute('aria-label') || 'Data Grid');

    // Read initial attributes if provided
    if (!this._sortKey && this.hasAttribute('sort-key')) {
      this._sortKey = this.getAttribute('sort-key');
      this._sortDir = this.getAttribute('sort-dir') || 'asc';
    }
    if (!this._searchQuery && this.hasAttribute('search')) {
      this._searchQuery = (this.getAttribute('search') || '').toLowerCase().trim();
    }

    // Locate or create internal DOM parts
    this._setupElements();
    this._bindEvents();

    // Setup Declarative Persistence & Cross-Tab Sync
    if (this.hasAttribute('persist') || this.hasAttribute('sync')) {
      const cleanupPersistence = attachPersistence(this, {
        keys: ['search', 'sortKey', 'sortDir', 'selected'],
        getState: () => ({
          search: this._searchQuery,
          sortKey: this._sortKey,
          sortDir: this._sortDir,
          selected: Array.from(this._selectedIds)
        }),
        setState: (state) => {
          if (state.search !== undefined && state.search !== this._searchQuery) {
            this._searchQuery = (state.search || '').toLowerCase().trim();
            this._isInternalSync = true;
            try {
              this.setAttributeSafe(this, 'search', this._searchQuery);
            } finally {
              this._isInternalSync = false;
            }
            const searchInput = this.querySelector('[data-part="search-input"]') || document.getElementById('grid-search-input');
            if (searchInput && searchInput.value !== state.search) searchInput.value = state.search;
            if (this._rows.length > 0) {
              this._applyFilterAndSort();
              this._updateVirtualWindow();
              this._updateFooter();
            }
          }
          if (state.sortKey !== undefined && state.sortKey !== null) {
            this._sortKey = state.sortKey;
            this._sortDir = state.sortDir || 'asc';
            this._isInternalSync = true;
            try {
              this.setAttributeSafe(this, 'sort-key', this._sortKey);
              this.setAttributeSafe(this, 'sort-dir', this._sortDir);
            } finally {
              this._isInternalSync = false;
            }

            if (this._thead) {
              this._thead.querySelectorAll('th[data-sortable="true"]').forEach(h => {
                const isMatch = h.getAttribute('data-col-key') === this._sortKey;
                h.setAttribute('aria-sort', isMatch ? (this._sortDir === 'asc' ? 'ascending' : 'descending') : 'none');
                const icon = h.querySelector('.grid-sort-icon');
                if (icon) icon.textContent = isMatch ? (this._sortDir === 'asc' ? '▲' : '▼') : '⇅';
              });
            }
            if (this._rows.length > 0) {
              this._applyFilterAndSort();
              this._updateVirtualWindow();
            }
          } else if (state.sortKey === null) {
            this._sortKey = null;
            this._sortDir = null;
            this._isInternalSync = true;
            try {
              this.removeAttributeSafe(this, 'sort-key');
              this.removeAttributeSafe(this, 'sort-dir');
            } finally {
              this._isInternalSync = false;
            }
            if (this._thead) {
              this._thead.querySelectorAll('th[data-sortable="true"]').forEach(h => {
                h.setAttribute('aria-sort', 'none');
                const icon = h.querySelector('.grid-sort-icon');
                if (icon) icon.textContent = '⇅';
              });
            }
            if (this._rows.length > 0) {
              this._applyFilterAndSort();
              this._updateVirtualWindow();
            }
          }
          if (Array.isArray(state.selected)) {
            this._selectedIds = new Set(state.selected);
            if (this._rows.length > 0) {
              this._updateVirtualWindow();
              this._updateSelectAllState();
              this._updateFooter();
            }
          }
        }
      });
      this._cleanups.push(cleanupPersistence);
    }

    // Check if initial declarative data is present in embedded JSON script
    const scriptData = this.querySelector('script[data-part="grid-data"]');
    if (scriptData) {
      try {
        const parsed = JSON.parse(scriptData.textContent);
        if (parsed.columns) this.setColumns(parsed.columns);
        if (parsed.rows) this.setRows(parsed.rows);
      } catch (e) {
        console.error('[ui-data-grid] Failed to parse embedded grid-data JSON', e);
      }
    } else {
      // Auto-extract from any initial HTML table if provided
      const table = this.querySelector('table:not([data-part="grid-table"])');
      if (table) {
        this._extractFromExistingTable(table);
      }
    }
  }

  _setupElements() {
    // Top Toolbar
    this._toolbar = this.querySelector('[data-part="toolbar"]');
    if (!this._toolbar) {
      this._toolbar = document.createElement('div');
      this._toolbar.setAttribute('data-part', 'toolbar');
      if (this.firstChild) {
        this.insertBefore(this._toolbar, this.firstChild);
      } else {
        this.appendChild(this._toolbar);
      }
    }
    this._toolbar.classList.add('grid-toolbar');

    // Viewport (the scroll container)
    this._viewport = this.querySelector('[data-part="viewport"]');
    if (!this._viewport) {
      this._viewport = document.createElement('div');
      this._viewport.setAttribute('data-part', 'viewport');
      this.appendChild(this._viewport);
    }
    this._viewport.classList.add('grid-viewport');
    this._viewport.style.overflowY = 'auto';

    // Runway (height spacer)
    this._runway = this._viewport.querySelector('[data-part="runway"]');
    if (!this._runway) {
      this._runway = document.createElement('div');
      this._runway.setAttribute('data-part', 'runway');
      this._viewport.appendChild(this._runway);
    }
    this._runway.classList.add('grid-runway');

    // Virtual Table
    this._table = this._runway.querySelector('[data-part="grid-table"]');
    if (!this._table) {
      this._table = document.createElement('table');
      this._table.setAttribute('data-part', 'grid-table');
      this._runway.appendChild(this._table);
    }
    this._table.setAttribute('role', 'grid');
    this._table.classList.add('grid-table', 'ui-table');

    // Thead (Sticky header)
    this._thead = this._table.querySelector('thead');
    if (!this._thead) {
      this._thead = document.createElement('thead');
      this._table.appendChild(this._thead);
    }

    // Virtual Tbody
    this._tbody = this._table.querySelector('tbody[data-part="virtual-tbody"]');
    if (!this._tbody) {
      this._tbody = document.createElement('tbody');
      this._tbody.setAttribute('data-part', 'virtual-tbody');
      this._table.appendChild(this._tbody);
    }
    this._tbody.classList.add('grid-tbody');

    // Status Footer
    this._footer = this.querySelector('[data-part="footer"]');
    if (!this._footer) {
      this._footer = document.createElement('div');
      this._footer.setAttribute('data-part', 'footer');
      this.appendChild(this._footer);
    }
    this._footer.classList.add('grid-footer');
  }

  _bindEvents() {
    // Passive scroll handler with requestAnimationFrame
    const onScroll = () => {
      if (this._rafId) return;
      this._rafId = requestAnimationFrame(() => {
        this._updateVirtualWindow();
        this._rafId = null;
      });
    };

    this._viewport.addEventListener('scroll', onScroll, { passive: true });
    this._cleanups.push(() => {
      this._viewport.removeEventListener('scroll', onScroll);
      if (this._rafId) cancelAnimationFrame(this._rafId);
    });

    // ResizeObserver for dynamic container resizes
    if (typeof ResizeObserver !== 'undefined') {
      const ro = new ResizeObserver(() => {
        this._updateVirtualWindow();
      });
      ro.observe(this._viewport);
      this._cleanups.push(() => ro.disconnect());
    }
  }

  /**
   * Set columns schema
   * @param {Array<{ key: string, label: string, sortable?: boolean, width?: string, align?: string }>} columns
   */
  setColumns(columns) {
    if (!this._initialized) {
      this.init();
      this._initialized = true;
    }
    this._columns = columns;
    this._renderHeader();
    if (this._sortKey && this._rows.length > 0) {
      this._applyFilterAndSort();
    }
    this._updateVirtualWindow();
  }

  /**
   * Set rows data
   * @param {Array<Object>} rows
   */
  setRows(rows) {
    if (!this._initialized) {
      this.init();
      this._initialized = true;
    }
    this._rows = rows.map((r, i) => ({
      ...r,
      _id: r.id != null ? String(r.id) : `row-${i}`,
      _searchStr: Object.values(r).join(' ').toLowerCase()
    }));
    this._applyFilterAndSort();
    this._updateRunwayHeight();
    this._updateVirtualWindow();
    this._updateFooter();
  }

  /**
   * Append rows (for streaming or live updates)
   * @param {Array<Object>} newRows
   * @param {Object} options { autoScroll?: boolean }
   */
  appendRows(newRows, options = {}) {
    if (!newRows || newRows.length === 0) return;

    const baseIndex = this._rows.length;
    const prepared = newRows.map((r, i) => ({
      ...r,
      _id: r.id != null ? String(r.id) : `row-${baseIndex + i}`,
      _searchStr: Object.values(r).join(' ').toLowerCase()
    }));

    this._rows.push(...prepared);

    // Update filtered set
    if (!this._searchQuery) {
      this._filteredRows.push(...prepared);
      if (this._sortKey) {
        this._sortFilteredRows();
      }
    } else {
      const q = this._searchQuery;
      const matches = prepared.filter(r => r._searchStr.includes(q));
      this._filteredRows.push(...matches);
      if (this._sortKey) {
        this._sortFilteredRows();
      }
    }

    this._updateRunwayHeight();

    if (options.autoScroll) {
      this._viewport.scrollTop = this._viewport.scrollHeight;
    }

    this._updateVirtualWindow();
    this._updateFooter();

    this.dispatchCustomEvent('stream-update', {
      addedCount: newRows.length,
      totalCount: this._rows.length
    });
  }

  /**
   * Set active search query filter
   * @param {string} query
   */
  setSearch(query) {
    this._searchQuery = (query || '').toLowerCase().trim();
    this._isInternalSync = true;
    try {
      this.setAttributeSafe(this, 'search', this._searchQuery);
    } finally {
      this._isInternalSync = false;
    }
    this._applyFilterAndSort();
    this._viewport.scrollTop = 0;
    this._updateRunwayHeight();
    this._updateVirtualWindow();
    this._updateFooter();
    this._persistState?.();
  }

  /**
   * Sort by a specific column key and direction ('asc' | 'desc' | null)
   * @param {string|null} key
   * @param {'asc'|'desc'|null} direction
   */
  sortBy(key, direction = 'asc') {
    this._isInternalSync = true;
    try {
      if (!key || !direction) {
        this._sortKey = null;
        this._sortDir = null;
        this.removeAttributeSafe(this, 'sort-key');
        this.removeAttributeSafe(this, 'sort-dir');
      } else {
        this._sortKey = key;
        this._sortDir = direction === 'desc' ? 'desc' : 'asc';
        this.setAttributeSafe(this, 'sort-key', this._sortKey);
        this.setAttributeSafe(this, 'sort-dir', this._sortDir);
      }
    } finally {
      this._isInternalSync = false;
    }

    if (this._thead) {
      this._thead.querySelectorAll('th[data-sortable="true"]').forEach(h => {
        const isMatch = this._sortKey && h.getAttribute('data-col-key') === this._sortKey;
        h.setAttribute('aria-sort', isMatch ? (this._sortDir === 'asc' ? 'ascending' : 'descending') : 'none');
        const icon = h.querySelector('.grid-sort-icon');
        if (icon) icon.textContent = isMatch ? (this._sortDir === 'asc' ? '▲' : '▼') : '⇅';
      });
    }

    this._applyFilterAndSort();
    this._updateVirtualWindow();
    this._persistState?.();
    this.dispatchCustomEvent('sort', { key: this._sortKey, direction: this._sortDir });
  }

  _applyFilterAndSort() {
    if (!this._searchQuery) {
      this._filteredRows = [...this._rows];
    } else {
      const q = this._searchQuery;
      this._filteredRows = this._rows.filter(r => r._searchStr.includes(q));
    }

    if (this._sortKey) {
      this._sortFilteredRows();
    }
  }

  _sortFilteredRows() {
    const key = this._sortKey;
    const dir = this._sortDir === 'desc' ? -1 : 1;

    this._filteredRows.sort((a, b) => {
      const valA = a[key];
      const valB = b[key];

      if (valA == null && valB == null) return 0;
      if (valA == null) return 1;
      if (valB == null) return -1;

      if (typeof valA === 'number' && typeof valB === 'number') {
        return (valA - valB) * dir;
      }

      // Handle Currency / Number-like strings (e.g. "$1,234.50")
      if (typeof valA === 'string' && typeof valB === 'string') {
        const cleanA = valA.replace(/[^0-9.-]/g, '');
        const cleanB = valB.replace(/[^0-9.-]/g, '');
        if (cleanA !== '' && cleanB !== '' && !isNaN(Number(cleanA)) && !isNaN(Number(cleanB))) {
          return (Number(cleanA) - Number(cleanB)) * dir;
        }
      }

      // Handle Dates
      if (typeof valA === 'string' && (valA.includes('-') || valA.includes('/') || valA.includes(':'))) {
        const dateA = Date.parse(valA);
        const dateB = Date.parse(valB);
        if (!isNaN(dateA) && !isNaN(dateB)) {
          return (dateA - dateB) * dir;
        }
      }

      return String(valA).localeCompare(String(valB), undefined, { numeric: true, sensitivity: 'base' }) * dir;
    });
  }

  _renderHeader() {
    if (!this._thead) return;

    this._thead.innerHTML = '';
    const tr = document.createElement('tr');
    tr.setAttribute('role', 'row');

    // Selection checkbox column
    const thSelect = document.createElement('th');
    thSelect.setAttribute('role', 'columnheader');
    thSelect.style.width = '44px';
    thSelect.style.textAlign = 'center';

    const selectAllCheckbox = document.createElement('input');
    selectAllCheckbox.type = 'checkbox';
    selectAllCheckbox.setAttribute('data-part', 'select-all');
    selectAllCheckbox.setAttribute('aria-label', 'Select all rows');
    selectAllCheckbox.className = 'ui-checkbox';
    selectAllCheckbox.addEventListener('change', () => {
      this._toggleSelectAll(selectAllCheckbox.checked);
    });
    this._selectAllCheckbox = selectAllCheckbox;
    thSelect.appendChild(selectAllCheckbox);
    tr.appendChild(thSelect);

    // Dynamic Columns
    this._columns.forEach(col => {
      const th = document.createElement('th');
      th.setAttribute('role', 'columnheader');
      th.setAttribute('tabindex', '0');
      th.setAttribute('data-col-key', col.key);
      if (col.width) th.style.width = col.width;
      if (col.align) th.style.textAlign = col.align;

      const isSortable = col.sortable !== false;
      if (isSortable) {
        th.setAttribute('data-sortable', 'true');
        th.style.cursor = 'pointer';
        th.style.userSelect = 'none';

        const isMatch = col.key === this._sortKey;
        if (isMatch && this._sortDir) {
          th.setAttribute('aria-sort', this._sortDir === 'asc' ? 'ascending' : 'descending');
        } else {
          th.setAttribute('aria-sort', 'none');
        }

        const labelSpan = document.createElement('span');
        labelSpan.textContent = col.label;

        const sortIndicator = document.createElement('span');
        sortIndicator.className = 'grid-sort-icon';
        sortIndicator.style.marginLeft = '0.35rem';
        sortIndicator.style.fontSize = '0.75rem';
        sortIndicator.textContent = isMatch && this._sortDir ? (this._sortDir === 'asc' ? '▲' : '▼') : '⇅';

        th.appendChild(labelSpan);
        th.appendChild(sortIndicator);

        const handleSortClick = () => this._handleSort(col.key, th, sortIndicator);
        th.addEventListener('click', handleSortClick);
        th.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleSortClick();
          }
        });
      } else {
        th.textContent = col.label;
      }

      tr.appendChild(th);
    });

    this._thead.appendChild(tr);
  }

  _handleSort(key, th, sortIndicator) {
    let nextDir = 'asc';
    if (this._sortKey === key) {
      if (this._sortDir === 'asc') nextDir = 'desc';
      else if (this._sortDir === 'desc') nextDir = null;
    }
    this.sortBy(nextDir ? key : null, nextDir);
  }

  _updateRunwayHeight() {
    if (!this._runway) return;
    const totalHeight = this._filteredRows.length * this.rowHeight;
    this._runway.style.height = `${totalHeight}px`;
  }

  _updateVirtualWindow() {
    if (!this._viewport || !this._tbody || this._columns.length === 0) return;

    const scrollTop = this._viewport.scrollTop;
    const viewportHeight = this._viewport.clientHeight || 450;
    const total = this._filteredRows.length;
    const totalCols = this._columns.length + 1; // 1 checkbox column + data columns

    if (total === 0) {
      this._tbody.innerHTML = `
        <tr role="row">
          <td colspan="${totalCols}" style="text-align: center; padding: 3rem 1rem;">
            <div data-ui="empty">
              <div data-ui="empty-icon">🔍</div>
              <div data-ui="empty-title">No matching records</div>
              <div data-ui="empty-description">Try adjusting your search criteria</div>
            </div>
          </td>
        </tr>
      `;
      this._tbody.style.transform = '';
      return;
    }

    const startIndex = Math.max(0, Math.floor(scrollTop / this.rowHeight) - this.overscan);
    const endIndex = Math.min(total, Math.ceil((scrollTop + viewportHeight) / this.rowHeight) + this.overscan);
    const topSpacerHeight = startIndex * this.rowHeight;
    const bottomSpacerHeight = Math.max(0, (total - endIndex) * this.rowHeight);

    this._tbody.style.transform = '';

    const slice = this._filteredRows.slice(startIndex, endIndex);
    const fragment = document.createDocumentFragment();

    // Top Spacer Row (preserves exact scroll position without absolute positioning)
    if (topSpacerHeight > 0) {
      const trTop = document.createElement('tr');
      trTop.className = 'grid-spacer grid-spacer-top';
      trTop.setAttribute('role', 'presentation');
      trTop.setAttribute('aria-hidden', 'true');
      trTop.style.cssText = `height: ${topSpacerHeight}px; border: 0; padding: 0; margin: 0;`;

      const tdTop = document.createElement('td');
      tdTop.colSpan = totalCols;
      tdTop.style.cssText = `height: ${topSpacerHeight}px; border: 0; padding: 0; margin: 0; line-height: 0; font-size: 0; background: transparent;`;
      trTop.appendChild(tdTop);
      fragment.appendChild(trTop);
    }

    // Visible Window Rows
    slice.forEach((row, idx) => {
      const absoluteIndex = startIndex + idx;
      const isSelected = this._selectedIds.has(row._id);

      const tr = document.createElement('tr');
      tr.setAttribute('role', 'row');
      tr.setAttribute('aria-rowindex', String(absoluteIndex + 1));
      tr.setAttribute('data-row-id', row._id);
      tr.style.height = `${this.rowHeight}px`;
      if (isSelected) tr.setAttribute('data-selected', 'true');

      // Checkbox Cell
      const tdSelect = document.createElement('td');
      tdSelect.setAttribute('role', 'gridcell');
      tdSelect.style.width = '44px';
      tdSelect.style.textAlign = 'center';

      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.checked = isSelected;
      cb.className = 'ui-checkbox';
      cb.setAttribute('aria-label', `Select row ${absoluteIndex + 1}`);

      cb.addEventListener('click', (e) => {
        e.stopPropagation();
        this._handleRowSelect(row._id, absoluteIndex, e.shiftKey);
      });

      tdSelect.appendChild(cb);
      tr.appendChild(tdSelect);

      // Data Cells
      this._columns.forEach(col => {
        const td = document.createElement('td');
        td.setAttribute('role', 'gridcell');
        if (col.width) td.style.width = col.width;
        if (col.align) td.style.textAlign = col.align;

        const val = row[col.key];
        if (typeof col.render === 'function') {
          const rendered = col.render(val, row);
          if (rendered instanceof HTMLElement) td.appendChild(rendered);
          else td.innerHTML = String(rendered);
        } else {
          td.textContent = val != null ? String(val) : '';
        }
        tr.appendChild(td);
      });

      fragment.appendChild(tr);
    });

    // Bottom Spacer Row (preserves remaining runway height)
    if (bottomSpacerHeight > 0) {
      const trBottom = document.createElement('tr');
      trBottom.className = 'grid-spacer grid-spacer-bottom';
      trBottom.setAttribute('role', 'presentation');
      trBottom.setAttribute('aria-hidden', 'true');
      trBottom.style.cssText = `height: ${bottomSpacerHeight}px; border: 0; padding: 0; margin: 0;`;

      const tdBottom = document.createElement('td');
      tdBottom.colSpan = totalCols;
      tdBottom.style.cssText = `height: ${bottomSpacerHeight}px; border: 0; padding: 0; margin: 0; line-height: 0; font-size: 0; background: transparent;`;
      trBottom.appendChild(tdBottom);
      fragment.appendChild(trBottom);
    }

    this._tbody.innerHTML = '';
    this._tbody.appendChild(fragment);

    this._updateSelectAllState();
    this._updateFooter();
  }

  _handleRowSelect(rowId, index, isShift) {
    if (isShift && this._lastSelectedIndex !== -1) {
      const start = Math.min(this._lastSelectedIndex, index);
      const end = Math.max(this._lastSelectedIndex, index);
      for (let i = start; i <= end; i++) {
        if (this._filteredRows[i]) {
          this._selectedIds.add(this._filteredRows[i]._id);
        }
      }
    } else {
      if (this._selectedIds.has(rowId)) {
        this._selectedIds.delete(rowId);
      } else {
        this._selectedIds.add(rowId);
      }
      this._lastSelectedIndex = index;
    }

    this._updateVirtualWindow();
    this._persistState?.();
    this.dispatchCustomEvent('selection-change', {
      selectedIds: Array.from(this._selectedIds),
      selectedCount: this._selectedIds.size
    });
  }

  _toggleSelectAll(checked) {
    if (checked) {
      this._filteredRows.forEach(r => this._selectedIds.add(r._id));
    } else {
      this._selectedIds.clear();
    }
    this._updateVirtualWindow();
    this._persistState?.();
    this.dispatchCustomEvent('selection-change', {
      selectedIds: Array.from(this._selectedIds),
      selectedCount: this._selectedIds.size
    });
  }

  _updateSelectAllState() {
    if (!this._selectAllCheckbox || this._filteredRows.length === 0) return;

    let allSelected = true;
    let someSelected = false;

    for (const r of this._filteredRows) {
      if (this._selectedIds.has(r._id)) {
        someSelected = true;
      } else {
        allSelected = false;
      }
    }

    this._selectAllCheckbox.checked = allSelected && someSelected;
    this._selectAllCheckbox.indeterminate = !allSelected && someSelected;
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _updateFooter() {
    if (!this._footer) return;

    const total = this._rows.length;
    const filtered = this._filteredRows.length;
    const selected = this._selectedIds.size;
    const activeNodes = this._tbody ? this._tbody.querySelectorAll('tr:not(.grid-spacer)').length : 0;

    this._footer.innerHTML = `
      <div class="grid-footer-content" style="display: flex; justify-content: space-between; align-items: center; width: 100%; font-size: 0.8rem; color: var(--ui-text-secondary); gap: 0.75rem; flex-wrap: wrap;">
        <div style="display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap;">
          <span>Showing <strong style="color: var(--ui-text-primary);">${filtered.toLocaleString()}</strong> of ${total.toLocaleString()} rows</span>
          ${this._searchQuery ? `<span data-ui="badge" data-variant="secondary" style="font-size: 0.725rem; padding: 0.15rem 0.5rem;">Filter: "${this._escapeHtml(this._searchQuery)}"</span>` : ''}
          ${selected > 0 ? `<span data-ui="badge" data-variant="default" style="font-size: 0.725rem; padding: 0.15rem 0.5rem; background: var(--ui-color-brand-600); color: white;">${selected.toLocaleString()} selected</span>` : ''}
        </div>
        <div style="display: flex; align-items: center; gap: 1rem;">
          <span style="font-size: 0.75rem; color: var(--ui-text-muted); display: inline-flex; align-items: center; gap: 0.35rem;">
            <span style="display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--ui-color-success-500);"></span>
            ${activeNodes} active DOM rows
          </span>
          <span style="font-family: var(--ui-font-mono, monospace); font-size: 0.75rem; font-weight: 600; color: var(--ui-color-success-500); background: rgba(16, 185, 129, 0.1); padding: 0.2rem 0.5rem; border-radius: 4px; border: 1px solid rgba(16, 185, 129, 0.2);">⚡ 60 FPS Virtualized</span>
        </div>
      </div>
    `;
  }

  /**
   * Export currently filtered / selected dataset to CSV
   * @param {string} filename
   */
  exportCsv(filename = 'export-grid.csv') {
    const dataToExport = this._selectedIds.size > 0
      ? this._rows.filter(r => this._selectedIds.has(r._id))
      : this._filteredRows;

    if (dataToExport.length === 0) return;

    const headers = this._columns.map(c => `"${c.label.replace(/"/g, '""')}"`).join(',');
    const rowsCsv = dataToExport.map(row => {
      return this._columns.map(c => {
        const val = row[c.key] != null ? String(row[c.key]) : '';
        return `"${val.replace(/"/g, '""')}"`;
      }).join(',');
    });

    const csvContent = [headers, ...rowsCsv].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  /**
   * Start mock live streaming of incoming rows
   */
  startStreaming(intervalMs = 400, generatorFn) {
    if (this._streamTimer) return;
    this.setAttributeSafe(this, 'streaming', 'true');

    const defaultGenerator = () => {
      const actions = ['BUY', 'SELL', 'TRANSFER', 'SWAP'];
      const symbols = ['BTC/USD', 'ETH/USD', 'SOL/USD', 'NVDA', 'AAPL', 'GOOGL'];
      const action = actions[Math.floor(Math.random() * actions.length)];
      const symbol = symbols[Math.floor(Math.random() * symbols.length)];
      const price = (Math.random() * 1000 + 50).toFixed(2);
      const volume = (Math.random() * 5 + 0.1).toFixed(4);

      return [{
        id: `stream-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
        timestamp: new Date().toLocaleTimeString(),
        symbol,
        action,
        price: `$${price}`,
        volume,
        status: Math.random() > 0.1 ? 'Executed' : 'Pending'
      }];
    };

    const gen = generatorFn || defaultGenerator;

    this._streamTimer = setInterval(() => {
      const newItems = gen();
      this.appendRows(newItems);
    }, intervalMs);
  }

  stopStreaming() {
    if (this._streamTimer) {
      clearInterval(this._streamTimer);
      this._streamTimer = null;
      this.removeAttributeSafe(this, 'streaming');
    }
  }

  destroy() {
    this.stopStreaming();
    if (this._rafId) cancelAnimationFrame(this._rafId);
  }
}

if (typeof customElements !== 'undefined') {
  if (!customElements.get('ui-data-grid')) {
    customElements.define('ui-data-grid', UiDataGrid);
  }
  if (!customElements.get('nnui-data-grid')) {
    customElements.define('nnui-data-grid', class extends UiDataGrid {});
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { attachAnchorFallback, applyPositionFallback } from '../../utils/anchor-fallback.js';
import { attachPersistence } from '../../utils/persistence.js';

/**
 * <ui-date-range-picker> Micro-Enhancer
 * APG-compliant accessible dual-calendar Date Range Picker.
 * Features:
 * - Start & End date selection with hover range preview
 * - Quick range presets (Today, Last 7 Days, Last 30 Days, This Month)
 * - Top-layer Popover API with CSS Anchor Positioning & automated fallback
 * - WAI-ARIA accessible keyboard navigation
 * - Declarative State Persistence: persist="url|session|local" [sync="cross-tab"]
 */
export class UiDateRangePicker extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['start-date', 'end-date', 'placeholder', 'disabled', 'open', 'name', 'persist', 'sync'];
  }

  constructor() {
    super();
    this._startDate = null;
    this._endDate = null;
    this._hoverDate = null;
    this._viewYear = new Date().getFullYear();
    this._viewMonth = new Date().getMonth();
    this._selectingEnd = false;
    if (typeof this.attachInternals === 'function') {
      this._internals = this.attachInternals();
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    if (val) this.setAttributeSafe('name', val);
    else this.removeAttributeSafe('name');
  }

  get value() {
    const s = this._startDate ? this._formatDate(this._startDate) : '';
    const e = this._endDate ? this._formatDate(this._endDate) : '';
    return (s && e) ? `${s} - ${e}` : (s || '');
  }

  set value(val) {
    if (!val) {
      this._startDate = null;
      this._endDate = null;
    } else {
      const parts = String(val).split(' - ');
      this._startDate = parts[0] ? new Date(parts[0].trim()) : null;
      this._endDate = parts[1] ? new Date(parts[1].trim()) : null;
    }
    this._renderTrigger();
    this._renderCalendars();
    this._updateFormValue();
  }

  get startDate() {
    return this._startDate;
  }

  set startDate(val) {
    this._startDate = val ? new Date(val) : null;
    this._renderTrigger();
    this._renderCalendars();
  }

  get endDate() {
    return this._endDate;
  }

  set endDate(val) {
    this._endDate = val ? new Date(val) : null;
    this._renderTrigger();
    this._renderCalendars();
  }

  get isOpen() {
    if (this._popover && typeof this._popover.matches === 'function') {
      try {
        return this._popover.matches(':popover-open') || this.hasAttribute('open');
      } catch (e) {}
    }
    return this.hasAttribute('open');
  }

  set isOpen(val) {
    if (val) this.open();
    else this.close();
  }

  getAiState() {
    return {
      startDate: this._startDate ? this._formatDate(this._startDate) : null,
      endDate: this._endDate ? this._formatDate(this._endDate) : null,
      isOpen: this.isOpen,
      selectingEnd: this._selectingEnd
    };
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'date-range-picker');

    if (this.hasAttribute('start-date')) {
      this._startDate = new Date(this.getAttribute('start-date'));
    }
    if (this.hasAttribute('end-date')) {
      this._endDate = new Date(this.getAttribute('end-date'));
    }

    if (this._startDate && !isNaN(this._startDate.getTime())) {
      this._viewYear = this._startDate.getFullYear();
      this._viewMonth = this._startDate.getMonth();
    }

    this._setupDOM();
    this._renderTrigger();
    this._renderCalendars();

    // Setup Declarative Persistence & Cross-Tab Sync
    if (this.hasAttribute('persist') || this.hasAttribute('sync')) {
      const cleanupPersistence = attachPersistence(this, {
        keys: ['start', 'end'],
        getState: () => ({
          start: this._startDate ? this._formatDate(this._startDate) : '',
          end: this._endDate ? this._formatDate(this._endDate) : ''
        }),
        setState: (state) => {
          if (state.start) {
            this._startDate = new Date(state.start);
            this._viewYear = this._startDate.getFullYear();
            this._viewMonth = this._startDate.getMonth();
          } else if (state.start === '') {
            this._startDate = null;
          }
          if (state.end) {
            this._endDate = new Date(state.end);
          } else if (state.end === '') {
            this._endDate = null;
          }
          this._renderTrigger();
          this._renderCalendars();
        }
      });
      this._cleanups.push(cleanupPersistence);
    }
  }

  _setupDOM() {
    // Generate anchor ID
    const uniqueId = `range-anchor-${Math.random().toString(36).substring(2, 9)}`;
    const popoverId = `range-popover-${Math.random().toString(36).substring(2, 9)}`;

    // Trigger container
    let trigger = this.querySelector('[data-part="trigger"]');
    if (!trigger) {
      trigger = document.createElement('button');
      trigger.type = 'button';
      trigger.setAttribute('data-part', 'trigger');
      trigger.className = 'ui-date-range-trigger';
      this.appendChild(trigger);
    }
    this._trigger = trigger;
    this._trigger.style.anchorName = `--${uniqueId}`;
    this._trigger.setAttribute('aria-haspopup', 'dialog');
    this._trigger.setAttribute('aria-expanded', 'false');

    // Popover
    let popover = this.querySelector('[data-part="popover"]');
    if (!popover) {
      popover = document.createElement('div');
      popover.setAttribute('data-part', 'popover');
      popover.setAttribute('popover', 'auto');
      popover.id = popoverId;
      popover.className = 'ui-date-range-popover';
      this.appendChild(popover);
    }
    this._popover = popover;
    this._popover.style.positionAnchor = `--${uniqueId}`;

    // Popover Toggle Event with light-dismiss re-open guard
    this._lastClosedTime = 0;
    this._trigger.addEventListener('click', (e) => {
      e.preventDefault();
      if (Date.now() - this._lastClosedTime < 150) {
        return;
      }
      this.toggle();
    });

    this._popover.addEventListener('toggle', (e) => {
      if (e.newState === 'open') {
        this.setAttributeSafe(this, 'open', '');
        this._trigger?.setAttribute('aria-expanded', 'true');
        this._reposition();
        if (typeof requestAnimationFrame === 'function') {
          requestAnimationFrame(this._reposition);
        }
        setTimeout(this._reposition, 15);
        this.dispatchCustomEvent('open');
      } else {
        this._lastClosedTime = Date.now();
        this.removeAttributeSafe(this, 'open');
        this._trigger?.setAttribute('aria-expanded', 'false');
        this.dispatchCustomEvent('close');
      }
    });

    // Anchor Fallback
    const cleanupAnchor = attachAnchorFallback(this._trigger, this._popover, {
      placement: 'bottom-start',
      offset: 8
    });
    this._cleanups.push(cleanupAnchor);
  }

  _reposition = () => {
    if (!this.isOpen || !this._popover) return;
    const trigger = (this._trigger && this._trigger.isConnected) ? this._trigger : this.querySelector('[data-part="trigger"]');
    if (!trigger) return;
    applyPositionFallback(trigger, this._popover, { placement: 'bottom-start', offset: 8 });
  };

  open() {
    if (this.hasAttribute('disabled')) return;
    if (this._popover && typeof this._popover.showPopover === 'function') {
      try {
        if (!this._popover.matches(':popover-open')) {
          this._popover.showPopover();
        }
      } catch (e) {
        this._popover.setAttribute('open', '');
      }
    } else if (this._popover) {
      this._popover.setAttribute('open', '');
    }
    this.setAttributeSafe(this, 'open', '');
    this._trigger?.setAttribute('aria-expanded', 'true');

    this._reposition();
    if (typeof requestAnimationFrame === 'function') {
      requestAnimationFrame(this._reposition);
    }
    setTimeout(this._reposition, 15);

    if (typeof window !== 'undefined') {
      window.addEventListener('scroll', this._reposition, { passive: true, capture: true });
      window.addEventListener('resize', this._reposition, { passive: true });
    }

    this.dispatchCustomEvent('open');
  }

  close() {
    if (typeof window !== 'undefined') {
      window.removeEventListener('scroll', this._reposition, { capture: true });
      window.removeEventListener('resize', this._reposition);
    }

    if (this._popover && typeof this._popover.hidePopover === 'function') {
      try {
        if (this._popover.matches(':popover-open')) {
          this._popover.hidePopover();
        }
      } catch (e) {
        this._popover.removeAttribute('open');
      }
    } else if (this._popover) {
      this._popover.removeAttribute('open');
    }
    this.removeAttributeSafe(this, 'open');
    this._trigger?.setAttribute('aria-expanded', 'false');
    this.dispatchCustomEvent('close');
  }

  toggle() {
    if (this.isOpen) this.close();
    else this.open();
  }

  _formatDate(date) {
    if (!date || isNaN(date.getTime())) return '';
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  _formatDisplayDate(d) {
    if (!d || isNaN(d.getTime())) return '';
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${months[d.getMonth()]} ${String(d.getDate()).padStart(2, '0')}, ${d.getFullYear()}`;
  }

  _renderTrigger() {
    if (!this._trigger) return;

    const startStr = this._formatDisplayDate(this._startDate);
    const endStr = this._formatDisplayDate(this._endDate);
    const placeholder = this.getAttribute('placeholder') || 'Select date range...';

    let displayHtml = '';
    if (startStr && endStr) {
      displayHtml = `<span style="font-weight: 500;">${startStr}</span> <span style="color: var(--ui-text-muted); font-size: 0.8rem; margin: 0 0.25rem;">→</span> <span style="font-weight: 500;">${endStr}</span>`;
    } else if (startStr) {
      displayHtml = `<span style="font-weight: 500;">${startStr}</span> <span style="color: var(--ui-text-muted); font-size: 0.8rem; margin: 0 0.25rem;">→</span> <span style="color: var(--ui-text-muted);">Pick end date</span>`;
    } else {
      displayHtml = `<span style="color: var(--ui-text-muted); font-weight: 400;">${placeholder}</span>`;
    }

    this._trigger.innerHTML = `
      <div style="display: flex; align-items: center; gap: 0.6rem; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="color: var(--ui-text-muted); flex-shrink: 0;">
          <rect width="18" height="18" x="3" y="4" rx="2" ry="2"/>
          <line x1="16" x2="16" y1="2" y2="6"/>
          <line x1="8" x2="8" y1="2" y2="6"/>
          <line x1="3" x2="21" y1="10" y2="10"/>
        </svg>
        <span style="overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${displayHtml}</span>
      </div>
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="color: var(--ui-text-muted); flex-shrink: 0; margin-left: 0.5rem;">
        <path d="m6 9 6 6 6-6"/>
      </svg>
    `;
  }

  _renderCalendars() {
    if (!this._popover) return;

    const month1Date = new Date(this._viewYear, this._viewMonth, 1);
    const month2Date = new Date(this._viewYear, this._viewMonth + 1, 1);

    const monthNames = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December'
    ];

    let rangeText = 'Select start and end dates';
    let durationBadge = '';
    if (this._startDate && this._endDate) {
      rangeText = `${this._formatDisplayDate(this._startDate)} → ${this._formatDisplayDate(this._endDate)}`;
      const days = Math.round(Math.abs((this._endDate.getTime() - this._startDate.getTime()) / (1000 * 60 * 60 * 24))) + 1;
      durationBadge = `<span class="range-duration-badge">${days} day${days === 1 ? '' : 's'}</span>`;
    } else if (this._startDate) {
      rangeText = `${this._formatDisplayDate(this._startDate)} → Pick end date`;
      durationBadge = `<span class="range-duration-badge" style="display: none;"></span>`;
    } else {
      durationBadge = `<span class="range-duration-badge" style="display: none;"></span>`;
    }

    this._popover.innerHTML = `
      <div class="range-picker-container">

        <!-- Header Presets Bar -->
        <div class="range-header-bar">
          <button type="button" class="range-preset-btn" data-preset="today">Today</button>
          <button type="button" class="range-preset-btn" data-preset="7d">Last 7 Days</button>
          <button type="button" class="range-preset-btn" data-preset="30d">Last 30 Days</button>
          <button type="button" class="range-preset-btn" data-preset="month">This Month</button>
        </div>

        <!-- Dual Calendars View (Side-by-side) -->
        <div class="range-calendars-wrapper">

          <!-- Month 1 (Left) -->
          <div class="range-calendar-pane">
            <div class="range-month-header">
              <button type="button" class="range-nav-btn range-nav-prev" aria-label="Previous month">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                  <path d="m15 18-6-6 6-6"/>
                </svg>
              </button>
              <span class="range-month-title">
                ${monthNames[month1Date.getMonth()]} ${month1Date.getFullYear()}
              </span>
              <span style="width: 28px; height: 28px; display: inline-block;"></span>
            </div>
            ${this._generateMonthGridHtml(month1Date)}
          </div>

          <!-- Divider -->
          <div class="range-calendars-divider"></div>

          <!-- Month 2 (Right) -->
          <div class="range-calendar-pane">
            <div class="range-month-header">
              <span style="width: 28px; height: 28px; display: inline-block;"></span>
              <span class="range-month-title">
                ${monthNames[month2Date.getMonth()]} ${month2Date.getFullYear()}
              </span>
              <button type="button" class="range-nav-btn range-nav-next" aria-label="Next month">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                  <path d="m9 18 6-6-6-6"/>
                </svg>
              </button>
            </div>
            ${this._generateMonthGridHtml(month2Date)}
          </div>

        </div>

        <!-- Footer Actions Bar -->
        <div class="range-footer-bar">
          <div class="range-summary-text">
            <span>${rangeText}</span>
            ${durationBadge}
          </div>
          <div class="range-actions-group">
            <button type="button" class="range-btn-clear">Clear</button>
            <button type="button" class="range-btn-apply">Apply Range</button>
          </div>
        </div>

      </div>
    `;

    this._bindCalendarInteractions();
  }

  _generateMonthGridHtml(monthDate) {
    const year = monthDate.getFullYear();
    const month = monthDate.getMonth();

    const firstDayIndex = new Date(year, month, 1).getDay(); // 0 is Sunday
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    let gridHtml = `
      <table class="range-grid-table">
        <thead>
          <tr>
            <th>Su</th><th>Mo</th><th>Tu</th><th>We</th><th>Th</th><th>Fr</th><th>Sa</th>
          </tr>
        </thead>
        <tbody>
          <tr>
    `;

    // Empty cells before first day
    for (let i = 0; i < firstDayIndex; i++) {
      gridHtml += `<td></td>`;
    }

    let currentDay = 1;
    let col = firstDayIndex;

    const startNorm = this._normalizeDate(this._startDate);
    const endNorm = this._normalizeDate(this._endDate);
    const hoverNorm = this._normalizeDate(this._hoverDate);

    while (currentDay <= daysInMonth) {
      if (col === 7) {
        gridHtml += `</tr><tr>`;
        col = 0;
      }

      const thisDate = new Date(year, month, currentDay);
      const thisNorm = this._normalizeDate(thisDate);
      const isStart = startNorm && thisNorm.getTime() === startNorm.getTime();
      const isEnd = endNorm && thisNorm.getTime() === endNorm.getTime();

      let inRange = false;
      if (startNorm && endNorm) {
        const minT = Math.min(startNorm.getTime(), endNorm.getTime());
        const maxT = Math.max(startNorm.getTime(), endNorm.getTime());
        inRange = thisNorm.getTime() > minT && thisNorm.getTime() < maxT;
      } else if (startNorm && hoverNorm && this._selectingEnd) {
        const minDate = Math.min(startNorm.getTime(), hoverNorm.getTime());
        const maxDate = Math.max(startNorm.getTime(), hoverNorm.getTime());
        inRange = thisNorm.getTime() > minDate && thisNorm.getTime() < maxDate;
      }

      let tdClass = '';
      if (isStart && isEnd) {
        tdClass = 'range-start range-end range-single';
      } else if (isStart) {
        tdClass = 'range-start' + (!endNorm && !hoverNorm ? ' range-single' : '');
      } else if (isEnd) {
        tdClass = 'range-end';
      } else if (inRange) {
        tdClass = 'in-range';
      }
      const tdClassAttr = tdClass ? `class="${tdClass}"` : '';

      let dateAttr = `data-date="${this._formatDate(thisDate)}"`;
      let rangeAttr = '';
      if (isStart) rangeAttr = 'data-range="start"';
      else if (isEnd) rangeAttr = 'data-range="end"';
      else if (inRange) rangeAttr = 'data-range="in-range"';

      gridHtml += `
        <td ${tdClassAttr}>
          <button type="button" class="range-cell-btn" ${dateAttr} ${rangeAttr}>
            ${currentDay}
          </button>
        </td>
      `;

      currentDay++;
      col++;
    }

    // Remaining empty cells
    while (col < 7 && col > 0) {
      gridHtml += `<td></td>`;
      col++;
    }

    gridHtml += `</tr></tbody></table>`;
    return gridHtml;
  }

  _normalizeDate(d) {
    if (!d || isNaN(d.getTime())) return null;
    return new Date(d.getFullYear(), d.getMonth(), d.getDate());
  }

  _bindCalendarInteractions() {
    if (!this._popover) return;

    // Navigation
    const prevBtn = this._popover.querySelector('.range-nav-prev');
    const nextBtn = this._popover.querySelector('.range-nav-next');

    if (prevBtn) {
      prevBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this._viewMonth--;
        if (this._viewMonth < 0) {
          this._viewMonth = 11;
          this._viewYear--;
        }
        this._renderCalendars();
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this._viewMonth++;
        if (this._viewMonth > 11) {
          this._viewMonth = 0;
          this._viewYear++;
        }
        this._renderCalendars();
      });
    }

    // Presets
    this._popover.querySelectorAll('.range-preset-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const preset = btn.getAttribute('data-preset');
        this._applyPreset(preset);
      });
    });

    // Date Cell Clicks & Hover (Non-destructive hover preview to protect click events)
    this._popover.querySelectorAll('.range-cell-btn[data-date]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const dateStr = btn.getAttribute('data-date');
        if (!dateStr) return;
        const [y, m, d] = dateStr.split('-').map(Number);
        this._handleDateClick(new Date(y, m - 1, d));
      });

      btn.addEventListener('mouseenter', () => {
        if (this._selectingEnd) {
          const dateStr = btn.getAttribute('data-date');
          if (!dateStr) return;
          const [y, m, d] = dateStr.split('-').map(Number);
          this._updateHoverRange(new Date(y, m - 1, d));
        }
      });
    });

    // Reset hover when mouse leaves calendar area while selecting end date
    const calendarsWrapper = this._popover.querySelector('.range-calendars-wrapper');
    if (calendarsWrapper) {
      calendarsWrapper.addEventListener('mouseleave', () => {
        if (this._selectingEnd && this._startDate) {
          this._resetHoverToStart();
        }
      });
    }

    // Apply Button
    const applyBtn = this._popover.querySelector('.range-btn-apply');
    if (applyBtn) {
      applyBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (this._startDate && this._endDate) {
          this.dispatchCustomEvent('change', {
            start: this._formatDate(this._startDate),
            end: this._formatDate(this._endDate),
            range: [this._startDate, this._endDate]
          });
        }
        this.close();
      });
    }

    // Clear Button
    const clearBtn = this._popover.querySelector('.range-btn-clear');
    if (clearBtn) {
      clearBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this._startDate = null;
        this._endDate = null;
        this._hoverDate = null;
        this._selectingEnd = false;
        this._renderTrigger();
        this._renderCalendars();
        this._persistState?.();
        this.dispatchCustomEvent('change', { start: null, end: null, range: [] });
      });
    }
  }

  _updateHoverRange(hoverDate) {
    if (!this._popover || !this._selectingEnd || !this._startDate) return;

    this._hoverDate = hoverDate;
    const startNorm = this._normalizeDate(this._startDate);
    const hoverNorm = this._normalizeDate(hoverDate);
    if (!startNorm || !hoverNorm) return;

    const startTime = startNorm.getTime();
    const hoverTime = hoverNorm.getTime();
    const minTime = Math.min(startTime, hoverTime);
    const maxTime = Math.max(startTime, hoverTime);

    // Smoothly update attributes and classes in-place without rebuilding DOM
    const cellBtns = this._popover.querySelectorAll('.range-cell-btn[data-date]');
    cellBtns.forEach(btn => {
      const dateStr = btn.getAttribute('data-date');
      if (!dateStr) return;
      const [y, m, d] = dateStr.split('-').map(Number);
      const cellTime = new Date(y, m - 1, d).getTime();
      const td = btn.closest('td');

      btn.removeAttribute('data-range');
      if (td) td.className = '';

      if (startTime === hoverTime) {
        if (cellTime === startTime) {
          btn.setAttribute('data-range', 'start');
          if (td) td.className = 'range-start range-end range-single';
        }
      } else if (hoverTime > startTime) {
        if (cellTime === startTime) {
          btn.setAttribute('data-range', 'start');
          if (td) td.className = 'range-start';
        } else if (cellTime === hoverTime) {
          btn.setAttribute('data-range', 'end');
          if (td) td.className = 'range-end';
        } else if (cellTime > minTime && cellTime < maxTime) {
          btn.setAttribute('data-range', 'in-range');
          if (td) td.className = 'in-range';
        }
      } else {
        if (cellTime === hoverTime) {
          btn.setAttribute('data-range', 'start');
          if (td) td.className = 'range-start';
        } else if (cellTime === startTime) {
          btn.setAttribute('data-range', 'end');
          if (td) td.className = 'range-end';
        } else if (cellTime > minTime && cellTime < maxTime) {
          btn.setAttribute('data-range', 'in-range');
          if (td) td.className = 'in-range';
        }
      }
    });

    const summarySpan = this._popover.querySelector('.range-summary-text span');
    if (summarySpan) {
      const d1 = new Date(minTime);
      const d2 = new Date(maxTime);
      summarySpan.textContent = `${this._formatDisplayDate(d1)} → ${this._formatDisplayDate(d2)}`;
    }
    const badge = this._popover.querySelector('.range-duration-badge');
    const days = Math.round(Math.abs((maxTime - minTime) / (1000 * 60 * 60 * 24))) + 1;
    if (badge) {
      badge.textContent = `${days} day${days === 1 ? '' : 's'}`;
      badge.style.display = 'inline-flex';
    }
  }

  _resetHoverToStart() {
    if (!this._popover || !this._startDate) return;
    this._hoverDate = null;
    const startNorm = this._normalizeDate(this._startDate);
    const startTime = startNorm ? startNorm.getTime() : null;

    const cellBtns = this._popover.querySelectorAll('.range-cell-btn[data-date]');
    cellBtns.forEach(btn => {
      const dateStr = btn.getAttribute('data-date');
      if (!dateStr) return;
      const [y, m, d] = dateStr.split('-').map(Number);
      const cellTime = new Date(y, m - 1, d).getTime();
      const td = btn.closest('td');

      btn.removeAttribute('data-range');
      if (td) td.className = '';

      if (startTime && cellTime === startTime) {
        btn.setAttribute('data-range', 'start');
        if (td) td.className = 'range-start range-single';
      }
    });

    const summarySpan = this._popover.querySelector('.range-summary-text span');
    if (summarySpan) {
      summarySpan.textContent = `${this._formatDisplayDate(this._startDate)} → Pick end date`;
    }
    const badge = this._popover.querySelector('.range-duration-badge');
    if (badge) {
      badge.style.display = 'none';
    }
  }

  _handleDateClick(clickedDate) {
    if (!this._startDate || (this._startDate && this._endDate)) {
      // First click: select start date
      this._startDate = clickedDate;
      this._endDate = null;
      this._hoverDate = null;
      this._selectingEnd = true;
      this._renderTrigger();
      this._renderCalendars();
    } else if (this._startDate && !this._endDate) {
      // Second click: select end date
      const startNorm = this._normalizeDate(this._startDate);
      const clickedNorm = this._normalizeDate(clickedDate);

      if (clickedNorm.getTime() < startNorm.getTime()) {
        this._endDate = this._startDate;
        this._startDate = clickedDate;
      } else {
        this._endDate = clickedDate;
      }
      this._selectingEnd = false;
      this._hoverDate = null;

      this._renderTrigger();
      this._renderCalendars();
      this.close();

      this._persistState?.();
      this.dispatchCustomEvent('change', {
        start: this._formatDate(this._startDate),
        end: this._formatDate(this._endDate),
        range: [this._startDate, this._endDate]
      });
    }
  }

  _applyPreset(preset) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (preset === 'today') {
      this._startDate = new Date(today);
      this._endDate = new Date(today);
    } else if (preset === '7d') {
      this._endDate = new Date(today);
      this._startDate = new Date(today.getTime() - 6 * 24 * 60 * 60 * 1000);
    } else if (preset === '30d') {
      this._endDate = new Date(today);
      this._startDate = new Date(today.getTime() - 29 * 24 * 60 * 60 * 1000);
    } else if (preset === 'month') {
      this._startDate = new Date(today.getFullYear(), today.getMonth(), 1);
      this._endDate = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    }

    this._selectingEnd = false;
    this._viewYear = this._startDate.getFullYear();
    this._viewMonth = this._startDate.getMonth();
    this._renderTrigger();
    this._renderCalendars();
    this.close();

    this._persistState?.();
    this.dispatchCustomEvent('change', {
      start: this._formatDate(this._startDate),
      end: this._formatDate(this._endDate),
      range: [this._startDate, this._endDate]
    });
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (oldVal === newVal) return;
    if (name === 'start-date') {
      this._startDate = newVal ? new Date(newVal) : null;
      if (this._startDate && !isNaN(this._startDate.getTime())) {
        this._viewYear = this._startDate.getFullYear();
        this._viewMonth = this._startDate.getMonth();
      }
      this._renderTrigger();
      this._renderCalendars();
    } else if (name === 'end-date') {
      this._endDate = newVal ? new Date(newVal) : null;
      this._renderTrigger();
      this._renderCalendars();
    } else if (name === 'open') {
      if (newVal !== null && !this.isOpen) {
        this.open();
      } else if (newVal === null && this.isOpen) {
        this.close();
      }
    } else if (name === 'disabled') {
      if (this._trigger) {
        if (this.hasAttribute('disabled')) {
          this._trigger.setAttribute('disabled', '');
        } else {
          this._trigger.removeAttribute('disabled');
        }
      }
    }
  }

  _updateFormValue() {
    if (this._internals) {
      this._internals.setFormValue(this.value);
    }
  }

  formResetCallback() {
    const startAttr = this.getAttribute('start-date');
    const endAttr = this.getAttribute('end-date');
    this._startDate = startAttr ? new Date(startAttr) : null;
    this._endDate = endAttr ? new Date(endAttr) : null;
    this._renderTrigger();
    this._renderCalendars();
    this._updateFormValue();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    if (typeof window !== 'undefined') {
      window.removeEventListener('scroll', this._reposition, { capture: true });
      window.removeEventListener('resize', this._reposition);
    }
  }
}

if (typeof customElements !== 'undefined') {
  if (!customElements.get('ui-date-range-picker')) {
    customElements.define('ui-date-range-picker', UiDateRangePicker);
  }
  if (!customElements.get('nnui-date-range-picker')) {
    customElements.define('nnui-date-range-picker', class extends UiDateRangePicker {});
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * <ui-tags-input> Micro-Enhancer
 * Accessible multi-token tag input with chip management and keyboard badge removal.
 * 
 * Features:
 * - Enter or comma to create new tags
 * - Backspace removes the last tag when input is empty
 * - Duplicate prevention & max tags limit
 * - Click-to-remove badge button
 * - Form associated / standard change events
 */
export class UiTagsInput extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['placeholder', 'max-tags', 'disabled', 'delimiter', 'name', 'value'];
  }

  constructor() {
    super();
    this._tags = [];
    if (typeof this.attachInternals === 'function') {
      this._internals = this.attachInternals();
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    if (val) this.setAttributeSafe(this, 'name', val);
    else this.removeAttributeSafe(this, 'name');
  }

  get value() {
    return this._tags.join(',');
  }

  set value(val) {
    if (typeof val === 'string') {
      this._tags = val ? val.split(',').map(s => s.trim()).filter(Boolean) : [];
      this._render();
      this._updateFormValue();
    }
  }

  get tags() {
    return [...this._tags];
  }

  set tags(val) {
    if (Array.isArray(val)) {
      this._tags = [...val];
      this._render();
      this._updateFormValue();
    }
  }

  get maxTags() {
    const val = parseInt(this.getAttribute('max-tags'), 10);
    return isNaN(val) ? Infinity : val;
  }

  set maxTags(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe(this, 'max-tags', String(val));
    else this.removeAttributeSafe(this, 'max-tags');
  }

  init() {
    this.setAttributeSafe(this, 'data-ui', 'tags-input');
    this.setAttributeSafe(this, 'role', 'group');

    // Read initial tags from DOM if present or attribute
    const initialTagsAttr = this.getAttribute('value') || this.getAttribute('tags');
    if (initialTagsAttr) {
      this._tags = initialTagsAttr.split(',').map(s => s.trim()).filter(Boolean);
    } else {
      const existingChips = this.querySelectorAll('[data-part="tag"]');
      if (existingChips.length > 0) {
        this._tags = Array.from(existingChips).map(el => el.getAttribute('data-value') || el.textContent.replace('×', '').trim());
      }
    }

    this._setupElements();
    this._render();
  }

  _setupElements() {
    this.innerHTML = '';
    this.className = 'ui-tags-input-container';

    this._chipsWrapper = document.createElement('div');
    this._chipsWrapper.className = 'ui-tags-chips-wrapper';
    this.appendChild(this._chipsWrapper);

    this._input = document.createElement('input');
    this._input.type = 'text';
    this._input.setAttribute('data-part', 'input');
    this._input.className = 'ui-tags-input-field';
    this._input.placeholder = this.getAttribute('placeholder') || 'Add tag...';

    if (this.hasAttribute('disabled')) {
      this._input.disabled = true;
    }

    this.appendChild(this._input);

    // Event Listeners
    this._input.addEventListener('keydown', (e) => {
      const val = this._input.value.trim();

      if (e.key === 'Enter' || e.key === ',') {
        e.preventDefault();
        if (val) {
          this.addTag(val);
          this._input.value = '';
        }
      } else if (e.key === 'Backspace' && !this._input.value && this._tags.length > 0) {
        e.preventDefault();
        const removed = this._tags[this._tags.length - 1];
        this.removeTag(removed);
      }
    });

    // Clicking anywhere in container focuses input
    this.addEventListener('click', (e) => {
      if (e.target !== this._input && !e.target.closest('[data-part="remove-tag"]')) {
        this._input.focus();
      }
    });
  }

  _render() {
    if (!this._chipsWrapper) return;
    this._chipsWrapper.innerHTML = '';

    this._tags.forEach((tag, idx) => {
      const chip = document.createElement('span');
      chip.setAttribute('data-part', 'tag');
      chip.setAttribute('data-value', tag);
      chip.className = 'ui-tag-badge';

      const label = document.createElement('span');
      label.textContent = tag;
      chip.appendChild(label);

      const removeBtn = document.createElement('button');
      removeBtn.type = 'button';
      removeBtn.setAttribute('data-part', 'remove-tag');
      removeBtn.setAttribute('aria-label', `Remove ${tag}`);
      removeBtn.className = 'ui-tag-remove-btn';
      removeBtn.textContent = '×';

      removeBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this.removeTag(tag);
        this._input.focus();
      });

      chip.appendChild(removeBtn);
      this._chipsWrapper.appendChild(chip);
    });

    // Update input visibility if maxTags reached
    if (this._tags.length >= this.maxTags) {
      this._input.style.display = 'none';
    } else {
      this._input.style.display = 'inline-block';
    }
  }

  addTag(tagText) {
    const clean = tagText.trim().replace(/^,+|,+$/g, '');
    if (!clean) return false;

    // Check duplicate
    if (this._tags.some(t => t.toLowerCase() === clean.toLowerCase())) {
      // Flash existing tag
      const existing = this._chipsWrapper.querySelector(`[data-value="${clean}"]`);
      if (existing) {
        existing.style.outline = '2px solid var(--ui-color-warning-500)';
        setTimeout(() => existing.style.outline = 'none', 600);
      }
      return false;
    }

    if (this._tags.length >= this.maxTags) return false;

    this._tags.push(clean);
    this._render();

    this.dispatchCustomEvent('change', {
      tags: [...this._tags],
      added: clean
    });

    return true;
  }

  removeTag(tagText) {
    const initialLen = this._tags.length;
    this._tags = this._tags.filter(t => t !== tagText);

    if (this._tags.length !== initialLen) {
      this._render();
      this.dispatchCustomEvent('change', {
        tags: [...this._tags],
        removed: tagText
      });
      return true;
    }
    return false;
  }

  clear() {
    this._tags = [];
    this._render();
    this._updateFormValue();
    this.dispatchCustomEvent('change', { tags: [] });
  }

  _updateFormValue() {
    if (this._internals) {
      this._internals.setFormValue(this._tags.join(','));
    }
  }

  formResetCallback() {
    const initialTagsAttr = this.getAttribute('value') || this.getAttribute('tags') || '';
    this._tags = initialTagsAttr ? initialTagsAttr.split(',').map(s => s.trim()).filter(Boolean) : [];
    this._render();
    this._updateFormValue();
  }
}

if (typeof customElements !== 'undefined') {
  if (!customElements.get('ui-tags-input')) {
    customElements.define('ui-tags-input', UiTagsInput);
  }
  if (!customElements.get('nnui-tags-input')) {
    customElements.define('nnui-tags-input', class extends UiTagsInput {});
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys, getNextIndex } from '../../utils/a11y.js';

/**
 * <ui-segmented-control> Micro-Enhancer
 * Accessible segmented pill control / toggle group in Light-DOM.
 * 
 * Features:
 * - WAI-ARIA APG Radiogroup pattern (role="radiogroup", role="radio")
 * - Roving tabindex with ArrowLeft / ArrowRight / Home / End
 * - Smooth sliding pill indicator with CSS transform
 * - Form-associated name/value integration
 * - Standard 'change' CustomEvent with { value }
 */
export class UiSegmentedControl extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['value', 'name', 'disabled', 'size'];
  }

  constructor() {
    super();
    if (typeof this.attachInternals === 'function') {
      this._internals = this.attachInternals();
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get value() {
    return this.getAttribute('value') || '';
  }

  set value(val) {
    this.setAttributeSafe('value', val);
    this._syncState();
  }

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    this.setAttributeSafe('name', val);
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) {
      this.setAttributeSafe('disabled', '');
    } else {
      this.removeAttributeSafe('disabled');
    }
    this._syncState();
  }

  init() {
    this.setAttributeSafe('data-ui', 'segmented-control');
    this.setAttributeSafe('role', 'radiogroup');

    this._setupStructure();
    this._syncState();
    this._bindEvents();

    // Listen for resize to update indicator position
    if (typeof ResizeObserver !== 'undefined') {
      const ro = new ResizeObserver(() => this._updateIndicator());
      ro.observe(this);
      this._cleanups.push(() => ro.disconnect());
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue || !this._initialized) return;
    if (name === 'value' || name === 'disabled') {
      this._syncState();
    }
  }

  _getSegments() {
    return Array.from(this.querySelectorAll('[data-part="segment"], [role="radio"]'));
  }

  _setupStructure() {
    const segments = this._getSegments();
    if (segments.length === 0) return;

    // Ensure hidden input for form submission if name is present
    if (this.name && !this.querySelector('input[type="hidden"]')) {
      const hiddenInput = document.createElement('input');
      hiddenInput.type = 'hidden';
      hiddenInput.name = this.name;
      hiddenInput.value = this.value;
      this.appendChild(hiddenInput);
      this._hiddenInput = hiddenInput;
    } else {
      this._hiddenInput = this.querySelector('input[type="hidden"]');
    }

    // Ensure indicator exists
    if (!this.querySelector('[data-part="indicator"]')) {
      const indicator = document.createElement('div');
      indicator.setAttribute('data-part', 'indicator');
      indicator.className = 'ui-segment-indicator';
      indicator.setAttribute('aria-hidden', 'true');
      this.prepend(indicator);
    }

    segments.forEach((seg, idx) => {
      const val = seg.getAttribute('data-value') || `opt-${idx}`;
      seg.setAttribute('data-value', val);
      seg.setAttribute('role', 'radio');
    });

    // Default to first segment if no value is set
    if (!this.value && segments.length > 0) {
      this.value = segments[0].getAttribute('data-value');
    }
  }

  _syncState() {
    const segments = this._getSegments();
    const currentVal = this.value;
    const isControlDisabled = this.disabled;

    let activeSegment = null;

    segments.forEach((seg) => {
      const isSelected = seg.getAttribute('data-value') === currentVal;
      const isDisabled = isControlDisabled || seg.hasAttribute('disabled');

      this.setAttributeSafe(seg, 'aria-checked', isSelected ? 'true' : 'false');
      this.setAttributeSafe(seg, 'data-state', isSelected ? 'checked' : 'unchecked');
      this.setAttributeSafe(seg, 'tabindex', isSelected && !isDisabled ? '0' : '-1');

      if (isDisabled) {
        this.setAttributeSafe(seg, 'aria-disabled', 'true');
      } else {
        this.removeAttributeSafe(seg, 'aria-disabled');
      }

      if (isSelected) {
        activeSegment = seg;
      }
    });

    if (this._hiddenInput) {
      this._hiddenInput.value = currentVal;
    }
    this._updateFormValue();

    this._updateIndicator(activeSegment);
  }

  _updateFormValue() {
    if (this._internals) {
      this._internals.setFormValue(this.value);
    }
  }

  formResetCallback() {
    const defaultSeg = this._getSegments().find(s => s.hasAttribute('default-selected') || s.hasAttribute('selected'));
    const initialVal = defaultSeg ? (defaultSeg.dataset.value || defaultSeg.getAttribute('value') || defaultSeg.textContent.trim()) : (this.getAttribute('value') || '');
    this.value = initialVal;
    this._syncState();
  }

  _updateIndicator(activeSegment = null) {
    const indicator = this.querySelector('[data-part="indicator"]');
    if (!indicator) return;

    if (!activeSegment) {
      activeSegment = this.querySelector('[data-part="segment"][data-state="checked"]');
    }

    if (!activeSegment || activeSegment.offsetWidth === 0) {
      indicator.style.opacity = '0';
      return;
    }

    indicator.style.opacity = '1';
    indicator.style.width = `${activeSegment.offsetWidth}px`;
    indicator.style.height = `${activeSegment.offsetHeight}px`;
    indicator.style.transform = `translate3d(${activeSegment.offsetLeft}px, ${activeSegment.offsetTop}px, 0)`;
  }

  _bindEvents() {
    this.listen(this, 'click', (e) => {
      const seg = e.target.closest('[data-part="segment"], [role="radio"]');
      if (!seg || this.disabled || seg.hasAttribute('disabled') || seg.getAttribute('aria-disabled') === 'true') return;

      const newVal = seg.getAttribute('data-value');
      if (newVal && newVal !== this.value) {
        this.select(newVal);
      }
    });

    this.listen(this, 'keydown', (e) => {
      if (this.disabled) return;
      const segments = this._getSegments().filter(s => !s.hasAttribute('disabled') && s.getAttribute('aria-disabled') !== 'true');
      if (segments.length === 0) return;

      const currentIdx = segments.findIndex(s => s.getAttribute('data-value') === this.value);
      let targetIdx = -1;

      switch (e.key) {
        case Keys.ARROW_RIGHT:
        case Keys.ARROW_DOWN:
          e.preventDefault();
          targetIdx = getNextIndex(currentIdx, segments.length, 1, true);
          break;
        case Keys.ARROW_LEFT:
        case Keys.ARROW_UP:
          e.preventDefault();
          targetIdx = getNextIndex(currentIdx, segments.length, -1, true);
          break;
        case Keys.HOME:
          e.preventDefault();
          targetIdx = 0;
          break;
        case Keys.END:
          e.preventDefault();
          targetIdx = segments.length - 1;
          break;
        case Keys.SPACE:
        case Keys.ENTER: {
          const focused = e.target.closest('[data-part="segment"]');
          if (focused && !focused.hasAttribute('disabled')) {
            e.preventDefault();
            this.select(focused.getAttribute('data-value'));
          }
          return;
        }
      }

      if (targetIdx !== -1 && targetIdx !== currentIdx) {
        const targetSeg = segments[targetIdx];
        const val = targetSeg.getAttribute('data-value');
        this.select(val);
        targetSeg.focus();
      }
    });
  }

  select(val) {
    const prev = this.value;
    if (prev === val) return;

    this.value = val;
    this.dispatch('change', { value: val, previousValue: prev });
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys } from '../../utils/a11y.js';

/**
 * <ui-otp-input> Micro-Enhancer
 * Accessible One-Time Password (OTP) / PIN verification code input in Light-DOM.
 * 
 * Features:
 * - Auto-advancing focus on single digit entry
 * - Backspace deletes and navigates to previous slot
 * - ArrowLeft / ArrowRight navigation
 * - Clipboard paste distribution across all slots
 * - Mobile-friendly inputmode="numeric" and autocomplete="one-time-code"
 * - 'input' and 'change' CustomEvents with { value, isComplete }
 */
export class UiOtpInput extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['length', 'value', 'name', 'disabled', 'type', 'mask'];
  }

  constructor() {
    super();
    if (typeof this.attachInternals === 'function') {
      this._internals = this.attachInternals();
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    if (val) this.setAttributeSafe('name', val);
    else this.removeAttributeSafe('name');
  }

  get length() {
    const len = parseInt(this.getAttribute('length'), 10);
    return isNaN(len) || len <= 0 ? 6 : len;
  }

  set length(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('length', String(val));
    else this.removeAttributeSafe('length');
  }

  get value() {
    const slots = this._getSlots();
    return slots.map(s => s.value || '').join('');
  }

  set value(val) {
    const str = String(val || '');
    const slots = this._getSlots();
    slots.forEach((slot, idx) => {
      slot.value = str[idx] || '';
    });
    this._syncState();
  }

  get isComplete() {
    return this.value.length === this.length;
  }

  set isComplete(_) {}

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) {
      this.setAttributeSafe('disabled', '');
    } else {
      this.removeAttributeSafe('disabled');
    }
    this._syncState();
  }

  init() {
    this.setAttributeSafe('data-ui', 'otp-input');
    this.setAttributeSafe('role', 'group');
    this.setAttributeSafe('aria-label', this.getAttribute('aria-label') || 'One-Time Password Input');

    this._setupSlots();
    this._syncState();
    this._bindEvents();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue || !this._initialized) return;
    if (name === 'value') {
      this.value = newValue;
    } else if (name === 'disabled') {
      this._syncState();
    }
  }

  _getSlots() {
    return Array.from(this.querySelectorAll('[data-part="slot"], input[data-slot]'));
  }

  _setupSlots() {
    let slots = this._getSlots();

    // If slots are not authored in template, generate them
    if (slots.length === 0) {
      const container = this.querySelector('[data-part="container"]') || this;
      const count = this.length;
      for (let i = 0; i < count; i++) {
        const input = document.createElement('input');
        input.setAttribute('data-part', 'slot');
        input.setAttribute('data-index', String(i));
        input.type = this.getAttribute('type') === 'password' || this.hasAttribute('mask') ? 'password' : 'text';
        input.inputMode = this.getAttribute('type') === 'text' ? 'text' : 'numeric';
        input.pattern = '[0-9]*';
        input.maxLength = 1;
        input.autocomplete = i === 0 ? 'one-time-code' : 'off';
        input.className = 'ui-otp-slot';
        container.appendChild(input);
      }
      slots = this._getSlots();
    } else {
      slots.forEach((slot, i) => {
        slot.setAttribute('data-index', String(i));
        slot.maxLength = 1;
        if (!slot.inputMode) slot.inputMode = 'numeric';
        if (i === 0 && !slot.autocomplete) slot.autocomplete = 'one-time-code';
      });
    }

    // Populate initial value if attribute is set
    const initVal = this.getAttribute('value');
    if (initVal) {
      this.value = initVal;
    }
  }

  _syncState() {
    const slots = this._getSlots();
    const isDisabled = this.disabled;

    slots.forEach((slot) => {
      slot.disabled = isDisabled;
      this.setAttributeSafe(slot, 'data-filled', slot.value ? 'true' : 'false');
    });
  }

  _bindEvents() {
    const slots = this._getSlots();

    slots.forEach((slot, idx) => {
      this.listen(slot, 'input', (e) => {
        const val = slot.value;
        // If user typed more than 1 character into single slot (e.g. autofill)
        if (val.length > 1) {
          this._distributeValue(val, idx);
          return;
        }

        this.setAttributeSafe(slot, 'data-filled', val ? 'true' : 'false');

        if (val && idx < slots.length - 1) {
          slots[idx + 1].focus();
          slots[idx + 1].select();
        }

        this._emitChange();
      });

      this.listen(slot, 'keydown', (e) => {
        if (this.disabled) return;

        if (e.key === Keys.BACKSPACE) {
          if (!slot.value && idx > 0) {
            e.preventDefault();
            slots[idx - 1].value = '';
            this.setAttributeSafe(slots[idx - 1], 'data-filled', 'false');
            slots[idx - 1].focus();
            this._emitChange();
          } else {
            this.setAttributeSafe(slot, 'data-filled', 'false');
            setTimeout(() => this._emitChange(), 0);
          }
        } else if (e.key === Keys.ARROW_LEFT && idx > 0) {
          e.preventDefault();
          slots[idx - 1].focus();
          slots[idx - 1].select();
        } else if (e.key === Keys.ARROW_RIGHT && idx < slots.length - 1) {
          e.preventDefault();
          slots[idx + 1].focus();
          slots[idx + 1].select();
        }
      });

      this.listen(slot, 'paste', (e) => {
        e.preventDefault();
        const clipboard = e.clipboardData || window.clipboardData;
        if (!clipboard) return;

        const pastedData = clipboard.getData('text').trim();
        this._distributeValue(pastedData, idx);
      });

      this.listen(slot, 'focus', () => {
        slot.select();
      });
    });
  }

  _distributeValue(str, startIndex = 0) {
    const slots = this._getSlots();
    const chars = str.split('');
    let lastFilled = startIndex;

    chars.forEach((char, i) => {
      const targetSlot = slots[startIndex + i];
      if (targetSlot) {
        targetSlot.value = char;
        this.setAttributeSafe(targetSlot, 'data-filled', 'true');
        lastFilled = startIndex + i;
      }
    });

    const nextIndex = Math.min(lastFilled + 1, slots.length - 1);
    slots[nextIndex].focus();

    this._emitChange();
  }

  _updateFormValue() {
    if (this._internals) {
      this._internals.setFormValue(this.value);
    }
  }

  formResetCallback() {
    const initVal = this.getAttribute('value') || '';
    this.value = initVal;
  }

  _emitChange() {
    const val = this.value;
    const complete = this.isComplete;
    this._updateFormValue();

    this.dispatch('input', { value: val, isComplete: complete });
    if (complete) {
      this.dispatch('change', { value: val, isComplete: true });
    }
  }

  clear() {
    const slots = this._getSlots();
    slots.forEach((s) => {
      s.value = '';
      this.setAttributeSafe(s, 'data-filled', 'false');
    });
    if (slots.length > 0) slots[0].focus();
    this._emitChange();
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { attachPersistence } from '../../utils/persistence.js';

/**
 * <ui-stepper> Micro-Enhancer
 * Accessible multi-step workflow & progress wizard in Light-DOM.
 * 
 * Features:
 * - WAI-ARIA compliant step indicators (aria-current="step")
 * - Linear or non-linear workflow validation gating
 * - Synchronized panels with data-state="active|inactive"
 * - Programmatic API: next(), prev(), goToStep(n)
 * - Standard 'change' CustomEvent with { step, previousStep }
 * - Declarative Persistence: persist="url|session|local" [sync="cross-tab"]
 */
export class UiStepper extends BaseLightElement {
  static get observedAttributes() {
    return ['active-step', 'linear', 'orientation', 'persist', 'sync'];
  }

  get activeStep() {
    const val = parseInt(this.getAttribute('active-step'), 10);
    return isNaN(val) ? 1 : val;
  }

  set activeStep(val) {
    this.setAttributeSafe('active-step', String(val));
    this._syncState();
  }

  get linear() {
    return this.hasAttribute('linear') && this.getAttribute('linear') !== 'false';
  }

  set linear(val) {
    if (val) {
      this.setAttributeSafe('linear', '');
    } else {
      this.removeAttributeSafe('linear');
    }
  }

  get orientation() {
    return this.getAttribute('orientation') || 'horizontal';
  }

  set orientation(val) {
    if (val) this.setAttributeSafe('orientation', val);
    else this.removeAttributeSafe('orientation');
  }

  getAiState() {
    return {
      activeStep: this.activeStep,
      totalSteps: this._getSteps().length,
      linear: this.linear,
      orientation: this.orientation
    };
  }

  init() {
    this.setAttributeSafe('data-ui', 'stepper');
    this.setAttributeSafe('data-orientation', this.orientation);

    this._setupStructure();
    this._syncState();
    this._bindEvents();

    // Setup Declarative Persistence & Cross-Tab Sync
    if (this.hasAttribute('persist') || this.hasAttribute('sync')) {
      const cleanupPersistence = attachPersistence(this, {
        keys: ['step'],
        getState: () => ({
          step: this.activeStep
        }),
        setState: (state) => {
          if (state.step !== undefined) {
            this.activeStep = Number(state.step);
          }
        }
      });
      this._cleanups.push(cleanupPersistence);
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue || !this._initialized) return;
    if (name === 'active-step') {
      this._syncState();
    } else if (name === 'orientation') {
      this.setAttributeSafe('data-orientation', newValue);
    }
  }

  _getSteps() {
    return Array.from(this.querySelectorAll('[data-part="step"]'));
  }

  _getPanels() {
    return Array.from(this.querySelectorAll('[data-part="panel"]'));
  }

  _setupStructure() {
    const steps = this._getSteps();
    const steplist = this.querySelector('[data-part="steplist"]');
    if (steplist) {
      steplist.setAttribute('role', 'list');
    }

    steps.forEach((step, idx) => {
      const stepNum = parseInt(step.getAttribute('data-step'), 10) || (idx + 1);
      step.setAttribute('data-step', String(stepNum));

      const trigger = step.querySelector('[data-part="trigger"]') || step;
      if (trigger.tagName.toLowerCase() === 'button' || step === trigger) {
        if (!trigger.hasAttribute('type') && trigger.tagName.toLowerCase() === 'button') {
          trigger.setAttribute('type', 'button');
        }
      }
    });

    if (!this.getAttribute('active-step') && steps.length > 0) {
      this.setAttributeSafe('active-step', '1');
    }
  }

  _syncState() {
    const steps = this._getSteps();
    const panels = this._getPanels();
    const current = this.activeStep;
    const isLinear = this.linear;

    steps.forEach((step) => {
      const stepNum = parseInt(step.getAttribute('data-step'), 10);
      const isCurrent = stepNum === current;
      const isCompleted = stepNum < current;
      const isUpcoming = stepNum > current;

      let state = 'upcoming';
      if (isCurrent) state = 'current';
      else if (isCompleted) state = 'completed';

      this.setAttributeSafe(step, 'data-state', state);

      if (isCurrent) {
        this.setAttributeSafe(step, 'aria-current', 'step');
      } else {
        this.removeAttributeSafe(step, 'aria-current');
      }

      const indicator = step.querySelector('[data-part="indicator"]');
      if (indicator) {
        this.setAttributeSafe(indicator, 'data-state', state);
        if (isCompleted) {
          indicator.setAttribute('data-completed', 'true');
          if (!indicator.hasAttribute('data-step-num')) {
            indicator.setAttribute('data-step-num', indicator.textContent.trim() || String(stepNum));
          }
          indicator.textContent = '✓';
        } else {
          indicator.removeAttribute('data-completed');
          const original = indicator.getAttribute('data-step-num');
          if (original) {
            indicator.textContent = original;
          }
        }
      }

      const trigger = step.querySelector('[data-part="trigger"]') || step;
      if (isLinear && isUpcoming) {
        this.setAttributeSafe(trigger, 'disabled', '');
        this.setAttributeSafe(trigger, 'aria-disabled', 'true');
      } else {
        this.removeAttributeSafe(trigger, 'disabled');
        this.removeAttributeSafe(trigger, 'aria-disabled');
      }
    });

    panels.forEach((panel) => {
      const panelStep = parseInt(panel.getAttribute('data-step'), 10);
      const isActive = panelStep === current;

      this.setAttributeSafe(panel, 'data-state', isActive ? 'active' : 'inactive');
      if (isActive) {
        panel.removeAttribute('hidden');
        this.setAttributeSafe(panel, 'aria-hidden', 'false');
      } else {
        panel.setAttribute('hidden', '');
        this.setAttributeSafe(panel, 'aria-hidden', 'true');
      }
    });
  }

  _bindEvents() {
    this.listen(this, 'click', (e) => {
      const stepEl = e.target.closest('[data-part="step"]');
      if (!stepEl) return;

      const trigger = e.target.closest('[data-part="trigger"]') || stepEl;
      if (trigger.hasAttribute('disabled') || trigger.getAttribute('aria-disabled') === 'true') return;

      const targetStep = parseInt(stepEl.getAttribute('data-step'), 10);
      if (!isNaN(targetStep) && targetStep !== this.activeStep) {
        if (this.linear && targetStep > this.activeStep + 1) return;
        this.goToStep(targetStep);
      }
    });
  }

  goToStep(stepNum) {
    const totalSteps = this._getSteps().length;
    const clamped = Math.max(1, Math.min(stepNum, totalSteps || stepNum));
    const prev = this.activeStep;

    if (clamped !== prev) {
      this.activeStep = clamped;
      this._persistState?.();
      this.dispatch('change', { step: clamped, previousStep: prev });
    }
  }

  next() {
    this.goToStep(this.activeStep + 1);
  }

  prev() {
    this.goToStep(this.activeStep - 1);
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys } from '../../utils/a11y.js';

/**
 * <ui-resizable> Micro-Enhancer
 * Accessible resizable panel layout in Light-DOM.
 * 
 * Features:
 * - Horizontal and vertical split orientations
 * - Mouse & touch dragging with pointer capture
 * - Full WAI-ARIA separator pattern (role="separator", aria-valuenow, Arrow keys)
 * - Min/max panel size constraints
 * - Dispatches 'resize' CustomEvent with { sizes: [number, number] }
 */
export class UiResizable extends BaseLightElement {
  static get observedAttributes() {
    return ['orientation', 'disabled'];
  }

  get orientation() {
    return this.getAttribute('orientation') || 'horizontal';
  }

  set orientation(val) {
    this.setAttributeSafe('orientation', val);
    this._syncOrientation();
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) {
      this.setAttributeSafe('disabled', '');
    } else {
      this.removeAttributeSafe('disabled');
    }
  }

  init() {
    this.setAttributeSafe('data-ui', 'resizable');
    this._syncOrientation();

    this._panels = Array.from(this.querySelectorAll('[data-part="panel"]'));
    this._handles = Array.from(this.querySelectorAll('[data-part="handle"], [role="separator"]'));

    this._initPanels();
    this._bindEvents();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue || !this._initialized) return;
    if (name === 'orientation') {
      this._syncOrientation();
    }
  }

  _syncOrientation() {
    this.setAttributeSafe('data-orientation', this.orientation);
    const isVert = this.orientation === 'vertical';
    this.style.display = 'flex';
    this.style.flexDirection = isVert ? 'column' : 'row';
    this.style.width = '100%';
    this.style.height = isVert ? '100%' : 'auto';
  }

  _initPanels() {
    if (this._panels.length < 2) return;

    // Read default sizes or divide evenly
    let total = 0;
    const sizes = this._panels.map((p) => {
      const s = parseFloat(p.getAttribute('data-size') || p.getAttribute('data-default-size'));
      return isNaN(s) ? 0 : s;
    });

    total = sizes.reduce((a, b) => a + b, 0);

    if (total === 0) {
      const even = 100 / this._panels.length;
      this._sizes = this._panels.map(() => even);
    } else {
      this._sizes = sizes.map(s => (s / total) * 100);
    }

    this._applySizes();

    this._handles.forEach((handle, idx) => {
      handle.setAttribute('role', 'separator');
      handle.setAttribute('tabindex', this.disabled ? '-1' : '0');
      handle.setAttribute('aria-orientation', this.orientation);
      handle.setAttribute('aria-valuenow', Math.round(this._sizes[idx] || 50));
      handle.setAttribute('aria-valuemin', '10');
      handle.setAttribute('aria-valuemax', '90');
    });
  }

  _applySizes() {
    this._panels.forEach((p, idx) => {
      const sz = this._sizes[idx] || 50;
      p.style.flex = `${sz} 1 0px`;
      p.setAttribute('data-size', sz.toFixed(2));
    });
  }

  _bindEvents() {
    this._handles.forEach((handle, handleIndex) => {
      let isDragging = false;
      let startPos = 0;
      let startSizes = [];

      const onPointerDown = (e) => {
        if (this.disabled || e.button !== 0) return;
        e.preventDefault();

        isDragging = true;
        handle.setPointerCapture?.(e.pointerId);
        handle.setAttribute('data-dragging', 'true');
        document.body.style.userSelect = 'none';

        startPos = this.orientation === 'vertical' ? e.clientY : e.clientX;
        startSizes = [...this._sizes];

        const onPointerMove = (moveEvt) => {
          if (!isDragging) return;
          const currentPos = this.orientation === 'vertical' ? moveEvt.clientY : moveEvt.clientX;
          const deltaPx = currentPos - startPos;

          const rect = this.getBoundingClientRect();
          const totalDimension = this.orientation === 'vertical' ? rect.height : rect.width;
          if (totalDimension <= 0) return;

          const deltaPercent = (deltaPx / totalDimension) * 100;
          this._adjustSizes(handleIndex, deltaPercent, startSizes);
        };

        const onPointerUp = (upEvt) => {
          if (!isDragging) return;
          isDragging = false;
          handle.releasePointerCapture?.(upEvt.pointerId);
          handle.removeAttribute('data-dragging');
          document.body.style.userSelect = '';

          window.removeEventListener('pointermove', onPointerMove);
          window.removeEventListener('pointerup', onPointerUp);
          window.removeEventListener('pointercancel', onPointerUp);
        };

        window.addEventListener('pointermove', onPointerMove);
        window.addEventListener('pointerup', onPointerUp);
        window.addEventListener('pointercancel', onPointerUp);
      };

      this.listen(handle, 'pointerdown', onPointerDown);

      // Keyboard navigation
      this.listen(handle, 'keydown', (e) => {
        if (this.disabled) return;
        const step = e.shiftKey ? 5 : 1;
        let delta = 0;

        if (this.orientation === 'horizontal') {
          if (e.key === Keys.ARROW_LEFT) delta = -step;
          else if (e.key === Keys.ARROW_RIGHT) delta = step;
        } else {
          if (e.key === Keys.ARROW_UP) delta = -step;
          else if (e.key === Keys.ARROW_DOWN) delta = step;
        }

        if (delta !== 0) {
          e.preventDefault();
          this._adjustSizes(handleIndex, delta, this._sizes);
        }
      });
    });
  }

  _adjustSizes(handleIndex, deltaPercent, baseSizes) {
    if (!baseSizes || baseSizes.length < 2) return;

    const leftIdx = handleIndex;
    const rightIdx = handleIndex + 1;

    if (rightIdx >= baseSizes.length) return;

    const minSize = 10;
    const maxSize = 90;

    let newLeft = baseSizes[leftIdx] + deltaPercent;
    let newRight = baseSizes[rightIdx] - deltaPercent;

    if (newLeft < minSize) {
      newRight -= (minSize - newLeft);
      newLeft = minSize;
    } else if (newLeft > maxSize) {
      newRight += (newLeft - maxSize);
      newLeft = maxSize;
    }

    if (newRight < minSize) {
      newLeft -= (minSize - newRight);
      newRight = minSize;
    }

    this._sizes[leftIdx] = newLeft;
    this._sizes[rightIdx] = newRight;

    this._applySizes();

    const handle = this._handles[handleIndex];
    if (handle) {
      handle.setAttribute('aria-valuenow', Math.round(newLeft));
    }

    this.dispatch('resize', { sizes: [...this._sizes] });
  }

  getSizes() {
    return [...(this._sizes || [])];
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * <ui-file-upload> Micro-Enhancer
 * Accessible drag-and-drop file upload manager in Light-DOM.
 * 
 * Features:
 * - HTML5 drag-and-drop with data-dragging="true" visual feedback
 * - File size and MIME type acceptance validation
 * - Clipboard image/document paste support
 * - Native hidden <input type="file"> integration
 * - 'change' CustomEvent with { files, rejectedFiles }
 */
export class UiFileUpload extends BaseLightElement {
  static get observedAttributes() {
    return ['accept', 'multiple', 'max-size', 'disabled'];
  }

  constructor() {
    super();
    this._files = [];
  }

  get files() {
    return [...this._files];
  }

  set files(val) {
    if (Array.isArray(val)) {
      this._files = [...val];
      this._renderFileList();
    }
  }

  get accept() {
    return this.getAttribute('accept') || '';
  }

  set accept(val) {
    if (val) this.setAttributeSafe('accept', val);
    else this.removeAttributeSafe('accept');
  }

  get multiple() {
    return this.hasAttribute('multiple');
  }

  set multiple(val) {
    if (val) this.setAttributeSafe('multiple', '');
    else this.removeAttributeSafe('multiple');
  }

  get maxSize() {
    const val = parseInt(this.getAttribute('max-size'), 10);
    return isNaN(val) ? Infinity : val;
  }

  set maxSize(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('max-size', String(val));
    else this.removeAttributeSafe('max-size');
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) {
      this.setAttributeSafe('disabled', '');
    } else {
      this.removeAttributeSafe('disabled');
    }
  }

  init() {
    this.setAttributeSafe('data-ui', 'file-upload');

    this._setupNativeInput();
    this._bindEvents();
  }

  _setupNativeInput() {
    let input = this.querySelector('input[type="file"]');
    if (!input) {
      input = document.createElement('input');
      input.type = 'file';
      input.setAttribute('data-part', 'native-input');
      input.style.display = 'none';
      this.appendChild(input);
    }

    if (this.accept) input.accept = this.accept;
    if (this.multiple) input.multiple = true;
    if (this.disabled) input.disabled = true;

    this._nativeInput = input;
  }

  _bindEvents() {
    const dropzone = this.querySelector('[data-part="dropzone"]') || this;
    const trigger = this.querySelector('[data-part="trigger"]') || dropzone;

    // Trigger click opens file browser dialog
    this.listen(trigger, 'click', (e) => {
      if (this.disabled) return;
      if (e.target !== this._nativeInput && !e.target.closest('[data-part="remove-file"]')) {
        this._nativeInput?.click();
      }
    });

    // Native file input change
    if (this._nativeInput) {
      this.listen(this._nativeInput, 'change', () => {
        if (this._nativeInput.files && this._nativeInput.files.length > 0) {
          this._handleSelectedFiles(Array.from(this._nativeInput.files));
        }
      });
    }

    // Drag and Drop
    let dragCounter = 0;

    this.listen(dropzone, 'dragenter', (e) => {
      if (this.disabled) return;
      e.preventDefault();
      e.stopPropagation();
      dragCounter++;
      this.setAttributeSafe(dropzone, 'data-dragging', 'true');
    });

    this.listen(dropzone, 'dragover', (e) => {
      if (this.disabled) return;
      e.preventDefault();
      e.stopPropagation();
    });

    this.listen(dropzone, 'dragleave', (e) => {
      if (this.disabled) return;
      e.preventDefault();
      e.stopPropagation();
      dragCounter--;
      if (dragCounter <= 0) {
        dragCounter = 0;
        this.removeAttributeSafe(dropzone, 'data-dragging');
      }
    });

    this.listen(dropzone, 'drop', (e) => {
      if (this.disabled) return;
      e.preventDefault();
      e.stopPropagation();
      dragCounter = 0;
      this.removeAttributeSafe(dropzone, 'data-dragging');

      if (e.dataTransfer && e.dataTransfer.files.length > 0) {
        this._handleSelectedFiles(Array.from(e.dataTransfer.files));
      }
    });

    // Paste file from clipboard
    this.listen(this, 'paste', (e) => {
      if (this.disabled) return;
      const items = e.clipboardData?.items;
      if (!items) return;

      const pastedFiles = [];
      for (let i = 0; i < items.length; i++) {
        if (items[i].kind === 'file') {
          const file = items[i].getAsFile();
          if (file) pastedFiles.push(file);
        }
      }

      if (pastedFiles.length > 0) {
        e.preventDefault();
        this._handleSelectedFiles(pastedFiles);
      }
    });

    // Remove file listener
    this.listen(this, 'click', (e) => {
      const removeBtn = e.target.closest('[data-part="remove-file"]');
      if (!removeBtn) return;
      e.stopPropagation();

      const itemEl = removeBtn.closest('[data-part="file-item"]');
      const filename = itemEl?.getAttribute('data-filename');
      if (filename) {
        this.removeFile(filename);
      }
    });
  }

  _handleSelectedFiles(newFiles) {
    const accepted = [];
    const rejected = [];
    const max = this.maxSize;
    const acceptTypes = this.accept ? this.accept.split(',').map(s => s.trim().toLowerCase()) : [];

    newFiles.forEach((file) => {
      // Validate size
      if (file.size > max) {
        rejected.push({ file, reason: 'size' });
        return;
      }

      // Validate MIME type / extension
      if (acceptTypes.length > 0) {
        const ext = `.${file.name.split('.').pop().toLowerCase()}`;
        const match = acceptTypes.some((type) => {
          if (type.startsWith('.')) return ext === type;
          if (type.endsWith('/*')) {
            const prefix = type.replace('/*', '');
            return file.type.startsWith(prefix);
          }
          return file.type === type;
        });

        if (!match) {
          rejected.push({ file, reason: 'type' });
          return;
        }
      }

      accepted.push(file);
    });

    if (this.multiple) {
      this._files = [...this._files, ...accepted];
    } else {
      this._files = accepted.slice(0, 1);
    }

    this._renderFileList();
    this.dispatch('change', { files: [...this._files], rejectedFiles: rejected });
  }

  _renderFileList() {
    const list = this.querySelector('[data-part="file-list"]');
    if (!list) return;

    list.innerHTML = '';
    this._files.forEach((file) => {
      const li = document.createElement('li');
      li.setAttribute('data-part', 'file-item');
      li.setAttribute('data-filename', file.name);
      li.className = 'ui-file-item';

      const info = document.createElement('div');
      info.className = 'ui-file-info';

      const nameSpan = document.createElement('span');
      nameSpan.className = 'ui-file-name';
      nameSpan.textContent = file.name;

      const sizeSpan = document.createElement('span');
      sizeSpan.className = 'ui-file-size';
      sizeSpan.textContent = this._formatBytes(file.size);

      info.appendChild(nameSpan);
      info.appendChild(sizeSpan);

      const delBtn = document.createElement('button');
      delBtn.type = 'button';
      delBtn.setAttribute('data-part', 'remove-file');
      delBtn.className = 'ui-file-remove';
      delBtn.setAttribute('aria-label', `Remove ${file.name}`);
      delBtn.textContent = '✕';

      li.appendChild(info);
      li.appendChild(delBtn);
      list.appendChild(li);
    });
  }

  _formatBytes(bytes) {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${(bytes / Math.pow(k, i)).toFixed(1)} ${sizes[i]}`;
  }

  removeFile(name) {
    this._files = this._files.filter(f => f.name !== name);
    this._renderFileList();
    this.dispatch('change', { files: [...this._files] });
  }

  clear() {
    this._files = [];
    if (this._nativeInput) this._nativeInput.value = '';
    this._renderFileList();
    this.dispatch('change', { files: [] });
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys } from '../../utils/a11y.js';

/**
 * <ui-context-menu> Micro-Enhancer
 * Accessible right-click context menu in Light-DOM.
 * 
 * Features:
 * - Native pointer coordinates positioning with boundary collision prevention
 * - Top-layer Popover API support with seamless fallback
 * - Keyboard navigation (ArrowUp, ArrowDown, Enter, Esc)
 * - Auto-dismiss on click outside or item activation
 * - Dispatches 'open', 'close', and 'select' CustomEvents
 */
export class UiContextMenu extends BaseLightElement {
  static get observedAttributes() {
    return ['disabled'];
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) {
      this.setAttributeSafe('disabled', '');
    } else {
      this.removeAttributeSafe('disabled');
    }
  }

  get isOpen() {
    const menu = this.querySelector('[data-part="menu"]');
    if (!menu) return false;
    return menu.matches?.(':popover-open') || menu.getAttribute('data-state') === 'open';
  }

  set isOpen(val) {
    if (val) this.open();
    else this.close();
  }

  init() {
    this.setAttributeSafe('data-ui', 'context-menu');

    this._menu = this.querySelector('[data-part="menu"]');
    this._area = this.querySelector('[data-part="area"]') || this;

    if (this._menu) {
      if (!this._menu.hasAttribute('popover')) {
        this._menu.setAttribute('popover', 'auto');
      }
      this._menu.setAttribute('role', 'menu');
      this.setAttributeSafe(this._menu, 'data-state', 'closed');
    }

    this._bindEvents();
  }

  _getItems() {
    if (!this._menu) return [];
    return Array.from(this._menu.querySelectorAll('[data-part="item"], [role="menuitem"], button'));
  }

  _bindEvents() {
    if (!this._area || !this._menu) return;

    this.listen(this._area, 'contextmenu', (e) => {
      if (this.disabled) return;
      e.preventDefault();
      this.openAt(e.clientX, e.clientY);
    });

    // Close when clicking item
    this.listen(this._menu, 'click', (e) => {
      const item = e.target.closest('[data-part="item"], [role="menuitem"]');
      if (item && !item.hasAttribute('disabled')) {
        const value = item.getAttribute('data-value') || item.textContent.trim();
        this.dispatch('select', { value, item });
        this.close();
      }
    });

    // Keyboard navigation
    this.listen(this._menu, 'keydown', (e) => {
      const items = this._getItems().filter(it => !it.hasAttribute('disabled'));
      if (items.length === 0) return;

      const currentIdx = items.indexOf(document.activeElement);

      if (e.key === Keys.ARROW_DOWN) {
        e.preventDefault();
        const next = currentIdx < items.length - 1 ? currentIdx + 1 : 0;
        items[next].focus();
      } else if (e.key === Keys.ARROW_UP) {
        e.preventDefault();
        const prev = currentIdx > 0 ? currentIdx - 1 : items.length - 1;
        items[prev].focus();
      } else if (e.key === Keys.ESCAPE) {
        e.preventDefault();
        this.close();
      }
    });

    // Sync state when native popover toggles
    this.listen(this._menu, 'toggle', (e) => {
      const isOpen = e.newState === 'open';
      this.setAttributeSafe(this._menu, 'data-state', isOpen ? 'open' : 'closed');
      if (isOpen) {
        this.dispatch('open');
      } else {
        this.dispatch('close');
      }
    });

    // Global click-outside fallback when popover API is not native
    this.listen(document, 'pointerdown', (e) => {
      if (!this.isOpen) return;
      if (!this._menu.contains(e.target)) {
        this.close();
      }
    });
  }

  openAt(clientX, clientY) {
    if (!this._menu) return;

    // Reset styles to calculate natural dimensions
    this._menu.style.position = 'fixed';
    this._menu.style.margin = '0';
    this._menu.style.inset = 'unset';
    this._menu.style.zIndex = '9999';

    // Show menu first so dimensions can be measured
    if (typeof this._menu.showPopover === 'function') {
      try {
        this._menu.showPopover();
      } catch (err) {
        // Fallback
        this._menu.setAttribute('data-state', 'open');
        this._menu.style.display = 'block';
      }
    } else {
      this._menu.setAttribute('data-state', 'open');
      this._menu.style.display = 'block';
    }

    this.setAttributeSafe(this._menu, 'data-state', 'open');

    // Calculate boundary collisions
    const menuWidth = this._menu.offsetWidth || 180;
    const menuHeight = this._menu.offsetHeight || 150;
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let posX = clientX;
    let posY = clientY;

    if (posX + menuWidth > viewportWidth) {
      posX = Math.max(10, clientX - menuWidth);
    }
    if (posY + menuHeight > viewportHeight) {
      posY = Math.max(10, clientY - menuHeight);
    }

    this._menu.style.left = `${posX}px`;
    this._menu.style.top = `${posY}px`;

    // Focus first available item
    const items = this._getItems().filter(it => !it.hasAttribute('disabled'));
    if (items.length > 0) {
      setTimeout(() => items[0].focus(), 10);
    }

    this.dispatch('open', { x: posX, y: posY });
  }

  close() {
    if (!this._menu) return;

    if (typeof this._menu.hidePopover === 'function') {
      try {
        this._menu.hidePopover();
      } catch (err) {
        // Fallback
        this._menu.removeAttribute('data-state');
        this._menu.style.display = 'none';
      }
    } else {
      this._menu.removeAttribute('data-state');
      this._menu.style.display = 'none';
    }

    this.setAttributeSafe(this._menu, 'data-state', 'closed');
    this.dispatch('close');
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys, getNextIndex } from '../../utils/a11y.js';

/**
 * <ui-navigation-menu> Micro-Enhancer
 * Accessible top-level application navigation and mega-menu in Light-DOM.
 * 
 * Features:
 * - WAI-ARIA APG Menubar pattern (role="menubar", role="menuitem")
 * - Roving tabindex across top items with ArrowLeft / ArrowRight
 * - ArrowDown to enter submenus, Escape to close
 * - Hover intent timer to prevent flicker
 * - Top-layer Popover API submenu positioning
 */
export class UiNavigationMenu extends BaseLightElement {
  static get observedAttributes() {
    return ['delay', 'disabled'];
  }

  get delay() {
    const d = parseInt(this.getAttribute('delay'), 10);
    return isNaN(d) ? 150 : d;
  }

  set delay(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('delay', String(val));
    else this.removeAttributeSafe('delay');
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) this.setAttributeSafe('disabled', '');
    else this.removeAttributeSafe('disabled');
  }

  init() {
    if (this._initialized) return;
    this.setAttributeSafe('data-ui', 'navigation-menu');

    this._nav = this.querySelector('[data-part="menubar"], [data-part="list"], nav') || this;
    this.setAttributeSafe(this._nav, 'role', 'menubar');

    this._activeItem = null;
    this._hoverTimeout = null;

    this._setupStructure();
    this._bindEvents();
  }

  _getItems() {
    return Array.from(this.querySelectorAll('[data-part="item"]'));
  }

  _getTriggers() {
    return Array.from(this.querySelectorAll('[data-part="trigger"]'));
  }

  _setupStructure() {
    const items = this._getItems();
    const triggers = this._getTriggers();

    triggers.forEach((trigger, idx) => {
      trigger.setAttribute('role', 'menuitem');
      trigger.setAttribute('tabindex', idx === 0 ? '0' : '-1');
      trigger.setAttribute('aria-haspopup', 'true');
      trigger.setAttribute('aria-expanded', 'false');

      const content = trigger.closest('[data-part="item"]')?.querySelector('[data-part="content"]');
      if (content) {
        content.setAttribute('role', 'menu');
        content.removeAttribute('popover');
        content.setAttribute('data-state', 'closed');
      }
    });
  }

  _bindEvents() {
    const items = this._getItems();

    items.forEach((item) => {
      const trigger = item.querySelector('[data-part="trigger"]');
      const content = item.querySelector('[data-part="content"]');
      if (!trigger || !content) return;

      // Click toggle
      this.listen(trigger, 'click', (e) => {
        if (this.disabled) return;
        e.preventDefault();
        const isOpen = trigger.getAttribute('aria-expanded') === 'true';
        if (isOpen) {
          this.closeItem(item);
        } else {
          this.openItem(item);
        }
      });

      // Hover with delay
      this.listen(item, 'mouseenter', () => {
        if (this.disabled) return;
        clearTimeout(this._hoverTimeout);
        this._hoverTimeout = setTimeout(() => {
          this.openItem(item);
        }, this.delay);
      });

      this.listen(item, 'mouseleave', () => {
        if (this.disabled) return;
        clearTimeout(this._hoverTimeout);
        this._hoverTimeout = setTimeout(() => {
          this.closeItem(item);
        }, this.delay + 50);
      });
    });

    // Keyboard roving focus across triggers
    this.listen(this, 'keydown', (e) => {
      if (this.disabled) return;
      const triggers = this._getTriggers();
      const currentIdx = triggers.indexOf(document.activeElement);

      if (currentIdx !== -1) {
        if (e.key === Keys.ARROW_RIGHT) {
          e.preventDefault();
          const nextIdx = getNextIndex(currentIdx, triggers.length, 1, true);
          triggers[nextIdx].focus();
        } else if (e.key === Keys.ARROW_LEFT) {
          e.preventDefault();
          const prevIdx = getNextIndex(currentIdx, triggers.length, -1, true);
          triggers[prevIdx].focus();
        } else if (e.key === Keys.ARROW_DOWN) {
          e.preventDefault();
          const item = triggers[currentIdx].closest('[data-part="item"]');
          this.openItem(item);
          const firstSubLink = item.querySelector('[data-part="content"] a, [data-part="content"] button');
          firstSubLink?.focus();
        }
      } else if (e.key === Keys.ESCAPE) {
        if (this._activeItem) {
          e.preventDefault();
          const trigger = this._activeItem.querySelector('[data-part="trigger"]');
          this.closeItem(this._activeItem);
          trigger?.focus();
        }
      }
    });

    // Document click to close
    this.listen(document, 'pointerdown', (e) => {
      if (!this.contains(e.target)) {
        this.closeAll();
      }
    });
  }

  openItem(item) {
    if (!item) return;
    this.closeAll();

    const trigger = item.querySelector('[data-part="trigger"]');
    const content = item.querySelector('[data-part="content"]');
    if (!trigger || !content) return;

    trigger.setAttribute('aria-expanded', 'true');
    content.setAttribute('data-state', 'open');

    this._activeItem = item;
    this.dispatch('open', { item });
  }

  closeItem(item) {
    if (!item) return;

    const trigger = item.querySelector('[data-part="trigger"]');
    const content = item.querySelector('[data-part="content"]');
    if (!trigger || !content) return;

    trigger.setAttribute('aria-expanded', 'false');
    content.setAttribute('data-state', 'closed');

    if (this._activeItem === item) {
      this._activeItem = null;
    }

    this.dispatch('close', { item });
  }

  closeAll() {
    this._getItems().forEach(it => this.closeItem(it));
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys } from '../../utils/a11y.js';

/**
 * <ui-tree-view> Micro-Enhancer
 * Accessible hierarchical treeview & folder explorer in Light-DOM.
 * 
 * Features:
 * - WAI-ARIA APG Treeview pattern (role="tree", role="treeitem", role="group")
 * - 4-directional keyboard navigation (Up, Down, Left, Right, Home, End)
 * - Single or multi-selection support
 * - Dynamic expand/collapse states (aria-expanded="true|false")
 * - Dispatches 'select' and 'toggle' CustomEvents
 */
export class UiTreeView extends BaseLightElement {
  static get observedAttributes() {
    return ['selection-mode', 'disabled'];
  }

  get selectionMode() {
    return this.getAttribute('selection-mode') || 'single';
  }

  set selectionMode(val) {
    if (val) this.setAttributeSafe('selection-mode', val);
    else this.removeAttributeSafe('selection-mode');
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) this.setAttributeSafe('disabled', '');
    else this.removeAttributeSafe('disabled');
  }

  init() {
    this.setAttributeSafe('data-ui', 'tree-view');

    const tree = this.querySelector('[data-part="tree"], ul, ol') || this;
    this.setAttributeSafe(tree, 'role', 'tree');

    this._setupStructure();
    this._bindEvents();
  }

  _getItems() {
    return Array.from(this.querySelectorAll('[data-part="item"], [role="treeitem"]'));
  }

  _getVisibleItems() {
    return this._getItems().filter((item) => {
      let parent = item.parentElement?.closest('[data-part="item"], [role="treeitem"]');
      while (parent) {
        if (parent.getAttribute('aria-expanded') === 'false') {
          return false;
        }
        parent = parent.parentElement?.closest('[data-part="item"], [role="treeitem"]');
      }
      return true;
    });
  }

  _setupStructure() {
    const items = this._getItems();

    items.forEach((item, idx) => {
      item.setAttribute('role', 'treeitem');
      item.setAttribute('tabindex', idx === 0 ? '0' : '-1');

      const group = item.querySelector(':scope > [data-part="group"], :scope > ul, :scope > ol');
      if (group) {
        group.setAttribute('role', 'group');
        if (!item.hasAttribute('aria-expanded')) {
          item.setAttribute('aria-expanded', 'false');
        }
        item.setAttribute('data-state', item.getAttribute('aria-expanded') === 'true' ? 'expanded' : 'collapsed');
      }
    });
  }

  _bindEvents() {
    // Click toggle or selection
    this.listen(this, 'click', (e) => {
      if (this.disabled) return;
      const item = e.target.closest('[data-part="item"], [role="treeitem"]');
      if (!item) return;

      const toggle = e.target.closest('[data-part="toggle"]');
      const hasChildren = item.querySelector(':scope > [data-part="group"], :scope > ul, :scope > ol');

      if (toggle || (hasChildren && e.target === item)) {
        this.toggleItem(item);
      } else {
        this.selectItem(item);
      }
    });

    // Keyboard navigation
    this.listen(this, 'keydown', (e) => {
      if (this.disabled) return;
      const visibleItems = this._getVisibleItems();
      const currentItem = document.activeElement?.closest('[data-part="item"], [role="treeitem"]');
      if (!currentItem) return;

      const currentIdx = visibleItems.indexOf(currentItem);

      switch (e.key) {
        case Keys.ARROW_DOWN: {
          e.preventDefault();
          if (currentIdx < visibleItems.length - 1) {
            this._focusItem(visibleItems[currentIdx + 1]);
          }
          break;
        }
        case Keys.ARROW_UP: {
          e.preventDefault();
          if (currentIdx > 0) {
            this._focusItem(visibleItems[currentIdx - 1]);
          }
          break;
        }
        case Keys.ARROW_RIGHT: {
          e.preventDefault();
          const hasChildren = currentItem.querySelector(':scope > [data-part="group"], :scope > ul, :scope > ol');
          if (hasChildren) {
            if (currentItem.getAttribute('aria-expanded') === 'false') {
              this.expandItem(currentItem);
            } else {
              // Move to first child
              const firstChild = currentItem.querySelector(':scope > [data-part="group"] > [data-part="item"], :scope > ul > [role="treeitem"]');
              if (firstChild) this._focusItem(firstChild);
            }
          }
          break;
        }
        case Keys.ARROW_LEFT: {
          e.preventDefault();
          const hasChildren = currentItem.querySelector(':scope > [data-part="group"], :scope > ul, :scope > ol');
          if (hasChildren && currentItem.getAttribute('aria-expanded') === 'true') {
            this.collapseItem(currentItem);
          } else {
            // Move to parent
            const parentItem = currentItem.parentElement?.closest('[data-part="item"], [role="treeitem"]');
            if (parentItem) this._focusItem(parentItem);
          }
          break;
        }
        case Keys.HOME: {
          e.preventDefault();
          if (visibleItems.length > 0) this._focusItem(visibleItems[0]);
          break;
        }
        case Keys.END: {
          e.preventDefault();
          if (visibleItems.length > 0) this._focusItem(visibleItems[visibleItems.length - 1]);
          break;
        }
        case Keys.ENTER:
        case Keys.SPACE: {
          e.preventDefault();
          const hasChildren = currentItem.querySelector(':scope > [data-part="group"], :scope > ul, :scope > ol');
          if (hasChildren) {
            this.toggleItem(currentItem);
          } else {
            this.selectItem(currentItem);
          }
          break;
        }
      }
    });
  }

  _focusItem(item) {
    this._getItems().forEach(it => it.setAttribute('tabindex', '-1'));
    item.setAttribute('tabindex', '0');
    item.focus();
  }

  toggleItem(item) {
    const isExpanded = item.getAttribute('aria-expanded') === 'true';
    if (isExpanded) {
      this.collapseItem(item);
    } else {
      this.expandItem(item);
    }
  }

  expandItem(item) {
    item.setAttribute('aria-expanded', 'true');
    item.setAttribute('data-state', 'expanded');
    const group = item.querySelector(':scope > [data-part="group"], :scope > ul, :scope > ol');
    if (group) group.style.display = 'block';
    this.dispatch('toggle', { item, expanded: true });
  }

  collapseItem(item) {
    item.setAttribute('aria-expanded', 'false');
    item.setAttribute('data-state', 'collapsed');
    const group = item.querySelector(':scope > [data-part="group"], :scope > ul, :scope > ol');
    if (group) group.style.display = 'none';
    this.dispatch('toggle', { item, expanded: false });
  }

  selectItem(item) {
    const isSelected = item.getAttribute('aria-selected') === 'true';
    if (this.selectionMode === 'single') {
      this._getItems().forEach(it => {
        it.removeAttribute('aria-selected');
        it.removeAttribute('data-selected');
      });
      item.setAttribute('aria-selected', 'true');
      item.setAttribute('data-selected', 'true');
    } else {
      item.setAttribute('aria-selected', isSelected ? 'false' : 'true');
      item.setAttribute('data-selected', isSelected ? 'false' : 'true');
    }

    const value = item.getAttribute('data-value') || item.textContent.trim();
    this.dispatch('select', { item, value, selected: !isSelected });
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { attachPersistence } from '../../utils/persistence.js';

/**
 * <ui-ai-prompt-box> Micro-Enhancer
 * Accessible AI Copilot prompt box with auto-expanding textarea in Light-DOM.
 * 
 * Features:
 * - Zero-flicker auto-resizing textarea up to max-rows
 * - Enter to submit, Shift+Enter for new line
 * - Dynamic loading/generating state (submit button switches to stop button)
 * - Action toolbar with file attach and speech hooks
 * - Dispatches 'submit', 'stop', and 'input' CustomEvents
 * - Declarative Draft Persistence: persist="local|session" [sync="cross-tab"]
 */
export class UiAiPromptBox extends BaseLightElement {
  static get observedAttributes() {
    return ['max-rows', 'loading', 'disabled', 'placeholder', 'persist', 'sync'];
  }

  get maxRows() {
    const r = parseInt(this.getAttribute('max-rows'), 10);
    return isNaN(r) ? 6 : r;
  }

  set maxRows(val) {
    if (val !== null && val !== undefined) {
      this.setAttributeSafe('max-rows', String(val));
    } else {
      this.removeAttributeSafe('max-rows');
    }
  }

  get loading() {
    return this.hasAttribute('loading') && this.getAttribute('loading') !== 'false';
  }

  set loading(val) {
    if (val) {
      this.setAttributeSafe('loading', '');
    } else {
      this.removeAttributeSafe('loading');
    }
    this._syncState();
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) {
      this.setAttributeSafe('disabled', '');
    } else {
      this.removeAttributeSafe('disabled');
    }
    this._syncState();
  }

  get value() {
    return this._textarea?.value || '';
  }

  set value(val) {
    if (this._textarea) {
      this._textarea.value = val;
      this._autoResize();
    }
  }

  getAiState() {
    return {
      value: this.value,
      loading: this.loading,
      disabled: this.disabled,
      maxRows: this.maxRows
    };
  }

  init() {
    this.setAttributeSafe('data-ui', 'ai-prompt-box');

    this._textarea = this.querySelector('textarea, [data-part="input"]');
    if (!this._textarea) {
      this._textarea = document.createElement('textarea');
      this._textarea.setAttribute('data-part', 'input');
      this._textarea.placeholder = this.getAttribute('placeholder') || 'Ask AI anything... (Shift+Enter for newline)';
      this.prepend(this._textarea);
    }

    this._textarea.rows = 1;
    this._textarea.style.resize = 'none';
    this._textarea.style.overflowY = 'hidden';

    this._syncState();
    this._bindEvents();
    this._autoResize();

    // Setup Declarative Draft Persistence & Cross-Tab Sync
    if (this.hasAttribute('persist') || this.hasAttribute('sync')) {
      const cleanupPersistence = attachPersistence(this, {
        keys: ['draft'],
        getState: () => ({
          draft: this.value
        }),
        setState: (state) => {
          if (state.draft !== undefined && state.draft !== this.value) {
            this.value = state.draft;
            this._autoResize();
            this._syncState();
          }
        }
      });
      this._cleanups.push(cleanupPersistence);
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue || !this._initialized) return;
    if (name === 'loading' || name === 'disabled') {
      this._syncState();
    }
  }

  _syncState() {
    const isLoading = this.loading;
    const isDisabled = this.disabled;

    if (this._textarea) {
      this._textarea.disabled = isDisabled;
    }

    const submitBtn = this.querySelector('[data-part="submit-btn"]');
    const stopBtn = this.querySelector('[data-part="stop-btn"]');

    if (submitBtn) {
      submitBtn.style.display = isLoading ? 'none' : 'inline-flex';
      submitBtn.disabled = isDisabled || !this.value.trim();
    }

    if (stopBtn) {
      stopBtn.style.display = isLoading ? 'inline-flex' : 'none';
      stopBtn.disabled = isDisabled;
    }
  }

  _autoResize() {
    if (!this._textarea) return;

    this._textarea.style.height = 'auto';
    const computed = window.getComputedStyle ? window.getComputedStyle(this._textarea) : null;
    let lineHeight = 20;
    if (computed) {
      const parsedLH = parseFloat(computed.lineHeight);
      if (!isNaN(parsedLH) && parsedLH > 0) {
        lineHeight = parsedLH;
      } else {
        const fontSize = parseFloat(computed.fontSize) || 15;
        lineHeight = Math.round(fontSize * 1.35);
      }
    }
    const maxHeight = lineHeight * this.maxRows;

    if (this._textarea.scrollHeight > maxHeight) {
      this._textarea.style.height = `${maxHeight}px`;
      this._textarea.style.overflowY = 'auto';
    } else {
      this._textarea.style.height = `${Math.max(this._textarea.scrollHeight, lineHeight)}px`;
      this._textarea.style.overflowY = 'hidden';
    }
  }

  _bindEvents() {
    if (!this._textarea) return;

    this.listen(this._textarea, 'input', () => {
      this._autoResize();
      this._syncState();
      this._persistState?.();
      this.dispatch('input', { value: this.value });
    });

    this.listen(this._textarea, 'keydown', (e) => {
      // Do not submit during IME composition (Chinese, Japanese, Korean, Pinyin)
      if (e.isComposing || e.keyCode === 229) return;

      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        this.submit();
      }
    });

    // Multimodal Clipboard Paste (Screenshots, Images, Files)
    this.listen(this._textarea, 'paste', (e) => {
      const clipboardData = e.clipboardData;
      if (!clipboardData) return;

      const files = [];
      if (clipboardData.files && clipboardData.files.length > 0) {
        for (let i = 0; i < clipboardData.files.length; i++) {
          files.push(clipboardData.files[i]);
        }
      } else if (clipboardData.items) {
        for (let i = 0; i < clipboardData.items.length; i++) {
          const item = clipboardData.items[i];
          if (item.kind === 'file') {
            const file = item.getAsFile();
            if (file) files.push(file);
          }
        }
      }

      if (files.length > 0) {
        this.dispatch('filepaste', { files });
      }
    });

    // Multimodal Drag & Drop onto Prompt Box
    this.listen(this, 'dragover', (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (!this.disabled && !this.loading) {
        this.setAttributeSafe('data-dragover', '');
      }
    });

    this.listen(this, 'dragleave', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.removeAttributeSafe('data-dragover');
    });

    this.listen(this, 'drop', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.removeAttributeSafe('data-dragover');
      if (this.disabled || this.loading) return;

      const dt = e.dataTransfer;
      if (dt && dt.files && dt.files.length > 0) {
        const files = Array.from(dt.files);
        this.dispatch('filedrop', { files });
      }
    });

    // Optional Attach Button Hookup with file input
    const attachBtn = this.querySelector('[data-part="attach-btn"]');
    const fileInput = this.querySelector('[data-part="file-input"], input[type="file"]');
    if (attachBtn && fileInput) {
      this.listen(attachBtn, 'click', (e) => {
        e.preventDefault();
        fileInput.click();
      });
      this.listen(fileInput, 'change', () => {
        const files = Array.from(fileInput.files || []);
        if (files.length > 0) {
          this.dispatch('fileattach', { files });
        }
      });
    }

    const submitBtn = this.querySelector('[data-part="submit-btn"]');
    if (submitBtn) {
      this.listen(submitBtn, 'click', (e) => {
        e.preventDefault();
        this.submit();
      });
    }

    const stopBtn = this.querySelector('[data-part="stop-btn"]');
    if (stopBtn) {
      this.listen(stopBtn, 'click', (e) => {
        e.preventDefault();
        this.stop();
      });
    }
  }

  submit() {
    if (this.disabled || this.loading) return;
    const text = this.value.trim();
    if (!text) return;

    this.dispatch('submit', { prompt: text });
    this.value = '';
    this._syncState();
    this._persistState?.();
  }

  stop() {
    this.dispatch('stop');
    this.loading = false;
  }

  clear() {
    this.value = '';
    this._syncState();
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * <ui-color-picker> Micro-Enhancer
 * Accessible modern color picker with native EyeDropper API in Light-DOM.
 * 
 * Features:
 * - Real-time swatch preview with accessible popover
 * - Native window.EyeDropper API screen sampling integration
 * - Hex, RGB, and HSL text input synchronization
 * - Slider-driven Hue and Alpha adjustments
 * - Form-associated hidden input submission
 * - Dispatches 'change' and 'input' CustomEvents with { value }
 */
export class UiColorPicker extends BaseLightElement {
  static formAssociated = true;

  static get observedAttributes() {
    return ['value', 'name', 'format', 'disabled'];
  }

  constructor() {
    super();
    if (typeof this.attachInternals === 'function') {
      this._internals = this.attachInternals();
    }
  }

  get form() {
    return this._internals ? this._internals.form : null;
  }

  set form(_) {}

  get value() {
    return this.getAttribute('value') || '#3b82f6';
  }

  set value(val) {
    this.setAttributeSafe('value', val);
    this._syncState();
  }

  get name() {
    return this.getAttribute('name') || '';
  }

  set name(val) {
    if (val) this.setAttributeSafe('name', val);
    else this.removeAttributeSafe('name');
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(val) {
    if (val) {
      this.setAttributeSafe('disabled', '');
    } else {
      this.removeAttributeSafe('disabled');
    }
    this._syncState();
  }

  get isOpen() {
    const popover = this.querySelector('[data-part="popover"]');
    return popover?.getAttribute('data-state') === 'open';
  }

  set isOpen(val) {
    if (val) this.open();
    else this.close();
  }

  init() {
    this.setAttributeSafe('data-ui', 'color-picker');

    this._setupStructure();
    this._syncState();
    this._bindEvents();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue || !this._initialized) return;
    if (name === 'value') {
      this._syncState();
    } else if (name === 'disabled') {
      this._syncState();
    }
  }

  _setupStructure() {
    // Hidden input for form submissions
    if (this.name && !this.querySelector('input[type="hidden"]')) {
      const hiddenInput = document.createElement('input');
      hiddenInput.type = 'hidden';
      hiddenInput.name = this.name;
      hiddenInput.value = this.value;
      this.appendChild(hiddenInput);
      this._hiddenInput = hiddenInput;
    } else {
      this._hiddenInput = this.querySelector('input[type="hidden"]');
    }

    const popover = this.querySelector('[data-part="popover"]');
    if (popover) {
      popover.removeAttribute('popover');
      popover.setAttribute('data-state', 'closed');
    }
  }

  _syncState() {
    const color = this.value;
    const swatch = this.querySelector('[data-part="swatch"]');
    const input = this.querySelector('[data-part="hex-input"], [data-part="input"]');
    const popover = this.querySelector('[data-part="popover"]');

    if (swatch) {
      swatch.style.backgroundColor = color;
      swatch.setAttribute('aria-label', `Selected color: ${color}`);
    }

    if (input && input !== document.activeElement) {
      input.value = color;
    }

    if (this._hiddenInput) {
      this._hiddenInput.value = color;
    }
    this._updateFormValue();

    if (this.disabled) {
      swatch?.setAttribute('disabled', '');
      input?.setAttribute('disabled', '');
    } else {
      swatch?.removeAttribute('disabled');
      input?.removeAttribute('disabled');
    }
  }

  _bindEvents() {
    const swatch = this.querySelector('[data-part="swatch"]');
    const popover = this.querySelector('[data-part="popover"]');
    const input = this.querySelector('[data-part="hex-input"], [data-part="input"]');
    const eyedropperBtn = this.querySelector('[data-part="eyedropper-btn"]');
    const hueSlider = this.querySelector('[data-part="hue-slider"]');

    // Toggle popover on swatch click
    if (swatch) {
      this.listen(swatch, 'click', (e) => {
        if (this.disabled) return;
        e.preventDefault();
        this.toggle();
      });
    }

    // Input typing
    if (input) {
      this.listen(input, 'input', () => {
        let val = input.value.trim();
        if (!val.startsWith('#') && val.length === 6) val = `#${val}`;
        if (/^#[0-9A-Fa-f]{6}$/.test(val) || /^#[0-9A-Fa-f]{3}$/.test(val)) {
          this.setValue(val);
        }
      });

      this.listen(input, 'change', () => {
        this.dispatch('change', { value: this.value });
      });
    }

    // Native EyeDropper API
    if (eyedropperBtn) {
      if (typeof window !== 'undefined' && 'EyeDropper' in window) {
        this.listen(eyedropperBtn, 'click', async (e) => {
          e.preventDefault();
          try {
            const eyeDropper = new window.EyeDropper();
            const result = await eyeDropper.open();
            if (result?.sRGBHex) {
              this.setValue(result.sRGBHex);
              this.dispatch('change', { value: result.sRGBHex });
            }
          } catch (err) {
            // User canceled eyedropper
          }
        });
      } else {
        eyedropperBtn.style.display = 'none';
      }
    }

    // Hue Slider
    if (hueSlider) {
      this.listen(hueSlider, 'input', () => {
        const hue = hueSlider.value;
        const color = `hsl(${hue}, 80%, 50%)`;
        this.setValue(color);
      });
    }

    // Close on click outside
    this.listen(document, 'pointerdown', (e) => {
      if (!this.isOpen) return;
      if (!this.contains(e.target) && !popover?.contains(e.target)) {
        this.close();
      }
    });
  }

  setValue(newVal) {
    const prev = this.value;
    if (prev === newVal) return;

    this.setAttributeSafe('value', newVal);
    this._syncState();
    this.dispatch('input', { value: newVal });
  }

  toggle() {
    if (this.isOpen) this.close();
    else this.open();
  }

  open() {
    const popover = this.querySelector('[data-part="popover"]');
    if (!popover || this.disabled) return;

    popover.setAttribute('data-state', 'open');
    this.dispatch('open');
  }

  _updateFormValue() {
    if (this._internals) {
      this._internals.setFormValue(this.value);
    }
    if (this._hiddenInput) {
      this._hiddenInput.value = this.value;
    }
  }

  formResetCallback() {
    const initialVal = this.getAttribute('value') || '#3b82f6';
    this.value = initialVal;
  }

  close() {
    const popover = this.querySelector('[data-part="popover"]');
    if (!popover) return;

    popover.setAttribute('data-state', 'closed');
    this.dispatch('close');
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * <ui-sparkline> Micro-Enhancer
 * Lightweight, zero-dependency SVG micro-trendline and area chart in Light-DOM.
 * 
 * Features:
 * - Sub-1KB SVG path generation (straight or smooth bezier curves)
 * - Automatic min/max normalization and aspect ratio preservation
 * - Optional area gradient fill
 * - Interactive hover cursor with animated focal point and floating value tooltip
 * - Auto-trend coloring (positive / negative delta detection)
 * - Dispatches 'hoverpoint' CustomEvent: { index, value, x, y }
 * - V-DOM & SSR safe, 100% accessible via role="img" and aria-label
 */
export class UiSparkline extends BaseLightElement {
  static get observedAttributes() {
    return ['data', 'color', 'stroke-width', 'fill', 'hoverable', 'height', 'width', 'smooth'];
  }

  get data() {
    const raw = this.getAttribute('data') || '';
    if (!raw) return this._dataArray || [];
    try {
      if (raw.startsWith('[')) return JSON.parse(raw);
    } catch {}
    return raw.split(/[\s,]+/).map(v => parseFloat(v)).filter(v => !isNaN(v));
  }

  set data(val) {
    if (Array.isArray(val)) {
      this._dataArray = val;
      this.setAttributeSafe('data', JSON.stringify(val));
    } else if (typeof val === 'string') {
      this.setAttributeSafe('data', val);
    } else {
      this.removeAttributeSafe('data');
    }
    this._render();
  }

  get color() {
    return this.getAttribute('color') || 'auto';
  }

  set color(val) {
    if (val) this.setAttributeSafe('color', val);
    else this.removeAttributeSafe('color');
    this._render();
  }

  get strokeWidth() {
    const w = parseFloat(this.getAttribute('stroke-width'));
    return isNaN(w) || w <= 0 ? 2 : w;
  }

  set strokeWidth(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('stroke-width', String(val));
    else this.removeAttributeSafe('stroke-width');
    this._render();
  }

  get fill() {
    return this.getAttribute('fill') || 'gradient';
  }

  set fill(val) {
    if (val) this.setAttributeSafe('fill', val);
    else this.removeAttributeSafe('fill');
    this._render();
  }

  get hoverable() {
    return this.hasAttribute('hoverable') && this.getAttribute('hoverable') !== 'false';
  }

  set hoverable(val) {
    if (val) this.setAttributeSafe('hoverable', '');
    else this.removeAttributeSafe('hoverable');
  }

  get smooth() {
    return this.getAttribute('smooth') !== 'false';
  }

  set smooth(val) {
    if (val === false || val === 'false') this.setAttributeSafe('smooth', 'false');
    else this.removeAttributeSafe('smooth');
    this._render();
  }

  getAiState() {
    return {
      pointsCount: this.data.length,
      values: this.data,
      color: this.color,
      fill: this.fill,
      hoverable: this.hoverable,
    };
  }

  init() {
    this.setAttributeSafe('data-ui', 'sparkline');
    this.setAttributeSafe('role', 'img');

    this._uniqueId = 'spark-' + Math.random().toString(36).slice(2, 7);
    this._render();
    this._bindEvents();
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (oldVal !== newVal && this._initialized) {
      this._render();
    }
  }

  _bindEvents() {
    this.listen(this, 'mousemove', (e) => this._onMouseMove(e));
    this.listen(this, 'mouseleave', () => this._onMouseLeave());
  }

  _render() {
    const rawData = this.data;
    if (!rawData || rawData.length < 2) {
      this.innerHTML = '';
      return;
    }

    const min = Math.min(...rawData);
    const max = Math.max(...rawData);
    const range = max === min ? 1 : max - min;

    const width = 160;
    const height = 48;
    const padding = 4;
    const usableW = width - padding * 2;
    const usableH = height - padding * 2;

    // Calculate coordinates
    const points = rawData.map((val, idx) => {
      const x = padding + (idx / (rawData.length - 1)) * usableW;
      const y = height - padding - ((val - min) / range) * usableH;
      return { x, y, val, idx };
    });
    this._points = points;

    // Auto trend color determination
    let strokeColor = this.color;
    if (strokeColor === 'auto') {
      const isPositive = rawData[rawData.length - 1] >= rawData[0];
      strokeColor = isPositive ? 'var(--ui-color-success-500, #10b981)' : 'var(--ui-color-danger-500, #ef4444)';
    }

    // Build SVG Path
    let linePath = '';
    if (this.smooth && points.length > 2) {
      linePath = `M ${points[0].x} ${points[0].y}`;
      for (let i = 0; i < points.length - 1; i++) {
        const p0 = points[i === 0 ? 0 : i - 1];
        const p1 = points[i];
        const p2 = points[i + 1];
        const p3 = points[i + 2 < points.length ? i + 2 : i + 1];

        const cp1x = p1.x + (p2.x - p0.x) / 6;
        const cp1y = p1.y + (p2.y - p0.y) / 6;
        const cp2x = p2.x - (p3.x - p1.x) / 6;
        const cp2y = p2.y - (p3.y - p1.y) / 6;

        linePath += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)}, ${cp2x.toFixed(1)} ${cp2y.toFixed(1)}, ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`;
      }
    } else {
      linePath = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');
    }

    const areaPath = `${linePath} L ${points[points.length - 1].x.toFixed(1)} ${height} L ${points[0].x.toFixed(1)} ${height} Z`;

    const gradId = `spark-grad-${this._uniqueId}`;

    const deltaPercent = (((rawData[rawData.length - 1] - rawData[0]) / (Math.abs(rawData[0]) || 1)) * 100).toFixed(1);
    this.setAttributeSafe('aria-label', `Trend sparkline: ${rawData.length} points, ending at ${rawData[rawData.length - 1]} (${deltaPercent}% change)`);

    this.innerHTML = `
      <svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" data-part="svg" style="width: 100%; height: 100%; display: block; overflow: visible;">
        <defs>
          <linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="${strokeColor}" stop-opacity="0.32" />
            <stop offset="100%" stop-color="${strokeColor}" stop-opacity="0.0" />
          </linearGradient>
        </defs>
        ${this.fill === 'gradient' ? `<path data-part="area" d="${areaPath}" fill="url(#${gradId})" />` : ''}
        ${this.fill === 'solid' ? `<path data-part="area" d="${areaPath}" fill="${strokeColor}" opacity="0.15" />` : ''}
        <path data-part="line" d="${linePath}" fill="none" stroke="${strokeColor}" stroke-width="${this.strokeWidth}" stroke-linecap="round" stroke-linejoin="round" />
        <circle data-part="cursor-dot" r="4" fill="${strokeColor}" stroke="#ffffff" stroke-width="2" style="display: none; transition: transform var(--ui-transition-spring-snappy, 150ms ease);" />
      </svg>
      <div data-part="tooltip" style="display: none; position: absolute; pointer-events: none; z-index: 10; font-family: var(--ui-font-mono, monospace); font-size: 0.7rem; font-weight: 600; padding: 2px 6px; border-radius: 4px; background: var(--ui-bg-surface-elevated, #18181b); color: var(--ui-text-primary, #ffffff); border: 1px solid var(--ui-border-default, #27272a); box-shadow: var(--ui-shadow-md, 0 4px 6px rgba(0,0,0,0.1)); transform: translate(-50%, -125%); white-space: nowrap;"></div>
    `;

    this._cursorDot = this.querySelector('[data-part="cursor-dot"]');
    this._tooltip = this.querySelector('[data-part="tooltip"]');
  }

  _onMouseMove(e) {
    if (!this.hoverable || !this._points || this._points.length === 0) return;

    const rect = this.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const ratio = Math.max(0, Math.min(1, mouseX / rect.width));
    const targetSvgX = 4 + ratio * (160 - 8);

    // Find nearest point
    let nearest = this._points[0];
    let minDiff = Infinity;
    for (const p of this._points) {
      const diff = Math.abs(p.x - targetSvgX);
      if (diff < minDiff) {
        minDiff = diff;
        nearest = p;
      }
    }

    if (this._cursorDot) {
      this._cursorDot.style.display = 'block';
      this._cursorDot.setAttribute('cx', String(nearest.x));
      this._cursorDot.setAttribute('cy', String(nearest.y));
    }

    if (this._tooltip) {
      this._tooltip.style.display = 'block';
      const actualX = (nearest.x / 160) * rect.width;
      const actualY = (nearest.y / 48) * rect.height;
      this._tooltip.style.left = `${actualX}px`;
      this._tooltip.style.top = `${actualY}px`;
      this._tooltip.textContent = String(nearest.val);
    }

    this.dispatch('hoverpoint', {
      index: nearest.idx,
      value: nearest.val,
      x: nearest.x,
      y: nearest.y,
    });
  }

  _onMouseLeave() {
    if (this._cursorDot) this._cursorDot.style.display = 'none';
    if (this._tooltip) this._tooltip.style.display = 'none';
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys, applyRovingTabindex, getNextIndex } from '../../utils/a11y.js';

/**
 * <ui-dock> Micro-Enhancer
 * macOS-inspired floating application dock and action island in Light-DOM.
 * 
 * Features:
 * - Distance-weighted spring magnification on mousemove
 * - Ultra-smooth spring settlement using --ui-spring-snappy
 * - Full WAI-ARIA roving tabindex keyboard navigation (ArrowLeft, ArrowRight, Home, End)
 * - Automatic tooltips with aria-label mirroring
 * - Dispatches 'select' CustomEvent with { index, value, item }
 * - 100% Light-DOM, zero Shadow DOM traps
 */
export class UiDock extends BaseLightElement {
  static get observedAttributes() {
    return ['position', 'distance', 'max-scale', 'orientation'];
  }

  get position() {
    return this.getAttribute('position') || 'bottom';
  }

  set position(val) {
    if (val) this.setAttributeSafe('position', val);
    else this.removeAttributeSafe('position');
  }

  get distance() {
    const d = parseFloat(this.getAttribute('distance'));
    return isNaN(d) || d <= 0 ? 140 : d;
  }

  set distance(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('distance', String(val));
    else this.removeAttributeSafe('distance');
  }

  get maxScale() {
    const s = parseFloat(this.getAttribute('max-scale'));
    return isNaN(s) || s <= 1 ? 1.45 : s;
  }

  set maxScale(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('max-scale', String(val));
    else this.removeAttributeSafe('max-scale');
  }

  getAiState() {
    return {
      position: this.position,
      itemsCount: this._getItems().length,
      maxScale: this.maxScale,
      distance: this.distance,
    };
  }

  init() {
    this.setAttributeSafe('data-ui', 'dock');
    this.setAttributeSafe('role', 'toolbar');
    this.setAttributeSafe('aria-label', 'Application Dock');

    this._activeIndex = 0;
    this._rafId = null;

    this._setupItems();
    this._bindEvents();
  }

  _getItems() {
    return Array.from(this.querySelectorAll('[data-part="item"], button, a')).filter(
      (el) => el.parentElement === this || el.parentElement.getAttribute('data-part') === 'container'
    );
  }

  _setupItems() {
    const items = this._getItems();
    let hasActive = false;

    items.forEach((item, idx) => {
      this.setAttributeSafe(item, 'data-part', 'item');
      this.setAttributeSafe(item, 'tabindex', idx === 0 ? '0' : '-1');

      const isMarkedActive =
        item.hasAttribute('active') ||
        item.getAttribute('data-active') === 'true' ||
        item.getAttribute('aria-selected') === 'true';

      if (isMarkedActive && !hasActive) {
        this.setAttributeSafe(item, 'data-active', 'true');
        this.setAttributeSafe(item, 'aria-selected', 'true');
        this._activeIndex = idx;
        hasActive = true;
      }

      // Visible label scaffolding if data-label exists and no [data-part="label"] is present
      const labelText = item.getAttribute('data-label');
      if (labelText && !item.querySelector('[data-part="label"]')) {
        const lbl = document.createElement('span');
        lbl.setAttribute('data-part', 'label');
        lbl.textContent = labelText;
        item.appendChild(lbl);
      }

      // Tooltip scaffolding if aria-label/title exists and item has no visible label
      const tipText = item.getAttribute('aria-label') || item.getAttribute('title');
      if (tipText && !item.querySelector('[data-part="tooltip"]') && !item.querySelector('[data-part="label"]')) {
        const tip = document.createElement('span');
        tip.setAttribute('data-part', 'tooltip');
        tip.textContent = tipText;
        item.appendChild(tip);
      }
    });
  }

  _bindEvents() {
    this.listen(this, 'mousemove', (e) => this._onMouseMove(e));
    this.listen(this, 'mouseleave', () => this._onMouseLeave());
    this.listen(this, 'keydown', (e) => this._onKeyDown(e));
    this.listen(this, 'click', (e) => this._onClick(e));
  }

  _onMouseMove(e) {
    if (this._rafId) return;

    this._rafId = requestAnimationFrame(() => {
      this._rafId = null;
      const mouseX = e.clientX;
      const mouseY = e.clientY;
      const maxDist = this.distance;
      const maxScale = this.maxScale;

      const items = this._getItems();
      items.forEach((item) => {
        const rect = item.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const dist = Math.abs(mouseX - centerX);

        if (dist < maxDist) {
          const factor = Math.cos((dist / maxDist) * (Math.PI / 2));
          const scale = 1 + (maxScale - 1) * factor;
          item.style.setProperty('--dock-scale', scale.toFixed(3));
          item.style.setProperty('--dock-translate-y', `${((-1 * (scale - 1) * 16)).toFixed(1)}px`);
        } else {
          item.style.setProperty('--dock-scale', '1');
          item.style.setProperty('--dock-translate-y', '0px');
        }
      });
    });
  }

  _onMouseLeave() {
    if (this._rafId) {
      cancelAnimationFrame(this._rafId);
      this._rafId = null;
    }
    const items = this._getItems();
    items.forEach((item) => {
      item.style.setProperty('--dock-scale', '1');
      item.style.setProperty('--dock-translate-y', '0px');
    });
  }

  _onKeyDown(e) {
    const items = this._getItems();
    if (items.length === 0) return;

    let targetIdx = this._activeIndex;

    switch (e.key) {
      case Keys.ARROW_RIGHT:
      case Keys.ARROW_DOWN:
        e.preventDefault();
        targetIdx = getNextIndex(this._activeIndex, items.length, 1, true);
        break;
      case Keys.ARROW_LEFT:
      case Keys.ARROW_UP:
        e.preventDefault();
        targetIdx = getNextIndex(this._activeIndex, items.length, -1, true);
        break;
      case Keys.HOME:
        e.preventDefault();
        targetIdx = 0;
        break;
      case Keys.END:
        e.preventDefault();
        targetIdx = items.length - 1;
        break;
      case Keys.ENTER:
      case Keys.SPACE:
      case Keys.SPACEBAR:
        e.preventDefault();
        if (items[this._activeIndex]) {
          items[this._activeIndex].click();
        }
        return;
      default:
        return;
    }

    if (targetIdx !== this._activeIndex && items[targetIdx]) {
      this._activeIndex = targetIdx;
      applyRovingTabindex(items, targetIdx, true);
    }
  }

  _onClick(e) {
    const item = e.target.closest('[data-part="item"], button, a');
    if (!item || !this.contains(item)) return;

    const items = this._getItems();
    const index = items.indexOf(item);
    if (index >= 0) {
      this._activeIndex = index;
      applyRovingTabindex(items, index, false);

      items.forEach((it, i) => {
        if (i === index) {
          this.setAttributeSafe(it, 'data-active', 'true');
          this.setAttributeSafe(it, 'aria-selected', 'true');
        } else {
          this.removeAttributeSafe(it, 'data-active');
          this.removeAttributeSafe(it, 'aria-selected');
        }
      });
    }

    const label =
      item.querySelector('[data-part="label"]')?.textContent?.trim() ||
      item.getAttribute('data-label') ||
      item.getAttribute('aria-label') ||
      '';

    this.dispatch('select', {
      index,
      value: item.getAttribute('data-value') || item.getAttribute('href') || label || item.textContent?.trim(),
      label,
      item,
    });
  }
}

import { BaseLightElement } from '../../utils/base-element.js';

/**
 * <ui-timeline> Micro-Enhancer
 * Accessible, platform-native event stream & workflow step timeline in Light-DOM.
 * 
 * Features:
 * - Vertical (default) and horizontal orientation support
 * - Dynamic status indicators: completed, active (pulsing radar beacon), pending, error
 * - Seamless connecting line tracks between nodes
 * - Keyboard navigable with WAI-ARIA role="list" and role="listitem"
 * - Dispatches 'stepclick' CustomEvent with { index, item, status }
 * - 100% Light-DOM, zero Shadow DOM traps
 */
export class UiTimeline extends BaseLightElement {
  static get observedAttributes() {
    return ['orientation', 'active-step'];
  }

  get orientation() {
    return this.getAttribute('orientation') || 'vertical';
  }

  set orientation(val) {
    if (val) this.setAttributeSafe('orientation', val);
    else this.removeAttributeSafe('orientation');
  }

  get activeStep() {
    const s = parseInt(this.getAttribute('active-step'), 10);
    return isNaN(s) ? -1 : s;
  }

  set activeStep(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('active-step', String(val));
    else this.removeAttributeSafe('active-step');
    this._syncActiveStep();
  }

  getAiState() {
    return {
      orientation: this.orientation,
      itemsCount: this._getItems().length,
      activeStep: this.activeStep,
    };
  }

  init() {
    this.setAttributeSafe('data-ui', 'timeline');
    this.setAttributeSafe('role', 'list');

    this._setupItems();
    this._syncActiveStep();
    this._bindEvents();
  }

  _getItems() {
    return Array.from(this.querySelectorAll('[data-part="item"]'));
  }

  _setupItems() {
    const items = this._getItems();
    items.forEach((item, idx) => {
      this.setAttributeSafe(item, 'role', 'listitem');
      this.setAttributeSafe(item, 'data-index', String(idx));

      // Auto-scaffold connector line if missing
      if (!item.querySelector('[data-part="connector"]') && idx < items.length - 1) {
        const connector = document.createElement('span');
        connector.setAttribute('data-part', 'connector');
        item.appendChild(connector);
      }

      // Auto-scaffold marker if missing
      if (!item.querySelector('[data-part="marker"]')) {
        const marker = document.createElement('span');
        marker.setAttribute('data-part', 'marker');
        item.prepend(marker);
      }
    });
  }

  _syncActiveStep() {
    const items = this._getItems();
    const activeIdx = this.activeStep;
    if (activeIdx < 0) return;

    items.forEach((item, idx) => {
      if (idx < activeIdx) {
        this.setAttributeSafe(item, 'data-status', 'completed');
      } else if (idx === activeIdx) {
        this.setAttributeSafe(item, 'data-status', 'active');
      } else {
        this.setAttributeSafe(item, 'data-status', 'pending');
      }
    });
  }

  _bindEvents() {
    this.listen(this, 'click', (e) => {
      const item = e.target.closest('[data-part="item"]');
      if (!item || !this.contains(item)) return;

      const items = this._getItems();
      const index = items.indexOf(item);
      const status = item.getAttribute('data-status') || 'default';

      this.dispatch('stepclick', {
        index,
        item,
        status,
        title: item.querySelector('[data-part="title"]')?.textContent?.trim() || '',
      });
    });
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys } from '../../utils/a11y.js';

/**
 * <ui-ai-reasoning> Micro-Enhancer
 * Accessible, platform-native chain-of-thought & reasoning disclosure in Light-DOM.
 * 
 * Features:
 * - Real-time elapsed thinking timer ("Thinking (3.4s)..." -> "Thought for 4.2s")
 * - Dynamic status states: 'thinking' (pulsing aura) and 'done' (settled emerald sparkle)
 * - Spring-animated collapsible disclosure tray with WAI-ARIA disclosure pattern
 * - Built-in copy thoughts trigger with visual feedback
 * - Optional auto-collapse when streaming completes (auto-collapse="true")
 * - 100% Light-DOM, zero Shadow DOM traps
 */
export class UiAiReasoning extends BaseLightElement {
  static get observedAttributes() {
    return ['status', 'duration', 'open', 'collapsed', 'auto-collapse', 'collapsible', 'auto-scroll'];
  }

  get status() {
    return this.getAttribute('status') || 'thinking';
  }

  set status(val) {
    if (val) this.setAttributeSafe('status', val);
    else this.removeAttributeSafe('status');
  }

  get duration() {
    const d = parseFloat(this.getAttribute('duration'));
    return isNaN(d) ? this._elapsedSeconds : d;
  }

  set duration(val) {
    if (val !== null && val !== undefined) this.setAttributeSafe('duration', String(val));
    else this.removeAttributeSafe('duration');
  }

  get open() {
    if (this.hasAttribute('open')) {
      const val = this.getAttribute('open');
      return val !== 'false';
    }
    if (this.hasAttribute('collapsed')) {
      return this.getAttribute('collapsed') === 'false';
    }
    return false;
  }

  set open(val) {
    if (val) {
      this.setAttributeSafe('open', '');
      this.removeAttributeSafe('collapsed');
    } else {
      this.removeAttributeSafe('open');
      this.removeAttributeSafe('collapsed');
    }
  }

  get collapsed() {
    return !this.open;
  }

  set collapsed(val) {
    this.open = !val;
  }

  get autoCollapse() {
    return this.hasAttribute('auto-collapse');
  }

  set autoCollapse(val) {
    if (val) this.setAttributeSafe('auto-collapse', '');
    else this.removeAttributeSafe('auto-collapse');
  }

  get collapsible() {
    return this.getAttribute('collapsible') !== 'false';
  }

  set collapsible(val) {
    if (val === false) this.setAttributeSafe('collapsible', 'false');
    else this.removeAttributeSafe('collapsible');
  }

  get autoScroll() {
    return this.getAttribute('auto-scroll') !== 'false';
  }

  set autoScroll(val) {
    if (val === false) this.setAttributeSafe('auto-scroll', 'false');
    else this.removeAttributeSafe('auto-scroll');
  }

  getAiState() {
    return {
      status: this.status,
      duration: this.duration,
      open: this.open,
      autoCollapse: this.autoCollapse,
      collapsible: this.collapsible,
      autoScroll: this.autoScroll,
      streamContentLength: this._getStreamContent().length,
    };
  }

  init() {
    this.setAttributeSafe('data-ui', 'ai-reasoning');
    this.setAttributeSafe('role', 'region');
    this.setAttributeSafe('aria-label', 'AI Reasoning Thoughts');

    this._startTime = Date.now();
    this._elapsedSeconds = 0;
    this._timerId = null;
    this._userScrolled = false;
    this._observer = null;

    this._scaffoldHeader();
    this._syncState();
    this._bindEvents();
    this._setupAutoScroll();

    if (this.status === 'thinking') {
      this._startTimer();
    }
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (!this._initialized || oldVal === newVal) return;

    if (name === 'status') {
      if (newVal === 'done') {
        this._stopTimer();
        if (this.autoCollapse) {
          this.open = false;
        }
      } else if (newVal === 'thinking') {
        this._startTime = Date.now() - (this._elapsedSeconds * 1000);
        this._startTimer();
      }
      this._syncState();
      this.dispatch('statuschange', { status: newVal, duration: this.duration });
    } else if (name === 'open' || name === 'collapsed') {
      this._syncOpen();
    } else if (name === 'duration') {
      this._updateSummaryText();
    }
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopTimer();
    if (this._observer) {
      this._observer.disconnect();
      this._observer = null;
    }
  }

  _getStreamElement() {
    return this.querySelector(':scope > [data-part="stream"], :scope > [data-part="content"], :scope > [data-part="body"]');
  }

  _getStreamContent() {
    const stream = this._getStreamElement();
    return stream ? (stream.innerText || stream.textContent || '').trim() : '';
  }

  _setupAutoScroll() {
    const stream = this._getStreamElement();
    if (!stream) return;

    this.listen(stream, 'scroll', () => {
      const threshold = 16;
      const isAtBottom = stream.scrollHeight - stream.scrollTop <= stream.clientHeight + threshold;
      this._userScrolled = !isAtBottom;
    });

    if (typeof MutationObserver !== 'undefined') {
      this._observer = new MutationObserver(() => {
        if (this.open && this.autoScroll && !this._userScrolled && this.status === 'thinking') {
          this.scrollToBottom();
        }
      });
      this._observer.observe(stream, { childList: true, subtree: true, characterData: true });
    }
  }

  scrollToBottom() {
    const stream = this._getStreamElement();
    if (stream) {
      stream.scrollTop = stream.scrollHeight;
    }
  }

  _scaffoldHeader() {
    // Clean up any legacy or misplaced trigger element
    const legacyTrigger = this.querySelector(':scope > [data-part="trigger"]');
    if (legacyTrigger) {
      legacyTrigger.remove();
    }

    let header = this.querySelector(':scope > [data-part="header"]');
    if (!header) {
      header = document.createElement('div');
      header.setAttribute('data-part', 'header');

      const beacon = document.createElement('span');
      beacon.setAttribute('data-part', 'beacon');
      beacon.innerHTML = `
        <svg data-icon="sparkle" viewBox="0 0 24 24" width="16" height="16" stroke="currentColor" fill="none" stroke-width="2.2">
          <path d="M12 2v4m0 12v4M4.93 4.93l2.83 2.83m8.48 8.48 2.83 2.83M2 12h4m12 0h4M4.93 19.07l2.83-2.83m8.48-8.48 2.83-2.83"/>
        </svg>
      `;

      const summary = document.createElement('span');
      summary.setAttribute('data-part', 'summary');

      const actions = document.createElement('div');
      actions.setAttribute('data-part', 'actions');

      const copyBtn = document.createElement('button');
      copyBtn.setAttribute('data-part', 'copy');
      copyBtn.setAttribute('type', 'button');
      copyBtn.setAttribute('title', 'Copy thoughts');
      copyBtn.setAttribute('aria-label', 'Copy thoughts');
      copyBtn.innerHTML = `
        <svg data-icon="copy" viewBox="0 0 24 24" width="13" height="13" stroke="currentColor" fill="none" stroke-width="2">
          <rect x="9" y="9" width="13" height="13" rx="2" ry="2"/>
          <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>
        </svg>
        <span data-part="copy-label">Copy</span>
      `;

      const toggleBtn = document.createElement('button');
      toggleBtn.setAttribute('data-part', 'toggle');
      toggleBtn.setAttribute('type', 'button');
      toggleBtn.setAttribute('title', 'Toggle reasoning tray');
      toggleBtn.setAttribute('aria-label', 'Toggle reasoning tray');
      toggleBtn.innerHTML = `
        <svg data-icon="chevron" viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2.2">
          <polyline points="6 9 12 15 18 9"/>
        </svg>
      `;

      actions.appendChild(copyBtn);
      actions.appendChild(toggleBtn);

      header.appendChild(beacon);
      header.appendChild(summary);
      header.appendChild(actions);

      this.prepend(header);
    }
  }

  _startTimer() {
    this._stopTimer();
    this._timerId = setInterval(() => {
      this._elapsedSeconds = (Date.now() - this._startTime) / 1000;
      this._updateSummaryText();
    }, 100);
  }

  _stopTimer() {
    if (this._timerId) {
      clearInterval(this._timerId);
      this._timerId = null;
    }
  }

  _updateSummaryText() {
    const summary = this.querySelector('[data-part="summary"]');
    if (!summary) return;

    const dur = this.duration.toFixed(1);
    if (this.status === 'thinking') {
      summary.textContent = `Thinking (${dur}s)...`;
    } else {
      summary.textContent = `Thought for ${dur} seconds`;
    }
  }

  _syncState() {
    this.setAttributeSafe('data-status', this.status);
    this._updateSummaryText();
    this._syncOpen();
  }

  _syncOpen() {
    const header = this.querySelector(':scope > [data-part="header"]');
    const stream = this.querySelector(':scope > [data-part="stream"], :scope > [data-part="content"], :scope > [data-part="body"]');
    const isOpen = this.open;

    if (isOpen) {
      this.setAttributeSafe('data-open', '');
    } else {
      this.removeAttributeSafe('data-open');
    }

    if (header) {
      this.setAttributeSafe(header, 'aria-expanded', String(isOpen));
    }
    if (stream) {
      this.setAttributeSafe(stream, 'aria-hidden', String(!isOpen));
    }
  }

  _bindEvents() {
    const header = this.querySelector(':scope > [data-part="header"]');
    if (header) {
      this.listen(header, 'click', (e) => {
        if (e.target.closest('[data-part="copy"]')) {
          this._handleCopy();
          return;
        }
        if (!this.collapsible) return;
        this.open = !this.open;
        this.dispatch('toggle', { open: this.open, duration: this.duration });
      });

      this.listen(header, 'keydown', (e) => {
        if (e.key === Keys.ENTER || e.key === Keys.SPACE || e.key === Keys.SPACEBAR) {
          e.preventDefault();
          if (this.collapsible) {
            this.open = !this.open;
            this.dispatch('toggle', { open: this.open, duration: this.duration });
          }
        }
      });
    }

    const copyBtn = this.querySelector('[data-part="copy"]');
    if (copyBtn) {
      this.listen(copyBtn, 'click', (e) => {
        e.stopPropagation();
        this._handleCopy();
      });
    }
  }

  async _handleCopy() {
    const content = this._getStreamContent();
    if (!content) return;

    try {
      if (typeof navigator !== 'undefined' && navigator.clipboard) {
        await navigator.clipboard.writeText(content);
      }
      this._flashCopiedState();
      this.dispatch('copy', { text: content });
    } catch {
      // Fallback
    }
  }

  _flashCopiedState() {
    const label = this.querySelector('[data-part="copy-label"]');
    if (!label) return;
    const prev = label.textContent;
    label.textContent = 'Copied!';
    setTimeout(() => {
      label.textContent = prev;
    }, 1600);
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys } from '../../utils/a11y.js';

/**
 * <ui-ai-tool-call> Micro-Enhancer
 * Accessible, platform-native agent tool execution inspector in Light-DOM.
 * 
 * Features:
 * - Dynamic execution state indicators: 'pending', 'running', 'success', 'error'
 * - Real-time execution latency display badge (e.g. "142ms", "1.2s")
 * - Collapsible arguments and output stream inspector with spring physics
 * - Automatic inspection tray wrapper for children elements
 * - Built-in Retry action trigger dispatching 'retry' CustomEvent
 * - One-click payload copy trigger with visual feedback
 * - 100% Light-DOM, zero Shadow DOM traps
 */
export class UiAiToolCall extends BaseLightElement {
  static get observedAttributes() {
    return ['name', 'tool-name', 'status', 'latency', 'open', 'collapsible'];
  }

  get name() {
    return this.getAttribute('name') || this.getAttribute('tool-name') || 'tool_call';
  }

  set name(val) {
    if (val) this.setAttributeSafe('name', val);
    else this.removeAttributeSafe('name');
  }

  get status() {
    return this.getAttribute('status') || 'pending';
  }

  set status(val) {
    if (val) this.setAttributeSafe('status', val);
    else this.removeAttributeSafe('status');
  }

  get latency() {
    return this.getAttribute('latency') || '';
  }

  set latency(val) {
    if (val) this.setAttributeSafe('latency', val);
    else this.removeAttributeSafe('latency');
  }

  get open() {
    return this.hasAttribute('open');
  }

  set open(val) {
    if (val) this.setAttributeSafe('open', '');
    else this.removeAttributeSafe('open');
  }

  get collapsible() {
    return this.getAttribute('collapsible') !== 'false';
  }

  set collapsible(val) {
    if (val === false) this.setAttributeSafe('collapsible', 'false');
    else this.removeAttributeSafe('collapsible');
  }

  getAiState() {
    return {
      name: this.name,
      status: this.status,
      latency: this.latency,
      open: this.open,
      collapsible: this.collapsible,
      argsContent: this._getArgsContent(),
      outputContent: this._getOutputContent(),
    };
  }

  init() {
    this.setAttributeSafe('data-ui', 'ai-tool-call');
    this.setAttributeSafe('role', 'region');
    this.setAttributeSafe('aria-label', `Tool Execution: ${this.name}`);

    this._scaffoldHeader();
    this._scaffoldInspector();
    this._syncState();
    this._bindEvents();
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (!this._initialized || oldVal === newVal) return;

    if (name === 'status' || name === 'latency' || name === 'name' || name === 'tool-name') {
      this._syncState();
    } else if (name === 'open') {
      this._syncOpen();
    }
  }

  _getArgsContent() {
    const el = this.querySelector('[data-part="args"], [data-part="arguments"], [data-part="payload"]');
    return el ? el.textContent?.trim() || '' : '';
  }

  _getOutputContent() {
    const el = this.querySelector('[data-part="output"], [data-part="result"]');
    return el ? el.textContent?.trim() || '' : '';
  }

  _scaffoldInspector() {
    let inspector = this.querySelector(':scope > [data-part="inspector"]');
    if (!inspector) {
      const nonHeaderChildren = Array.from(this.children).filter(
        (child) => child.getAttribute('data-part') !== 'header'
      );
      if (nonHeaderChildren.length > 0) {
        inspector = document.createElement('div');
        inspector.setAttribute('data-part', 'inspector');
        nonHeaderChildren.forEach((child) => inspector.appendChild(child));
        this.appendChild(inspector);
      }
    }
  }

  _scaffoldHeader() {
    let header = this.querySelector('[data-part="header"]');
    if (!header) {
      header = document.createElement('div');
      header.setAttribute('data-part', 'header');

      const infoGroup = document.createElement('div');
      infoGroup.setAttribute('data-part', 'info');

      const icon = document.createElement('span');
      icon.setAttribute('data-part', 'icon');
      icon.innerHTML = this._getToolIcon(this.name);

      const nameEl = document.createElement('span');
      nameEl.setAttribute('data-part', 'name');
      nameEl.textContent = this.name;

      const statusBadge = document.createElement('span');
      statusBadge.setAttribute('data-part', 'status-badge');

      const latencyBadge = document.createElement('span');
      latencyBadge.setAttribute('data-part', 'latency');

      infoGroup.appendChild(icon);
      infoGroup.appendChild(nameEl);
      infoGroup.appendChild(statusBadge);
      infoGroup.appendChild(latencyBadge);

      const actions = document.createElement('div');
      actions.setAttribute('data-part', 'actions');

      const retryBtn = document.createElement('button');
      retryBtn.setAttribute('data-part', 'retry');
      retryBtn.setAttribute('type', 'button');
      retryBtn.setAttribute('title', 'Retry tool execution');
      retryBtn.setAttribute('aria-label', 'Retry tool execution');
      retryBtn.innerHTML = `
        <svg viewBox="0 0 24 24" width="13" height="13" stroke="currentColor" fill="none" stroke-width="2.2">
          <polyline points="1 4 1 10 7 10"/>
          <path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/>
        </svg>
      `;

      const copyBtn = document.createElement('button');
      copyBtn.setAttribute('data-part', 'copy');
      copyBtn.setAttribute('type', 'button');
      copyBtn.setAttribute('title', 'Copy payload');
      copyBtn.setAttribute('aria-label', 'Copy payload');
      copyBtn.innerHTML = `
        <svg viewBox="0 0 24 24" width="12" height="12" stroke="currentColor" fill="none" stroke-width="2">
          <rect x="9" y="9" width="13" height="13" rx="2" ry="2"/>
          <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>
        </svg>
        <span data-part="copy-label">Copy</span>
      `;

      const toggleBtn = document.createElement('button');
      toggleBtn.setAttribute('data-part', 'toggle');
      toggleBtn.setAttribute('type', 'button');
      toggleBtn.setAttribute('title', 'Toggle inspector tray');
      toggleBtn.setAttribute('aria-label', 'Toggle inspector tray');
      toggleBtn.innerHTML = `
        <svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2.2">
          <polyline points="6 9 12 15 18 9"/>
        </svg>
      `;

      actions.appendChild(retryBtn);
      actions.appendChild(copyBtn);
      actions.appendChild(toggleBtn);

      header.appendChild(infoGroup);
      header.appendChild(actions);

      this.prepend(header);
    }
  }

  _getToolIcon(name) {
    const n = (name || '').toLowerCase();
    if (n.includes('query') || n.includes('sql') || n.includes('database') || n.includes('db') || n.includes('data')) {
      return `<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"/></svg>`;
    }
    if (n.includes('deploy') || n.includes('pod') || n.includes('k8s') || n.includes('kube') || n.includes('cloud') || n.includes('docker')) {
      return `<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2"><polygon points="12 2 2 7 12 12 22 7 12 2"/><polyline points="2 17 12 22 22 17"/><polyline points="2 12 12 17 22 12"/></svg>`;
    }
    if (n.includes('command') || n.includes('exec') || n.includes('bash') || n.includes('shell') || n.includes('run') || n.includes('sh')) {
      return `<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2"><polyline points="4 17 10 11 4 5"/><line x1="12" y1="19" x2="20" y2="19"/></svg>`;
    }
    if (n.includes('search') || n.includes('web') || n.includes('browse') || n.includes('fetch') || n.includes('http') || n.includes('api')) {
      return `<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>`;
    }
    if (n.includes('file') || n.includes('write') || n.includes('read') || n.includes('edit')) {
      return `<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>`;
    }
    // Default wrench icon
    return `<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" fill="none" stroke-width="2"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/></svg>`;
  }

  _syncState() {
    this.setAttributeSafe('data-status', this.status);

    const nameEl = this.querySelector('[data-part="name"]');
    if (nameEl) nameEl.textContent = this.name;

    const iconEl = this.querySelector('[data-part="icon"]');
    if (iconEl) iconEl.innerHTML = this._getToolIcon(this.name);

    const statusBadge = this.querySelector('[data-part="status-badge"]');
    if (statusBadge) {
      statusBadge.setAttribute('data-status', this.status);
      switch (this.status) {
        case 'running':
          statusBadge.innerHTML = `<span class="ui-tool-spinner"></span> Running`;
          break;
        case 'approval-required':
        case 'requires-approval':
          statusBadge.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" stroke="currentColor" fill="none" stroke-width="2.2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg> Approval Required`;
          break;
        case 'success':
          statusBadge.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" stroke="currentColor" fill="none" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg> Success`;
          break;
        case 'error':
          statusBadge.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" stroke="currentColor" fill="none" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg> Failed`;
          break;
        case 'pending':
        default:
          statusBadge.innerHTML = `● Pending`;
          break;
      }
    }

    const latencyEl = this.querySelector('[data-part="latency"]');
    if (latencyEl) {
      if (this.latency) {
        latencyEl.textContent = this.latency;
        latencyEl.style.display = 'inline-flex';
      } else {
        latencyEl.style.display = 'none';
      }
    }

    const retryBtn = this.querySelector('[data-part="retry"]');
    if (retryBtn) {
      retryBtn.style.display = (this.status === 'error' || this.status === 'success') ? 'inline-flex' : 'none';
    }

    this._syncOpen();
  }

  _syncOpen() {
    const header = this.querySelector('[data-part="header"]');
    const inspector = this.querySelector(':scope > [data-part="inspector"], [data-part="body"]');
    const isOpen = this.open;

    if (header) {
      this.setAttributeSafe(header, 'aria-expanded', String(isOpen));
    }
    if (inspector) {
      this.setAttributeSafe(inspector, 'aria-hidden', String(!isOpen));
    }
  }

  _bindEvents() {
    const header = this.querySelector('[data-part="header"]');
    if (header) {
      this.listen(header, 'click', (e) => {
        if (e.target.closest('[data-part="retry"]') || e.target.closest('[data-part="copy"]')) {
          return;
        }
        if (!this.collapsible) return;
        this.open = !this.open;
        this.dispatch('toggle', { open: this.open, name: this.name, status: this.status });
      });

      this.listen(header, 'keydown', (e) => {
        if (e.key === Keys.ENTER || e.key === Keys.SPACE || e.key === Keys.SPACEBAR) {
          e.preventDefault();
          if (this.collapsible) {
            this.open = !this.open;
            this.dispatch('toggle', { open: this.open, name: this.name, status: this.status });
          }
        }
      });
    }

    const retryBtn = this.querySelector('[data-part="retry"]');
    if (retryBtn) {
      this.listen(retryBtn, 'click', (e) => {
        e.stopPropagation();
        this.status = 'running';
        this.dispatch('retry', {
          name: this.name,
          args: this._getArgsContent(),
        });
      });
    }

    const copyBtn = this.querySelector('[data-part="copy"]');
    if (copyBtn) {
      this.listen(copyBtn, 'click', (e) => {
        e.stopPropagation();
        this._handleCopy();
      });
    }
  }

  async _handleCopy() {
    let args = this._getArgsContent();
    let output = this._getOutputContent();

    try {
      if (typeof args === 'string' && (args.startsWith('{') || args.startsWith('['))) {
        args = JSON.parse(args);
      }
    } catch {}

    try {
      if (typeof output === 'string' && (output.startsWith('{') || output.startsWith('['))) {
        output = JSON.parse(output);
      }
    } catch {}

    const payload = JSON.stringify({ name: this.name, status: this.status, latency: this.latency, args, output }, null, 2);

    try {
      if (typeof navigator !== 'undefined' && navigator.clipboard) {
        await navigator.clipboard.writeText(payload);
      }
      this._flashCopiedState();
      this.dispatch('copy', { payload });
    } catch {
      // Fallback
    }
  }

  _flashCopiedState() {
    const label = this.querySelector('[data-part="copy-label"]');
    if (!label) return;
    const prev = label.textContent;
    label.textContent = 'Copied!';
    setTimeout(() => {
      label.textContent = prev;
    }, 1600);
  }
}

import { BaseLightElement } from '../../utils/base-element.js';
import { Keys } from '../../utils/a11y.js';

/**
 * <ui-ai-approval> Micro-Enhancer
 * Accessible, platform-native Human-in-the-Loop (HITL) action governance in Light-DOM.
 * 
 * Features:
 * - Multi-tier risk severity classification: 'info', 'warning', 'critical'
 * - Dedicated payload & code diff inspection review slot
 * - Explicit Approve and Reject governance triggers dispatching 'approve' / 'reject'
 * - Settled audit state transition ('approved' / 'rejected')
 * - Built-in keyboard accessibility: 'A' or 'Enter' to approve, 'Escape' to reject
 * - 100% Light-DOM, zero Shadow DOM traps
 */
export class UiAiApproval extends BaseLightElement {
  static get observedAttributes() {
    return ['severity', 'status', 'action-name'];
  }

  get severity() {
    return this.getAttribute('severity') || 'warning';
  }

  set severity(val) {
    if (val) this.setAttributeSafe('severity', val);
    else this.removeAttributeSafe('severity');
  }

  get status() {
    return this.getAttribute('status') || 'pending';
  }

  set status(val) {
    if (val) this.setAttributeSafe('status', val);
    else this.removeAttributeSafe('status');
  }

  get actionName() {
    return this.getAttribute('action-name') || '';
  }

  set actionName(val) {
    if (val) this.setAttributeSafe('action-name', val);
    else this.removeAttributeSafe('action-name');
  }

  getAiState() {
    return {
      severity: this.severity,
      status: this.status,
      actionName: this.actionName,
      payloadContent: this._getPayloadContent(),
    };
  }

  init() {
    this.setAttributeSafe('data-ui', 'ai-approval');
    this.setAttributeSafe('role', 'alertdialog');
    this.setAttributeSafe('aria-labelledby', 'approval-heading');
    this.setAttributeSafe('tabindex', '0');

    this._scaffoldHeader();
    this._scaffoldActions();
    this._syncState();
    this._bindEvents();
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (!this._initialized || oldVal === newVal) return;
    this._syncState();
  }

  _getPayloadContent() {
    const el = this.querySelector('[data-part="payload"], [data-part="content"], [data-part="diff"]');
    return el ? el.textContent?.trim() || '' : '';
  }

  _scaffoldHeader() {
    let header = this.querySelector('[data-part="header"]');
    if (!header) {
      header = document.createElement('div');
      header.setAttribute('data-part', 'header');

      const titleGroup = document.createElement('div');
      titleGroup.setAttribute('data-part', 'title-group');

      const icon = document.createElement('span');
      icon.setAttribute('data-part', 'icon');
      icon.innerHTML = `
        <svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" fill="none" stroke-width="2.2">
          <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/>
        </svg>
      `;

      const heading = document.createElement('h5');
      heading.setAttribute('data-part', 'title');
      heading.setAttribute('id', 'approval-heading');
      heading.textContent = this.actionName || 'Action Authorization Required';

      titleGroup.appendChild(icon);
      titleGroup.appendChild(heading);

      const severityBadge = document.createElement('span');
      severityBadge.setAttribute('data-part', 'severity-badge');

      header.appendChild(titleGroup);
      header.appendChild(severityBadge);

      this.prepend(header);
    }
  }

  _scaffoldActions() {
    let actions = this.querySelector('[data-part="actions"]');
    if (!actions) {
      actions = document.createElement('div');
      actions.setAttribute('data-part', 'actions');

      const rejectBtn = document.createElement('button');
      rejectBtn.setAttribute('data-part', 'reject');
      rejectBtn.setAttribute('type', 'button');
      rejectBtn.innerHTML = `<span>✕ Reject Action</span>`;

      const approveBtn = document.createElement('button');
      approveBtn.setAttribute('data-part', 'approve');
      approveBtn.setAttribute('type', 'button');
      approveBtn.innerHTML = `<span>✓ Approve Action</span> <kbd>A</kbd>`;

      actions.appendChild(rejectBtn);
      actions.appendChild(approveBtn);

      this.appendChild(actions);
    }
  }

  _syncState() {
    this.setAttributeSafe('data-severity', this.severity);
    this.setAttributeSafe('data-status', this.status);

    const heading = this.querySelector('[data-part="title"]');
    if (heading && this.actionName) {
      heading.textContent = this.actionName;
    }

    const severityBadge = this.querySelector('[data-part="severity-badge"]');
    if (severityBadge) {
      severityBadge.setAttribute('data-severity', this.severity);
      switch (this.severity) {
        case 'critical':
          severityBadge.textContent = 'Critical Risk';
          break;
        case 'info':
          severityBadge.textContent = 'Standard Action';
          break;
        case 'warning':
        default:
          severityBadge.textContent = 'High Impact';
          break;
      }
    }

    const actions = this.querySelector('[data-part="actions"]');
    let auditBadge = this.querySelector('[data-part="audit-badge"]');

    if (this.status === 'approved') {
      if (actions) actions.style.display = 'none';
      if (!auditBadge) {
        auditBadge = document.createElement('div');
        auditBadge.setAttribute('data-part', 'audit-badge');
        auditBadge.setAttribute('data-status', 'approved');
        this.appendChild(auditBadge);
      }
      auditBadge.innerHTML = `✓ Approved by User`;
      auditBadge.style.display = 'flex';
    } else if (this.status === 'rejected') {
      if (actions) actions.style.display = 'none';
      if (!auditBadge) {
        auditBadge = document.createElement('div');
        auditBadge.setAttribute('data-part', 'audit-badge');
        auditBadge.setAttribute('data-status', 'rejected');
        this.appendChild(auditBadge);
      }
      auditBadge.innerHTML = `✕ Action Rejected by User`;
      auditBadge.style.display = 'flex';
    } else {
      if (actions) actions.style.display = 'flex';
      if (auditBadge) auditBadge.style.display = 'none';
    }
  }

  _bindEvents() {
    this.listen(this, 'click', (e) => {
      const approveBtn = e.target.closest('[data-part="approve"]');
      if (approveBtn) {
        e.stopPropagation();
        this.approve();
        return;
      }

      const rejectBtn = e.target.closest('[data-part="reject"]');
      if (rejectBtn) {
        e.stopPropagation();
        this.reject();
        return;
      }
    });

    this.listen(this, 'keydown', (e) => {
      if (this.status !== 'pending') return;

      // Ignore modifier combinations (e.g. Ctrl+A / Cmd+A select all text)
      if (e.ctrlKey || e.metaKey || e.altKey) return;

      // Ignore if event originated from an interactive input or editable field
      const targetTag = e.target?.tagName?.toLowerCase();
      if (targetTag === 'input' || targetTag === 'textarea' || targetTag === 'select' || e.target?.isContentEditable) {
        return;
      }

      if (e.key === 'a' || e.key === 'A') {
        e.preventDefault();
        this.approve();
      } else if (e.key === Keys.ESCAPE || e.key === 'r' || e.key === 'R') {
        e.preventDefault();
        this.reject();
      }
    });
  }

  approve() {
    if (this.status !== 'pending') return;
    this.status = 'approved';
    this.dispatch('approve', {
      action: this.actionName,
      severity: this.severity,
      payload: this._getPayloadContent(),
      timestamp: new Date().toISOString(),
    });
  }

  reject(reason = 'User declined action') {
    if (this.status !== 'pending') return;
    this.status = 'rejected';
    this.dispatch('reject', {
      action: this.actionName,
      severity: this.severity,
      reason,
      payload: this._getPayloadContent(),
      timestamp: new Date().toISOString(),
    });
  }
}
